const lessons = [
{num:1,time:"00:00:30,000 --> 00:00:33,240",arabic:"أَلَا تَجْلِسُ يَا رَجُلُ وَتَدَعُنَا نُفَكِّرُ بِهُدُوءٍ؟",segs:[{ar:"أَلَا تَجْلِسُ يَا رَجُلُ",uz:"O‘tirsang-chi, ey kishi"},{ar:"وَتَدَعُنَا نُفَكِّرُ بِهُدُوءٍ؟",uz:"bizga xotirjam o‘ylashga qo‘yib bersang-chi?"}],full_uz:"O‘tirsang-chi, ey kishi, bizga xotirjam o‘ylashga qo‘yib bersang-chi?",note:"أَلَا bu yerda taklif va undash bildiradi. وَدَعَ يَدَعُ — qo‘ymoq, tark etmoq."},
{num:2,time:"00:00:33,240 --> 00:00:44,219",arabic:"أَجْلِسُ وَبِهُدُوءٍ؟ لَا تَقْلَقِي، غَدًا سَنَجْلِسُ مَعًا نُحْصِي ذَرَّاتِ تُرَابِ أَرْضِ بَغْدَادَ بَعْدَ أَنْ بَاعَ أَحْمَدُ دُكَّانَهُ، لَا تَقْلَقِي.",segs:[{ar:"أَجْلِسُ وَبِهُدُوءٍ؟",uz:"Xotirjam o‘tiraymi?"},{ar:"لَا تَقْلَقِي،",uz:"xavotir olma"},{ar:"غَدًا سَنَجْلِسُ مَعًا",uz:"ertaga birga o‘tiramiz"},{ar:"نُحْصِي ذَرَّاتِ تُرَابِ أَرْضِ بَغْدَادَ",uz:"Bag‘dod yerining tuproq zarralarini sanab"},{ar:"بَعْدَ أَنْ بَاعَ أَحْمَدُ دُكَّانَهُ،",uz:"Ahmad do‘konini sotganidan keyin"},{ar:"لَا تَقْلَقِي.",uz:"xavotir olma."}],full_uz:"Xotirjam o‘tiraymi? Xavotir olma, Ahmad do‘konini sotganidan keyin ertaga birga o‘tirib, Bag‘dod yerining tuproq zarralarini sanaymiz. Xavotir olma.",note:"أَجْلِسُ — «men o‘tiraman»; اِجْلِسْ — «o‘tir». أَحْصَى يُحْصِي — birma-bir sanab chiqmoq."},
{num:3,time:"00:00:44,219 --> 00:00:49,780",arabic:"كَفَاكَ وَلْوَلَةً كَالنِّسَاءِ، اِجْلِسْ أَيُّهَا الْأَحْمَقُ وَدَعْنِي أُفَكِّرْ لَكَ فِي حَلٍّ.",segs:[{ar:"كَفَاكَ وَلْوَلَةً كَالنِّسَاءِ،",uz:"Ayollarga o‘xshab voy-voy qilishing yetar"},{ar:"اِجْلِسْ أَيُّهَا الْأَحْمَقُ",uz:"o‘tir, ey ahmoq"},{ar:"وَدَعْنِي أُفَكِّرْ لَكَ",uz:"sening uchun o‘ylashimga qo‘y"},{ar:"فِي حَلٍّ.",uz:"bir yechim haqida."}],full_uz:"Ayollarga o‘xshab voy-voy qilishing yetar. O‘tir, ey ahmoq, sening uchun bir yechim o‘ylashimga qo‘y.",note:"وَلْوَلَةٌ — voy-voylab yig‘lash. أُفَكِّرْ bu yerda buyruqning natijasi bo‘lgani uchun majzum."},
{num:4,time:"00:00:49,780 --> 00:00:53,000",arabic:"حَلٌّ؟ عَنْ أَيِّ حَلٍّ تَتَحَدَّثِينَ يَا أُمِّي؟",segs:[{ar:"حَلٌّ؟",uz:"Yechimmi?"},{ar:"عَنْ أَيِّ حَلٍّ تَتَحَدَّثِينَ",uz:"Qanday yechim haqida gapiryapsiz"},{ar:"يَا أُمِّي؟",uz:"onajon?"}],full_uz:"Yechimmi? Qanday yechim haqida gapiryapsiz, onajon?",note:null},
{num:5,time:"00:00:53,000 --> 00:00:58,579",arabic:"كُلَّمَا بَحَثْتِ لِي عَنْ حَلٍّ يَا أُمِّي جَاءَتْنِي الْمَصَائِبُ تَتْرَى.",segs:[{ar:"كُلَّمَا بَحَثْتِ لِي عَنْ حَلٍّ",uz:"Har safar menga yechim izlaganingizda"},{ar:"يَا أُمِّي",uz:"onajon"},{ar:"جَاءَتْنِي الْمَصَائِبُ تَتْرَى.",uz:"boshimga musibatlar ketma-ket keladi."}],full_uz:"Onajon, har safar menga yechim izlaganingizda boshimga musibatlar ketma-ket keladi.",note:"كُلَّمَا — har safar ...ganda. تَتْرَى — ketma-ket, biri ortidan biri."},
{num:6,time:"00:00:58,579 --> 00:01:00,679",arabic:"هَذَا جَزَاءُ مَنْ أَطَاعَ النِّسَاءَ.",segs:[{ar:"هَذَا جَزَاءُ",uz:"Bu jazosidir"},{ar:"مَنْ أَطَاعَ النِّسَاءَ.",uz:"ayollarga itoat qilgan kishining."}],full_uz:"Bu ayollarga itoat qilgan kishining jazosi.",note:"جَزَاءٌ vaziyatga qarab mukofot yoki jazo ma’nosida keladi."},
{num:7,time:"00:01:00,679 --> 00:01:03,179",arabic:"الرَّجُلُ يَا أُمِّي لَا يُرِيدُ بَيْعَ دُكَّانِهِ.",segs:[{ar:"الرَّجُلُ يَا أُمِّي",uz:"U kishi, onajon"},{ar:"لَا يُرِيدُ بَيْعَ دُكَّانِهِ.",uz:"do‘konini sotishni istamaydi."}],full_uz:"U kishi do‘konini sotishni istamaydi, onajon.",note:null},
{num:8,time:"00:01:03,179 --> 00:01:04,840",arabic:"مَا لِي وَلِدُكَّانِهِ؟",segs:null,full_uz:"Uning do‘koniga mening nima aloqam bor?",note:"مَا لِي وَلِـ؟ — mening ...bilan nima ishim bor?"},
{num:9,time:"00:01:04,840 --> 00:01:09,859",arabic:"أَوَلَمْ يَكْفِ أَنَّهُ لَمْ يَطْلُبْ مِنَّا أُجْرَةَ الدُّكَّانِ مُنْذُ أَشْهُرٍ،",segs:[{ar:"أَوَلَمْ يَكْفِ",uz:"Yetarli emasmidi"},{ar:"أَنَّهُ لَمْ يَطْلُبْ مِنَّا أُجْرَةَ الدُّكَّانِ",uz:"u bizdan do‘kon ijara haqini so‘ramagani"},{ar:"مُنْذُ أَشْهُرٍ،",uz:"bir necha oydan beri,"}],full_uz:"Bir necha oydan beri bizdan do‘kon ijara haqini so‘ramaganining o‘zi yetarli emasmidi…",note:"يَكْفِي fe’li لَمْ dan keyin oxirgi ي sini yo‘qotadi: يَكْفِ."},
{num:10,time:"00:01:09,859 --> 00:01:11,260",arabic:"رَأْفَةً بِحَالِنَا؟",segs:null,full_uz:"Holimizga rahm qilib?",note:"رَأْفَةً — sababni bildiruvchi masdar: rahm qilgani uchun."},
{num:11,time:"00:01:11,260 --> 00:01:13,960",arabic:"أَوَهَذَا جَزَاؤُهُ مِنَّا يَا أُمِّي؟",segs:[{ar:"أَوَهَذَا جَزَاؤُهُ مِنَّا",uz:"Bizdan oladigan javobi shumi"},{ar:"يَا أُمِّي؟",uz:"onajon?"}],full_uz:"Uning yaxshiligiga bizning javobimiz shumi, onajon?",note:null},
{num:12,time:"00:01:13,960 --> 00:01:15,620",arabic:"ذَلِكَ كُلُّهُ بِسَبَبِكَ.",segs:null,full_uz:"Bularning hammasi sen tufayli.",note:null},
{num:13,time:"00:01:15,620 --> 00:01:19,420",arabic:"لِمَ لَمْ تَدْفَعْ إِلَى الرَّجُلِ أُجْرَتَهُ إِلَى الْآنَ،",segs:[{ar:"لِمَ لَمْ تَدْفَعْ إِلَى الرَّجُلِ أُجْرَتَهُ",uz:"Nega u kishiga ijara haqini to‘lamading"},{ar:"إِلَى الْآنَ،",uz:"shu paytgacha,"}],full_uz:"Nega shu paytgacha u kishiga ijara haqini to‘lamading…",note:"لِمَ — nima uchun? لَمْ — o‘tgan zamondagi ishni inkor qilib, muzoriy fe’lni jazm qiladi."},
{num:14,time:"00:01:19,420 --> 00:01:21,400",arabic:"وَأَنْتَ تَمْلِكُ كُلَّ هَذِهِ النُّقُودِ؟",segs:null,full_uz:"Shuncha puling bo‘la turib?",note:"وَأَنْتَ ... — hol jumlasi: sen ... holingda, ...bo‘la turib."},
{num:15,time:"00:01:21,400 --> 00:01:24,680",arabic:"مَاذَا؟ مَاذَا تَقُولِينَ يَا سَلَمَةُ؟",segs:[{ar:"مَاذَا؟",uz:"Nima?"},{ar:"مَاذَا تَقُولِينَ يَا سَلَمَةُ؟",uz:"Nima deyapsan, Salama?"}],full_uz:"Nima? Nima deyapsan, Salama?",note:null},
{num:16,time:"00:01:24,680 --> 00:01:26,719",arabic:"الْآنَ أَصْبَحْتُ أَنَا الْمُخْطِئَ؟",segs:null,full_uz:"Endi aybdor men bo‘lib qoldimmi?",note:"الْمُخْطِئَ — أَصْبَحَ ning xabari bo‘lgani uchun mansub."},
{num:17,time:"00:01:26,719 --> 00:01:30,960",arabic:"مَنْ كَانَ يَرْسُمُ وَيُخَطِّطُ وَيَكِيدُ لِأَحْمَدَ وَدُكَّانِهِ؟",segs:[{ar:"مَنْ كَانَ يَرْسُمُ وَيُخَطِّطُ",uz:"Kim reja tuzib, o‘ylab chiqayotgan edi"},{ar:"وَيَكِيدُ لِأَحْمَدَ وَدُكَّانِهِ؟",uz:"Ahmad va uning do‘koniga qarshi hiyla qilayotgan edi?"}],full_uz:"Ahmad va uning do‘koniga qarshi kim reja tuzib, hiyla qilayotgan edi?",note:"كَادَ يَكِيدُ لِـ — ...ga qarshi hiyla qilmoq. Bu fe’l «sal qolmoq» ma’nosidagi كَادَ يَكَادُ dan boshqa."},
{num:18,time:"00:01:30,960 --> 00:01:33,540",arabic:"أَمْ تُرَاكُمْ قَدْ نَسِيتُمْ؟",segs:null,full_uz:"Yoki unutib qo‘ydingizlarmi?",note:"تُرَاكُمْ — taxmin yoki taajjubni ifodalovchi ibora: sizlar ...mikan?"},
{num:19,time:"00:01:33,540 --> 00:01:37,500",arabic:"كُفَّ عَنْ هَذَا الْجِدَالِ الْعَقِيمِ وَدَعْنَا نَجْلِسْ لِنُفَكِّرَ بِهُدُوءٍ.",segs:[{ar:"كُفَّ عَنْ هَذَا الْجِدَالِ الْعَقِيمِ",uz:"Bu befoyda bahsni bas qil"},{ar:"وَدَعْنَا نَجْلِسْ",uz:"o‘tirishimizga qo‘y"},{ar:"لِنُفَكِّرَ بِهُدُوءٍ.",uz:"xotirjam o‘ylashimiz uchun."}],full_uz:"Bu befoyda bahsni bas qil, xotirjam o‘ylash uchun o‘tirishimizga qo‘y.",note:"جِدَالٌ عَقِيمٌ — natijasiz, foydasiz bahs. كُفَّ عَنْ — ...ni bas qil."},
{num:20,time:"00:01:37,500 --> 00:01:40,280",arabic:"لَمْ يَعُدِ التَّفْكِيرُ يُجْدِي نَفْعًا يَا أُمِّي.",segs:[{ar:"لَمْ يَعُدِ التَّفْكِيرُ يُجْدِي نَفْعًا",uz:"Endi o‘ylash foyda bermaydi"},{ar:"يَا أُمِّي.",uz:"onajon."}],full_uz:"Endi o‘ylash foyda bermaydi, onajon.",note:"لَمْ يَعُدْ — endi ...emas. أَجْدَى يُجْدِي — foyda bermoq."},
{num:21,time:"00:01:40,280 --> 00:01:44,400",arabic:"وَعَلَيْنَا جَمِيعًا أَنْ نَتَحَمَّلَ جَزَاءَ خُبْثِنَا وَمَكْرِنَا.",segs:[{ar:"وَعَلَيْنَا جَمِيعًا أَنْ نَتَحَمَّلَ",uz:"Barchamiz ko‘tarishimiz kerak"},{ar:"جَزَاءَ خُبْثِنَا وَمَكْرِنَا.",uz:"yovuzligimiz va hiylamiz jazosini."}],full_uz:"Barchamiz yovuzligimiz va hiylamiz jazosini ko‘tarishimiz kerak.",note:"تَحَمَّلَ — ko‘tarmoq, chidamoq, oqibatni zimmasiga olmoq."},
{num:22,time:"00:01:51,400 --> 00:02:13,159",arabic:"مَا زِلْتَ غَاضِبًا؟",segs:null,full_uz:"Hali ham jahling chiqib turibdimi?",note:"مَا زَالَ — hali ham ...bo‘lmoq; xabari mansub: غَاضِبًا."},
{num:23,time:"00:02:13,159 --> 00:02:15,180",arabic:"كُنْتُ كَذَلِكَ.",segs:null,full_uz:"Shunday edim.",note:null},
{num:24,time:"00:02:15,180 --> 00:02:18,439",arabic:"تَغْضَبُ عَلَى أُمِّكَ؟",segs:null,full_uz:"Onangdan jahling chiqadimi?",note:null},
{num:25,time:"00:02:18,439 --> 00:02:20,000",arabic:"مَعَاذَ اللَّهِ يَا أُمَّ أَحْمَدَ.",segs:null,full_uz:"Alloh saqlasin, Umm Ahmad.",note:"مَعَاذَ اللَّهِ — bunday ish yoki fikrdan Allohga panoh so‘rash iborasi."},
{num:26,time:"00:02:20,000 --> 00:02:24,080",arabic:"إِنَّمَا أَثَارَ حَفِيظَتِي إِلْحَاحُ عَامِرٍ وَأَهْلِهِ،",segs:[{ar:"إِنَّمَا أَثَارَ حَفِيظَتِي",uz:"G‘azabimni faqat qo‘zg‘atdi"},{ar:"إِلْحَاحُ عَامِرٍ وَأَهْلِهِ،",uz:"Omir va oilasining qistovi,"}],full_uz:"G‘azabimni faqat Omir va oilasining qistovi qo‘zg‘atdi…",note:"أَثَارَ حَفِيظَتَهُ — uning g‘azabini qo‘zg‘atmoq. إِلْحَاحٌ — tinimsiz talab qilish, qistash."},
{num:27,time:"00:02:24,080 --> 00:02:27,300",arabic:"عَلَى أَمْرٍ يَرَوْنَ فِيهِ نَفْعَهُمْ وَنَرَى فِيهِ غَبْنَنَا.",segs:[{ar:"عَلَى أَمْرٍ",uz:"bir ishga"},{ar:"يَرَوْنَ فِيهِ نَفْعَهُمْ",uz:"ular bunda o‘z foydalarini ko‘radilar"},{ar:"وَنَرَى فِيهِ غَبْنَنَا.",uz:"biz esa zarar ko‘rishimizni."}],full_uz:"Ular o‘zlariga foydali, biz esa o‘zimizga zararli deb biladigan ishga qistashlari.",note:"غَبْنٌ — savdoda aldash yoki haqiqiy qiymatdan kam haq olib zarar ko‘rish."},
{num:28,time:"00:02:27,300 --> 00:02:34,520",arabic:"رُبَّمَا رَأَيْتُ أَنَّ بَيْعَ الدُّكَّانِ أَنْفَعُ لَنَا مِنْ كِرَائِهِ،",segs:[{ar:"رُبَّمَا رَأَيْتُ",uz:"Balki men ...deb bilgandirman"},{ar:"أَنَّ بَيْعَ الدُّكَّانِ أَنْفَعُ لَنَا",uz:"do‘konni sotish bizga foydaliroq"},{ar:"مِنْ كِرَائِهِ،",uz:"uni ijaraga berishdan,"}],full_uz:"Balki do‘konni sotish uni ijaraga berishdan bizga foydaliroq deb bilgandirman…",note:"كِرَاءٌ — ijara. أَنْفَعُ مِنْ — ...dan foydaliroq."},
{num:29,time:"00:02:34,520 --> 00:02:38,180",arabic:"وَلَكِنْ مَا دُمْتَ عَلَى غَيْرِ قَنَاعَةٍ،",segs:[{ar:"وَلَكِنْ مَا دُمْتَ",uz:"Ammo modomiki sen"},{ar:"عَلَى غَيْرِ قَنَاعَةٍ،",uz:"bunga ishonch hosil qilmagan ekansan,"}],full_uz:"Ammo modomiki sen bunga ishonch hosil qilmagan ekansan…",note:"قَنَاعَةٌ bu yerda bir fikrning to‘g‘riligiga ichki ishonch, unga ko‘nish."},
{num:30,time:"00:02:38,180 --> 00:02:41,000",arabic:"فَالْأَمْرُ زِمَامُهُ بَيْنَ يَدَيْكَ.",segs:[{ar:"فَالْأَمْرُ زِمَامُهُ",uz:"unda ishning jilovi"},{ar:"بَيْنَ يَدَيْكَ.",uz:"sening qo‘lingda."}],full_uz:"Unda ishning jilovi sening qo‘lingda.",note:"زِمَامُ الْأَمْرِ — ishni boshqarish vakolati; so‘zma-so‘z «ishning jilovi»."},
{num:31,time:"00:02:41,000 --> 00:02:44,020",arabic:"وَالدُّكَّانُ دُكَّانُكَ وَدُكَّانُ أَبِيكَ.",segs:[{ar:"وَالدُّكَّانُ دُكَّانُكَ",uz:"Do‘kon sening do‘koning"},{ar:"وَدُكَّانُ أَبِيكَ.",uz:"va otangning do‘koni."}],full_uz:"Do‘kon seniki va otangniki.",note:null},
{num:32,time:"00:02:44,020 --> 00:02:46,539",arabic:"جَزَاكِ اللَّهُ خَيْرًا يَا أُمِّي.",segs:[{ar:"جَزَاكِ اللَّهُ خَيْرًا",uz:"Alloh sizni yaxshilik bilan mukofotlasin"},{ar:"يَا أُمِّي.",uz:"onajon."}],full_uz:"Alloh sizni yaxshilik bilan mukofotlasin, onajon.",note:null},
{num:33,time:"00:02:46,539 --> 00:02:48,560",arabic:"أَنَا وَمَا أَمْلِكُ طَوْعُ أَمْرِكِ.",segs:[{ar:"أَنَا وَمَا أَمْلِكُ",uz:"Men va bor mol-mulkim"},{ar:"طَوْعُ أَمْرِكِ.",uz:"sizning amringizga tayyor."}],full_uz:"Men va bor mol-mulkim sizning amringizga tayyor.",note:"طَوْعُ أَمْرِكَ — buyrug‘ingizga itoatda, xizmatingizga tayyor."},
{num:34,time:"00:02:48,560 --> 00:02:52,379",arabic:"اِفْعَلْ مَا تَرَاهُ مُنَاسِبًا يَا وَلَدِي.",segs:[{ar:"اِفْعَلْ مَا تَرَاهُ مُنَاسِبًا",uz:"Ma’qul deb bilganingni qil"},{ar:"يَا وَلَدِي.",uz:"o‘g‘lim."}],full_uz:"Ma’qul deb bilganingni qil, o‘g‘lim.",note:"تَرَاهُ bu yerda ko‘z bilan ko‘rish emas, fikran baholash ma’nosida."},
{num:35,time:"00:03:15,980 --> 00:03:18,539",arabic:"مَا بِكِ؟",segs:null,full_uz:"Sizga nima bo‘ldi?",note:null},
{num:36,time:"00:03:18,539 --> 00:03:23,739",arabic:"أَثَمَّ مَا تُخْفِينَهُ عَنِّي؟",segs:[{ar:"أَثَمَّ",uz:"Bormi"},{ar:"مَا تُخْفِينَهُ عَنِّي؟",uz:"mendan yashirayotgan narsangiz?"}],full_uz:"Mendan yashirayotgan narsangiz bormi?",note:"ثَمَّ — u yerda, bor; ثُمَّ — keyin. So‘roq hamzasi bilan أَثَمَّ — bormi?"},
{num:37,time:"00:03:23,739 --> 00:03:27,639",arabic:"وَمَا الَّذِي أُخْفِيهِ عَنْكِ يَا ابْنَتِي؟",segs:[{ar:"وَمَا الَّذِي أُخْفِيهِ عَنْكِ",uz:"Sendan nimani yashirayotgan ekanman"},{ar:"يَا ابْنَتِي؟",uz:"qizim?"}],full_uz:"Sendan nimani yashirayotgan ekanman, qizim?",note:null},
{num:38,time:"00:03:27,639 --> 00:03:29,340",arabic:"أَسْتَحْلِفُكِ بِاللَّهِ يَا عَمَّتِي.",segs:[{ar:"أَسْتَحْلِفُكِ بِاللَّهِ",uz:"Sizdan Alloh nomi bilan qasam so‘rayman"},{ar:"يَا عَمَّتِي.",uz:"ammajon."}],full_uz:"Alloh haqqi, rostini ayting, ammajon.",note:"اِسْتَحْلَفَ — birovdan qasam ichishni so‘ramoq; bu yerda rostini aytishni qat’iy iltimos qilish."},
{num:39,time:"00:03:29,340 --> 00:03:32,180",arabic:"مُحَمَّدٌ بِخَيْرٍ؟",segs:null,full_uz:"Muhammad yaxshimi?",note:null},
{num:40,time:"00:03:32,180 --> 00:03:34,439",arabic:"مَا دَامَ رَبُّهُ يَرْعَاهُ،",segs:null,full_uz:"Modomiki Rabbi uni asrayotgan ekan…",note:"رَعَى يَرْعَى — asramoq, g‘amxo‘rlik qilmoq."},
{num:41,time:"00:03:34,439 --> 00:03:36,979",arabic:"فَهُوَ بِخَيْرٍ إِنْ شَاءَ اللَّهُ.",segs:[{ar:"فَهُوَ بِخَيْرٍ",uz:"u yaxshidir"},{ar:"إِنْ شَاءَ اللَّهُ.",uz:"Alloh xohlasa."}],full_uz:"Alloh xohlasa, u yaxshidir.",note:null},
{num:42,time:"00:03:36,979 --> 00:03:39,439",arabic:"لَا تَقْلَقِي يَا ابْنَتِي.",segs:null,full_uz:"Xavotir olma, qizim.",note:null},
{num:43,time:"00:03:39,439 --> 00:03:41,259",arabic:"لَا تَقْلَقِي بِشَأْنِهِ.",segs:null,full_uz:"U haqida xavotir olma.",note:"بِشَأْنِهِ — u haqida, uning holati borasida."},
{num:44,time:"00:03:41,259 --> 00:03:44,799",arabic:"كَيْفَ لَا أَقْلَقُ عَلَيْهِ وَأَنَا أَرَاكِ مَشْغُولَةً عَلَيْهِ؟",segs:[{ar:"كَيْفَ لَا أَقْلَقُ عَلَيْهِ",uz:"Qanday qilib undan xavotir olmay"},{ar:"وَأَنَا أَرَاكِ مَشْغُولَةً عَلَيْهِ؟",uz:"sizning ham u uchun tashvishlanayotganingizni ko‘rib turib?"}],full_uz:"Sizning ham u uchun tashvishlanayotganingizni ko‘rib turib, qanday qilib undan xavotir olmay?",note:"مَشْغُولَةٌ عَلَيْهِ bu suhbatda bir kishining holatini o‘ylab tashvishlanayotganlikni bildiradi."},
{num:45,time:"00:03:44,799 --> 00:03:47,180",arabic:"وَأَرَاكِ تَكْتُمِينَ انْشِغَالَكِ.",segs:[{ar:"وَأَرَاكِ",uz:"Sizning ...ingizni ko‘ryapman"},{ar:"تَكْتُمِينَ انْشِغَالَكِ.",uz:"tashvishingizni yashirayotganingizni."}],full_uz:"Tashvishingizni yashirayotganingizni ko‘ryapman.",note:"كَتَمَ — yashirmoq, ichida saqlamoq."},
{num:46,time:"00:03:47,180 --> 00:03:51,140",arabic:"عَمَّتِي، أَثَمَّ مَا يَجِبُ أَنْ أَعْرِفَهُ؟",segs:[{ar:"عَمَّتِي،",uz:"Ammajon"},{ar:"أَثَمَّ مَا يَجِبُ أَنْ أَعْرِفَهُ؟",uz:"men bilishim kerak bo‘lgan narsa bormi?"}],full_uz:"Ammajon, men bilishim kerak bo‘lgan narsa bormi?",note:null},
{num:47,time:"00:03:51,140 --> 00:03:54,099",arabic:"فَأَنَا ابْنَتُكِ وَزَوْجَةُ مُحَمَّدٍ.",segs:[{ar:"فَأَنَا ابْنَتُكِ",uz:"Axir men qizingizman"},{ar:"وَزَوْجَةُ مُحَمَّدٍ.",uz:"va Muhammadning xotiniman."}],full_uz:"Axir men qizingiz va Muhammadning xotiniman.",note:null},
{num:48,time:"00:03:54,099 --> 00:03:59,219",arabic:"رُبَّمَا سَرَتْ إِلَيَّ عَدْوَى هَوَاجِسِكِ يَا حَمْدَةُ.",segs:[{ar:"رُبَّمَا سَرَتْ إِلَيَّ",uz:"Balki menga ham yuqqandir"},{ar:"عَدْوَى هَوَاجِسِكِ",uz:"sening xavotirlaring"},{ar:"يَا حَمْدَةُ.",uz:"ey Hamda."}],full_uz:"Balki sening xavotirlaring menga ham yuqqandir, Hamda.",note:"سَرَتْ — tarqaldi, o‘tdi. عَدْوَى — yuqish; bu yerda xavotirning bir kishidan boshqasiga o‘tishi tasvirlangan."},
{num:49,time:"00:03:59,219 --> 00:04:04,260",arabic:"قُلْتُ لَكِ: فَوِّضِي أَمْرَكِ إِلَى اللَّهِ وَهُوَ حَسْبُنَا.",segs:[{ar:"قُلْتُ لَكِ:",uz:"Senga aytdim"},{ar:"فَوِّضِي أَمْرَكِ إِلَى اللَّهِ",uz:"ishingni Allohga topshir"},{ar:"وَهُوَ حَسْبُنَا.",uz:"U bizga kifoya."}],full_uz:"Senga aytdim: ishingni Allohga topshir, U bizga kifoya.",note:"فَوَّضَ أَمْرَهُ إِلَى — ishini, uning natijasini ...ga topshirmoq. حَسْبُنَا — bizga kifoya qiluvchi."},
{num:50,time:"00:04:04,260 --> 00:04:06,540",arabic:"الْحَمْدُ لِلَّهِ.",segs:null,full_uz:"Allohga hamd bo‘lsin.",note:null},
{num:51,time:"00:04:06,540 --> 00:04:08,560",arabic:"تَفَضَّلِي يَا عَمَّتِي.",segs:null,full_uz:"Marhamat, ammajon.",note:null},
{num:52,time:"00:04:08,560 --> 00:04:09,659",arabic:"تَفَضَّلِي.",segs:null,full_uz:"Marhamat.",note:"تَفَضَّلِي — ayolga, تَفَضَّلْ — erkakka aytiladi."},
{num:53,time:"00:04:17,180 --> 00:04:37,620",arabic:"لَا بُدَّ أَنَّهُمْ فِي غَايَةِ الْقَلَقِ عَلَيَّ.",segs:[{ar:"لَا بُدَّ أَنَّهُمْ",uz:"Shubhasiz, ular"},{ar:"فِي غَايَةِ الْقَلَقِ عَلَيَّ.",uz:"mendan nihoyatda xavotirdalar."}],full_uz:"Shubhasiz, ular mendan nihoyatda xavotirdalar.",note:"لَا بُدَّ أَنَّ — shubhasiz, ...bo‘lsa kerak. فِي غَايَةِ — nihoyatda, eng yuqori darajada."},
{num:54,time:"00:04:37,620 --> 00:04:42,699",arabic:"وَمَا دُمْتُ لَا أَسْتَطِيعُ الذَّهَابَ إِلَيْهِمْ،",segs:[{ar:"وَمَا دُمْتُ لَا أَسْتَطِيعُ",uz:"Modomiki men qodir emas ekanman"},{ar:"الذَّهَابَ إِلَيْهِمْ،",uz:"ularning oldiga borishga,"}],full_uz:"Modomiki ularning oldiga bora olmas ekanman…",note:null},
{num:55,time:"00:04:42,699 --> 00:04:45,699",arabic:"إِلَّا بِإِذْنِ وَلِيِّ أَمْرِ الْمُؤْمِنِينَ،",segs:null,full_uz:"Mo‘minlar hukmdorining ruxsatisiz…",note:"Oldingi inkor bilan birga «faqat mo‘minlar hukmdorining ruxsati bilan bora olaman» ma’nosi kelib chiqadi."},
{num:56,time:"00:04:45,699 --> 00:04:52,259",arabic:"فَيَجِبُ أَنْ أُرْسِلَ إِلَيْهِمْ رَسُولًا لِيُذْهِبَ قَلَقَهُمْ.",segs:[{ar:"فَيَجِبُ أَنْ أُرْسِلَ إِلَيْهِمْ رَسُولًا",uz:"ularga bir elchi yuborishim kerak"},{ar:"لِيُذْهِبَ قَلَقَهُمْ.",uz:"xavotirlarini ketkazishi uchun."}],full_uz:"Xavotirlarini ketkazishi uchun ularga bir elchi yuborishim kerak.",note:"رَسُولٌ bu yerda elchi, xabar yetkazuvchi. أَذْهَبَ — ketkazmoq; ذَهَبَ — ketmoq."},
{num:57,time:"00:04:52,259 --> 00:04:58,219",arabic:"فَقَدْ كَادَ شَوْقِي لَهُمْ يَفْتِكُ بِي.",segs:[{ar:"فَقَدْ كَادَ شَوْقِي لَهُمْ",uz:"Ularga bo‘lgan sog‘inchim sal bo‘lmasa"},{ar:"يَفْتِكُ بِي.",uz:"meni halok qilay dedi."}],full_uz:"Ularga bo‘lgan sog‘inchim sal bo‘lmasa meni halok qilay dedi.",note:"فَتَكَ بِهِ — uni halok qilmoq; bu yerda sog‘inchning kuchini ifodalaydi."},
{num:58,time:"00:05:45,699 --> 00:06:04,800",arabic:"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",segs:[{ar:"السَّلَامُ عَلَيْكُمْ",uz:"Sizlarga salom bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",uz:"va Allohning rahmati hamda barakalari."}],full_uz:"Sizlarga salom, Allohning rahmati va barakalari bo‘lsin.",note:null},
{num:59,time:"00:06:04,800 --> 00:06:08,919",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"Sizlarga ham salom bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",uz:"va Allohning rahmati hamda barakalari."}],full_uz:"Sizlarga ham salom, Allohning rahmati va barakalari bo‘lsin.",note:null},
{num:60,time:"00:06:08,919 --> 00:06:09,719",arabic:"تَفَضَّلْ.",segs:null,full_uz:"Marhamat.",note:null},
{num:61,time:"00:06:09,719 --> 00:06:14,740",arabic:"أَهْلًا بِقَاضِي قُضَاةِ بَغْدَادَ مُحَمَّدِ بْنِ الْحَسَنِ الشَّيْبَانِيِّ.",segs:[{ar:"أَهْلًا بِقَاضِي قُضَاةِ بَغْدَادَ",uz:"Xush kelibsiz, Bag‘dod qozikaloni"},{ar:"مُحَمَّدِ بْنِ الْحَسَنِ الشَّيْبَانِيِّ.",uz:"Muhammad ibn Hasan Shayboniy."}],full_uz:"Xush kelibsiz, Bag‘dod qozikaloni Muhammad ibn Hasan Shayboniy.",note:"قَاضِي الْقُضَاةِ — qozilar boshlig‘i, qozikalon."},
{num:62,time:"00:06:14,740 --> 00:06:20,639",arabic:"أَهْلًا بِكَ، أَهْلًا بِكَ أَيُّهَا الشَّافِعِيُّ، قَدْ وَجَبَتْ عَلَيْنَا زِيَارَتُكَ.",segs:[{ar:"أَهْلًا بِكَ، أَهْلًا بِكَ أَيُّهَا الشَّافِعِيُّ،",uz:"Salomat bo‘ling, salomat bo‘ling, ey Shofe’iy"},{ar:"قَدْ وَجَبَتْ عَلَيْنَا زِيَارَتُكَ.",uz:"sizni ziyorat qilish bizning burchimiz bo‘ldi."}],full_uz:"Salomat bo‘ling, ey Shofe’iy. Sizni ziyorat qilish bizning burchimiz bo‘ldi.",note:"وَجَبَ عَلَيْنَا — zimmamizga burch bo‘ldi. زِيَارَتُكَ bu yerda «sizni ziyorat qilish»."},
{num:63,time:"00:06:20,639 --> 00:06:24,519",arabic:"حَلَلْتَ أَهْلًا وَنَزَلْتَ سَهْلًا يَا أَبَا عَبْدِ اللَّهِ، تَفَضَّلْ.",segs:[{ar:"حَلَلْتَ أَهْلًا",uz:"O‘z yaqinlaringiz orasiga keldingiz"},{ar:"وَنَزَلْتَ سَهْلًا",uz:"va qulay joyga tushdingiz"},{ar:"يَا أَبَا عَبْدِ اللَّهِ،",uz:"ey Abu Abdulloh"},{ar:"تَفَضَّلْ.",uz:"marhamat."}],full_uz:"Xush kelibsiz, o‘z yaqinlaringiz orasiga, qulay joyga keldingiz, Abu Abdulloh. Marhamat.",note:"حَلَلْتَ أَهْلًا وَنَزَلْتَ سَهْلًا — mehmonni iliq kutib olish iborasi."},
{num:64,time:"00:06:24,519 --> 00:06:31,660",arabic:"إِلَى مَتَى يَتَغَافَلُ مَوْلَاكَ يَا ابْنَ الرَّبِيعِ عَنْ تَجَاوُزَاتِ أَبْنَاءِ بَرْمَكٍ فِي شُؤُونِ الْخِلَافَةِ؟",segs:[{ar:"إِلَى مَتَى يَتَغَافَلُ مَوْلَاكَ",uz:"Hazrating qachongacha ko‘rmaganga oladi"},{ar:"يَا ابْنَ الرَّبِيعِ",uz:"ey Ibn Rabi’"},{ar:"عَنْ تَجَاوُزَاتِ أَبْنَاءِ بَرْمَكٍ",uz:"Barmak avlodining haddan oshishlarini"},{ar:"فِي شُؤُونِ الْخِلَافَةِ؟",uz:"xalifalik ishlarida?"}],full_uz:"Ibn Rabi’, hazrating Barmak avlodining xalifalik ishlaridagi haddan oshishlarini qachongacha ko‘rmaganga oladi?",note:"تَغَافَلَ عَنْ — bilib turib bexabardek tutmoq, ko‘rmaganga olmoq."},
{num:65,time:"00:06:31,660 --> 00:06:38,460",arabic:"لَا أَدْرِي يَا مَوْلَاتِي، إِنَّ أَحَدًا لَا يَقْوَى عَلَى الْحَدِيثِ مَعَ أَمِيرِ الْمُؤْمِنِينَ بِشَأْنِ الْبَرَامِكَةِ.",segs:[{ar:"لَا أَدْرِي يَا مَوْلَاتِي،",uz:"Bilmayman, bekam"},{ar:"إِنَّ أَحَدًا لَا يَقْوَى عَلَى الْحَدِيثِ",uz:"hech kim gaplashishga jur’at qilolmaydi"},{ar:"مَعَ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri bilan"},{ar:"بِشَأْنِ الْبَرَامِكَةِ.",uz:"Barmakiylar haqida."}],full_uz:"Bilmayman, bekam. Hech kim mo‘minlar amiri bilan Barmakiylar haqida gaplashishga jur’at qilolmaydi.",note:"قَوِيَ عَلَى — bir ishga kuchi yetmoq; bu yerda jur’at eta olish. مَوْلَاتِي — ayol hukmdor yoki bekaga murojaat."},
{num:66,time:"00:06:38,460 --> 00:06:43,220",arabic:"فَأَمِيرُ الْمُؤْمِنِينَ لَا يَرْضَى أَنْ يَنَالَهُمْ أَحَدٌ وَلَوْ بِكَلِمَةٍ تُقَالُ.",segs:[{ar:"فَأَمِيرُ الْمُؤْمِنِينَ لَا يَرْضَى",uz:"Mo‘minlar amiri rozi bo‘lmaydi"},{ar:"أَنْ يَنَالَهُمْ أَحَدٌ",uz:"biror kishining ularga til tekkizishiga"},{ar:"وَلَوْ بِكَلِمَةٍ تُقَالُ.",uz:"hatto bir og‘iz so‘z bilan bo‘lsa ham."}],full_uz:"Mo‘minlar amiri biror kishining ularga hatto bir og‘iz so‘z bilan til tekkizishiga ham rozi bo‘lmaydi.",note:"نَالَ مِنْهُ — unga til tekkizmoq, uni yomonlamoq; bu yerda نَالَهُمْ shu mazmunda."},
{num:67,time:"00:06:43,220 --> 00:06:46,840",arabic:"أَمِيرُ الْمُؤْمِنِينَ يَسُوسُ بِعَقْلِهِ وَحِكْمَتِهِ،",segs:[{ar:"أَمِيرُ الْمُؤْمِنِينَ يَسُوسُ",uz:"Mo‘minlar amiri boshqaradi"},{ar:"بِعَقْلِهِ وَحِكْمَتِهِ،",uz:"aqli va hikmati bilan,"}],full_uz:"Mo‘minlar amiri aqli va hikmati bilan boshqaradi…",note:"سَاسَ يَسُوسُ — boshqarmoq, idora qilmoq."},
{num:68,time:"00:06:46,840 --> 00:06:51,480",arabic:"وَلَا يَرْضَى أَنْ يَتَوَغَّلَ أَحَدٌ فِي شُؤُونِ الْحُكْمِ وَالْخِلَافَةِ مَهْمَا كَانَ.",segs:[{ar:"وَلَا يَرْضَى أَنْ يَتَوَغَّلَ أَحَدٌ",uz:"Biror kishining chuqur aralashishiga rozi bo‘lmaydi"},{ar:"فِي شُؤُونِ الْحُكْمِ وَالْخِلَافَةِ",uz:"boshqaruv va xalifalik ishlariga"},{ar:"مَهْمَا كَانَ.",uz:"kim bo‘lishidan qat’i nazar."}],full_uz:"Kim bo‘lishidan qat’i nazar, biror kishining boshqaruv va xalifalik ishlariga chuqur aralashishiga rozi bo‘lmaydi.",note:"تَوَغَّلَ فِي — ichkarilab kirmoq, chuqur aralashmoq."},
{num:69,time:"00:06:51,480 --> 00:06:54,920",arabic:"فَزِمَامُ الدَّوْلَةِ كُلِّهَا فِي يَدِهِ.",segs:[{ar:"فَزِمَامُ الدَّوْلَةِ كُلِّهَا",uz:"Butun davlatning jilovi"},{ar:"فِي يَدِهِ.",uz:"uning qo‘lida."}],full_uz:"Butun davlatning jilovi uning qo‘lida.",note:null},
{num:70,time:"00:06:54,920 --> 00:06:58,200",arabic:"وَلَكِنَّ آلَ بَرْمَكٍ قَدْ بَلَغُوا مِنَ الْأَمْرِ غَايَتَهُ،",segs:[{ar:"وَلَكِنَّ آلَ بَرْمَكٍ",uz:"Ammo Barmak xonadoni"},{ar:"قَدْ بَلَغُوا مِنَ الْأَمْرِ غَايَتَهُ،",uz:"ishda eng chekka chegaraga yetdi,"}],full_uz:"Ammo Barmak xonadoni bu ishda eng chekka chegaraga yetdi…",note:"آلُ — xonadon, sulola. بَلَغَ غَايَتَهُ — oxirgi chegarasiga yetmoq."},
{num:71,time:"00:06:58,200 --> 00:07:03,540",arabic:"فَقَدِ اسْتَأْثَرُوا لِأَنْفُسِهِمْ وَأَتْبَاعِهِمْ بِمُقَدَّرَاتِ الدَّوْلَةِ وَشُؤُونِهَا.",segs:[{ar:"فَقَدِ اسْتَأْثَرُوا",uz:"Ular o‘zlariga egallab oldilar"},{ar:"لِأَنْفُسِهِمْ وَأَتْبَاعِهِمْ",uz:"o‘zlari va izdoshlari uchun"},{ar:"بِمُقَدَّرَاتِ الدَّوْلَةِ وَشُؤُونِهَا.",uz:"davlat boyliklari va ishlarini."}],full_uz:"Ular davlat boyliklari va ishlarini o‘zlari hamda izdoshlari uchun egallab oldilar.",note:"اِسْتَأْثَرَ بِـ — boshqalarga bermay, o‘ziga xoslab egallamoq. مُقَدَّرَاتُ الدَّوْلَةِ — davlatning boyliklari va imkoniyatlari."},
{num:72,time:"00:07:03,540 --> 00:07:09,540",arabic:"وَلَيْسَ أَدَلَّ عَلَى ذَلِكَ مِنْ أَنَّ نَفَقَةَ الْبَرَامِكَةِ تَفُوقُ نَفَقَةَ أَمِيرِ الْمُؤْمِنِينَ نَفْسِهِ.",segs:[{ar:"وَلَيْسَ أَدَلَّ عَلَى ذَلِكَ",uz:"Bunga kuchliroq dalil yo‘q"},{ar:"مِنْ أَنَّ نَفَقَةَ الْبَرَامِكَةِ",uz:"Barmakiylarning xarajatlari"},{ar:"تَفُوقُ نَفَقَةَ أَمِيرِ الْمُؤْمِنِينَ نَفْسِهِ.",uz:"mo‘minlar amirining o‘z xarajatlaridan ham oshishidan."}],full_uz:"Barmakiylarning xarajatlari mo‘minlar amirining o‘z xarajatlaridan oshishi bunga eng kuchli dalildir.",note:"أَدَلُّ عَلَى — ...ni kuchliroq ko‘rsatuvchi. فَاقَ يَفُوقُ — oshmoq, ustun kelmoq."},
{num:73,time:"00:07:09,540 --> 00:07:15,120",arabic:"ثُمَّ هَا هُمْ الْآنَ يَلْتَفُّونَ حَوْلَ ابْنِهِ عَبْدِ اللَّهِ الْمَأْمُونِ،",segs:[{ar:"ثُمَّ هَا هُمْ الْآنَ يَلْتَفُّونَ",uz:"Endi mana, ular o‘ralashib yuribdilar"},{ar:"حَوْلَ ابْنِهِ عَبْدِ اللَّهِ الْمَأْمُونِ،",uz:"uning o‘g‘li Abdulloh Ma’munning atrofida,"}],full_uz:"Endi mana, ular uning o‘g‘li Abdulloh Ma’munning atrofida o‘ralashib yuribdilar…",note:"اِلْتَفَّ حَوْلَ — atrofida to‘planmoq, o‘ralashmoq."},
{num:74,time:"00:07:15,120 --> 00:07:18,060",arabic:"الْتِفَافَ الْحَيَّةِ عَلَى فَرَائِسِهَا.",segs:null,full_uz:"Ilon o‘ljalariga o‘ralgandek.",note:"الْتِفَافَ — oldingi fe’lning qanday bajarilishini bildiruvchi masdar. فَرَائِسُ — فَرِيسَةٌ ning ko‘pligi: o‘ljalar."},
{num:75,time:"00:07:18,060 --> 00:07:23,000",arabic:"وَأَخْشَى أَنَّ هُنَاكَ مَنْ يَكِيدُ فِي الْخَفَاءِ.",segs:[{ar:"وَأَخْشَى أَنَّ هُنَاكَ",uz:"Xavotirdamanki, bor"},{ar:"مَنْ يَكِيدُ فِي الْخَفَاءِ.",uz:"yashirincha fitna qilayotgan kishi."}],full_uz:"Yashirincha fitna qilayotgan kishi borligidan xavotirdaman.",note:"فِي الْخَفَاءِ — yashirincha, pinhona."},
{num:76,time:"00:07:25,680 --> 00:07:28,720",arabic:"إِنَّ دَوْلَةَ الْخِلَافَةِ فِي خَطَرٍ.",segs:null,full_uz:"Xalifalik davlati xavf ostida.",note:null},
{num:77,time:"00:07:28,720 --> 00:07:33,759",arabic:"أُثَنِّي عَلَى كَلَامِ ابْنِ الرَّبِيعِ يَا مَوْلَاتِي،",segs:[{ar:"أُثَنِّي عَلَى كَلَامِ ابْنِ الرَّبِيعِ",uz:"Ibn Rabi’ning gapini qo‘llab-quvvatlayman"},{ar:"يَا مَوْلَاتِي،",uz:"bekam,"}],full_uz:"Ibn Rabi’ning gapini qo‘llab-quvvatlayman, bekam…",note:"ثَنَّى عَلَى كَلَامِهِ — uning fikrini qo‘llab-quvvatlamoq; أَثْنَى عَلَيْهِ — uni maqtamoq."},
{num:78,time:"00:07:33,759 --> 00:07:38,020",arabic:"بِأَنَّهُمْ أَحَاطُوا الْمَأْمُونَ بِأَعْوَانِهِمْ وَعُيُونِهِمْ،",segs:[{ar:"بِأَنَّهُمْ أَحَاطُوا الْمَأْمُونَ",uz:"ular Ma’munning atrofini o‘rab olishgan"},{ar:"بِأَعْوَانِهِمْ وَعُيُونِهِمْ،",uz:"yordamchilari va josuslari bilan,"}],full_uz:"Ular Ma’munning atrofini o‘z yordamchilari va josuslari bilan o‘rab olishgan…",note:"عُيُونٌ aslida «ko‘zlar»; bu yerda yashirin kuzatuvchilar, josuslar."},
{num:79,time:"00:07:38,019 --> 00:07:43,039",arabic:"وَلَا سِيَّمَا ذَلِكَ الدَّاهِيَةُ الْمُسَمَّى الْفَضْلَ بْنَ سَهْلٍ.",segs:[{ar:"وَلَا سِيَّمَا ذَلِكَ الدَّاهِيَةُ",uz:"ayniqsa o‘sha o‘ta ayyor kishi"},{ar:"الْمُسَمَّى الْفَضْلَ بْنَ سَهْلٍ.",uz:"Fazl ibn Sahl deb ataladigan."}],full_uz:"Ayniqsa Fazl ibn Sahl deb ataladigan o‘sha o‘ta ayyor kishi.",note:"لَا سِيَّمَا — ayniqsa. دَاهِيَةٌ erkakka nisbatan ham o‘ta ziyrak, ayyor kishi ma’nosida ishlatiladi."},
{num:80,time:"00:07:43,039 --> 00:07:44,779",arabic:"اِسْمَعْ يَا أَبَا الْعَبَّاسِ.",segs:null,full_uz:"Quloq sol, Abu Abbos.",note:null},
{num:81,time:"00:07:44,779 --> 00:07:47,500",arabic:"كُلِّي آذَانٌ مُصْغِيَةٌ يَا مَوْلَاتِي.",segs:[{ar:"كُلِّي آذَانٌ مُصْغِيَةٌ",uz:"Butun vujudim bilan tinglayapman"},{ar:"يَا مَوْلَاتِي.",uz:"bekam."}],full_uz:"Butun vujudim bilan tinglayapman, bekam.",note:"كُلِّي آذَانٌ مُصْغِيَةٌ — so‘zma-so‘z «borlig‘im tinglovchi quloqlar»; diqqat bilan eshitishga tayyorlik iborasi."},
{num:82,time:"00:07:47,500 --> 00:07:51,579",arabic:"إِنْ كَانَتِ الْأُمُورُ كَمَا ذَكَرْتُمْ فَإِنَّ ذَلِكَ لَا يُنْبِئُ بِخَيْرٍ.",segs:[{ar:"إِنْ كَانَتِ الْأُمُورُ كَمَا ذَكَرْتُمْ",uz:"Agar ishlar sizlar aytgandek bo‘lsa"},{ar:"فَإِنَّ ذَلِكَ لَا يُنْبِئُ بِخَيْرٍ.",uz:"bu yaxshilikdan darak bermaydi."}],full_uz:"Agar ishlar sizlar aytgandek bo‘lsa, bu yaxshilikdan darak bermaydi.",note:"أَنْبَأَ بِـ — xabar bermoq, darak bermoq."},
{num:83,time:"00:07:51,579 --> 00:07:56,500",arabic:"وَيَجِبُ أَنْ نَجِدَ حَلًّا بِسُرْعَةٍ قَبْلَ أَنْ تَغْرَقَ السَّفِينَةُ.",segs:[{ar:"وَيَجِبُ أَنْ نَجِدَ حَلًّا بِسُرْعَةٍ",uz:"Tezda yechim topishimiz kerak"},{ar:"قَبْلَ أَنْ تَغْرَقَ السَّفِينَةُ.",uz:"kema cho‘kib ketishidan oldin."}],full_uz:"Kema cho‘kib ketishidan oldin tezda yechim topishimiz kerak.",note:"Kemaning cho‘kishi bu suhbatda davlat boshiga falokat kelishini tasvirlaydi."},
{num:84,time:"00:07:57,319 --> 00:08:00,680",arabic:"لَا أَكُفُّ عَنِ التَّفْكِيرِ وَالتَّدْبِيرِ يَا مَوْلَاتِي.",segs:[{ar:"لَا أَكُفُّ عَنِ التَّفْكِيرِ وَالتَّدْبِيرِ",uz:"O‘ylash va chora izlashdan to‘xtamayman"},{ar:"يَا مَوْلَاتِي.",uz:"bekam."}],full_uz:"O‘ylash va chora izlashdan to‘xtamayman, bekam.",note:"كَفَّ عَنْ — ...dan to‘xtamoq. تَدْبِيرٌ — chora ko‘rish, reja tuzish."},
{num:85,time:"00:08:00,680 --> 00:08:07,339",arabic:"وَلَكِنْ لَا سَبِيلَ عَلَيْهِمْ وَهُمْ عَلَى مَكَانَتِهِمْ عِنْدَ أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"وَلَكِنْ لَا سَبِيلَ عَلَيْهِمْ",uz:"Ammo ularga qarshi chora yo‘q"},{ar:"وَهُمْ عَلَى مَكَانَتِهِمْ",uz:"ular o‘z mavqelarida turgan ekan"},{ar:"عِنْدَ أَمِيرِ الْمُؤْمِنِينَ.",uz:"mo‘minlar amiri huzurida."}],full_uz:"Ammo mo‘minlar amiri huzuridagi mavqelari saqlanib turgan ekan, ularga qarshi chora yo‘q.",note:"لَا سَبِيلَ عَلَيْهِمْ — ularga qarshi yo‘l, imkon yo‘q. مَكَانَةٌ — obro‘, mavqe."},
{num:86,time:"00:08:07,339 --> 00:08:13,899",arabic:"وَلَكِنَّ الْفَضْلَ بْنَ الرَّبِيعِ قَدْ قَطَعَ عَلَى نَفْسِهِ عَهْدًا بِأَنْ يَسْتَأْصِلَ شَأْفَتَهُمْ.",segs:[{ar:"وَلَكِنَّ الْفَضْلَ بْنَ الرَّبِيعِ",uz:"Ammo Fazl ibn Rabi’"},{ar:"قَدْ قَطَعَ عَلَى نَفْسِهِ عَهْدًا",uz:"o‘ziga qat’iy ahd qilgan"},{ar:"بِأَنْ يَسْتَأْصِلَ شَأْفَتَهُمْ.",uz:"ularning ildizini quritishga."}],full_uz:"Ammo Fazl ibn Rabi’ ularning ildizini quritishga qat’iy ahd qilgan.",note:"قَطَعَ عَلَى نَفْسِهِ عَهْدًا — o‘z zimmasiga qat’iy ahd olmoq. اِسْتَأْصَلَ شَأْفَتَهُمْ — ularni butunlay yo‘q qilmoq."},
{num:87,time:"00:08:13,899 --> 00:08:17,299",arabic:"لَا تَنْقُصُكَ الْحِيلَةُ وَالدَّهَاءُ يَا ابْنَ الرَّبِيعِ.",segs:[{ar:"لَا تَنْقُصُكَ الْحِيلَةُ وَالدَّهَاءُ",uz:"Senda hiyla va ziyraklik kam emas"},{ar:"يَا ابْنَ الرَّبِيعِ.",uz:"ey Ibn Rabi’."}],full_uz:"Senda hiyla va ziyraklik kam emas, Ibn Rabi’.",note:"لَا تَنْقُصُكَ — senda yetishmovchilik yo‘q. دَهَاءٌ — o‘tkir aql, ayyorlik."},
{num:88,time:"00:08:17,299 --> 00:08:19,719",arabic:"فَامْضِ فِيمَا تَرَى وَتَعْزِمُ،",segs:[{ar:"فَامْضِ",uz:"Unda olg‘a bor"},{ar:"فِيمَا تَرَى وَتَعْزِمُ،",uz:"ma’qul ko‘rgan va niyat qilgan ishingda,"}],full_uz:"Unda ma’qul ko‘rgan va niyat qilgan ishingda davom et…",note:"اِمْضِ — مَضَى يَمْضِي fe’lining buyrug‘i; oxirgi ي tushgan."},
{num:89,time:"00:08:19,719 --> 00:08:24,620",arabic:"وَاعْلَمْ أَنَّ مَوْلَاتَكَ زُبَيْدَةَ تَرْعَاكَ وَتَحْمِيكَ،",segs:[{ar:"وَاعْلَمْ أَنَّ مَوْلَاتَكَ زُبَيْدَةَ",uz:"Bilginki, bekang Zubayda"},{ar:"تَرْعَاكَ وَتَحْمِيكَ،",uz:"seni qo‘llaydi va himoya qiladi,"}],full_uz:"Bilginki, bekang Zubayda seni qo‘llaydi va himoya qiladi…",note:"رَعَى يَرْعَى — g‘amxo‘rlik qilmoq; حَمَى يَحْمِي — himoya qilmoq."},
{num:90,time:"00:08:24,620 --> 00:08:26,899",arabic:"فَلَا تَخْشَ شَيْئًا.",segs:null,full_uz:"Hech narsadan qo‘rqma.",note:"تَخْشَى fe’li taqiq لَا sidan keyin oxirgi zaif harfini yo‘qotadi: لَا تَخْشَ."},
{num:91,time:"00:08:26,899 --> 00:08:27,659",arabic:"إِنْ شَاءَ اللَّهُ.",segs:null,full_uz:"Alloh xohlasa.",note:null},
{num:92,time:"00:08:27,659 --> 00:08:35,220",arabic:"إِذَنْ فَقَدْ تَصَافَى الْوُدُّ بَيْنَكُمْ يَا شَافِعِيُّ.",segs:[{ar:"إِذَنْ فَقَدْ تَصَافَى الْوُدُّ بَيْنَكُمْ",uz:"Demak, orangizdagi do‘stlik yana samimiylashibdi"},{ar:"يَا شَافِعِيُّ.",uz:"ey Shofe’iy."}],full_uz:"Demak, orangizdagi do‘stlik yana samimiylashibdi, Shofe’iy.",note:"تَصَافَى — gina-kuduratdan xoli bo‘lib, samimiylashmoq. وُدٌّ — mehr, do‘stlik."},
{num:93,time:"00:08:35,220 --> 00:08:38,960",arabic:"تَقْصِدُ أَمِيرَ الْمُؤْمِنِينَ هَارُونَ؟",segs:null,full_uz:"Mo‘minlar amiri Horunni nazarda tutyapsizmi?",note:null},
{num:94,time:"00:08:38,960 --> 00:08:42,180",arabic:"أَجَلْ، فِيمَا يَبْدُو.",segs:null,full_uz:"Ha, shunday ko‘rinadi.",note:"فِيمَا يَبْدُو — ko‘rinishicha."},
{num:95,time:"00:08:42,180 --> 00:08:48,740",arabic:"وَإِنْ كُنْتُ أَعْتِبُ عَلَيْهِ لِحِرْمَانِي مِنَ الْقُفُولِ إِلَى مَكَّةَ حَمَاهَا اللَّهُ فِي الْوَقْتِ الرَّاهِنِ.",segs:[{ar:"وَإِنْ كُنْتُ أَعْتِبُ عَلَيْهِ",uz:"Garchi undan ranjiyotgan bo‘lsam ham"},{ar:"لِحِرْمَانِي مِنَ الْقُفُولِ إِلَى مَكَّةَ",uz:"Makkaga qaytishimga yo‘l bermagani uchun"},{ar:"حَمَاهَا اللَّهُ",uz:"Alloh uni asrasin"},{ar:"فِي الْوَقْتِ الرَّاهِنِ.",uz:"hozirgi paytda."}],full_uz:"Garchi hozir Makkaga qaytishimga yo‘l bermagani uchun undan ranjiyotgan bo‘lsam ham. Alloh Makkani asrasin.",note:"عَتَبَ عَلَيْهِ — undan ranjimoq, uni yengil koyimoq. قُفُولٌ — safardan qaytish. الْوَقْتُ الرَّاهِنُ — hozirgi vaqt."},
{num:96,time:"00:08:48,740 --> 00:08:53,240",arabic:"لَعَلَّهُ يُرِيدُ أَنْ يَسْتَأْنِسَ بِكَ يَا أَبَا مُحَمَّدٍ.",segs:[{ar:"لَعَلَّهُ يُرِيدُ",uz:"Balki u istayotgandir"},{ar:"أَنْ يَسْتَأْنِسَ بِكَ",uz:"suhbatingizdan taskin topishni"},{ar:"يَا أَبَا مُحَمَّدٍ.",uz:"ey Abu Muhammad."}],full_uz:"Balki u suhbatingizdan taskin topishni istayotgandir, Abu Muhammad.",note:"اِسْتَأْنَسَ بِهِ — uning yonida yoki suhbatida ko‘ngli taskin topmoq."},
{num:97,time:"00:08:53,240 --> 00:08:56,960",arabic:"أَوْ يَنْتَفِعَ مِنْ عِلْمِكَ وَفِقْهِكَ وَحُسْنِ رَأْيِكَ.",segs:[{ar:"أَوْ يَنْتَفِعَ",uz:"Yoki foydalansa"},{ar:"مِنْ عِلْمِكَ وَفِقْهِكَ",uz:"ilmingiz va fiqhiy bilimingizdan"},{ar:"وَحُسْنِ رَأْيِكَ.",uz:"hamda yaxshi fikringizdan."}],full_uz:"Yoki ilmingiz, fiqhiy bilimingiz va yaxshi fikringizdan foydalanishni istayotgandir.",note:"يَنْتَفِعَ oldingi banddagi أَنْ يَسْتَأْنِسَ ga bog‘langanligi uchun mansub."},
{num:98,time:"00:08:56,960 --> 00:09:00,740",arabic:"لَا، لَا، لَا، لَا أَظُنُّ ذَلِكَ.",segs:[{ar:"لَا، لَا، لَا،",uz:"Yo‘q, yo‘q, yo‘q"},{ar:"لَا أَظُنُّ ذَلِكَ.",uz:"bunday deb o‘ylamayman."}],full_uz:"Yo‘q, yo‘q, yo‘q, bunday deb o‘ylamayman.",note:null},
{num:99,time:"00:09:00,740 --> 00:09:08,220",arabic:"إِنَّ الرَّشِيدَ وَإِنْ ظَهَرَتْ لَهُ بَرَاءَتِي مِمَّا نُسِبَ إِلَيَّ كَذِبًا مِنْ أَمْرِ الْخُرُوجِ عَلَيْهِ،",segs:[{ar:"إِنَّ الرَّشِيدَ",uz:"Rashid"},{ar:"وَإِنْ ظَهَرَتْ لَهُ بَرَاءَتِي",uz:"garchi unga aybsizligim ayon bo‘lgan bo‘lsa ham"},{ar:"مِمَّا نُسِبَ إِلَيَّ كَذِبًا",uz:"menga yolg‘ondan nisbat berilgan narsada"},{ar:"مِنْ أَمْرِ الْخُرُوجِ عَلَيْهِ،",uz:"unga qarshi bosh ko‘tarish masalasida,"}],full_uz:"Rashidga, garchi unga qarshi bosh ko‘tarish haqida menga yolg‘ondan qo‘yilgan aybdan xoli ekanim ayon bo‘lgan bo‘lsa ham…",note:"نُسِبَ إِلَيَّ — menga nisbat berildi, majhul shakl. الْخُرُوجُ عَلَى — hukmdorga qarshi bosh ko‘tarish."},
{num:100,time:"00:09:08,220 --> 00:09:14,360",arabic:"إِلَّا أَنَّهُ مَا زَالَ يَتَوَجَّسُ خِيفَةً مِنْ هَذَا الزَّعْمِ وَالِادِّعَاءِ.",segs:[{ar:"إِلَّا أَنَّهُ مَا زَالَ",uz:"baribir u hali ham"},{ar:"يَتَوَجَّسُ خِيفَةً",uz:"ichida qo‘rquv sezyapti"},{ar:"مِنْ هَذَا الزَّعْمِ وَالِادِّعَاءِ.",uz:"bu da’vo va iddaodan."}],full_uz:"Baribir u bu da’vo va iddaodan hali ham ichida qo‘rquv sezyapti.",note:"تَوَجَّسَ خِيفَةً — ichida xavotir yoki qo‘rquv sezmoq. مَا زَالَ — hali ham davom etayotgan holat."},
{num:101,time:"00:09:14,360 --> 00:09:18,080",arabic:"وَكَيْفَ ذَلِكَ يَا ابْنَ إِدْرِيسَ؟",segs:[{ar:"وَكَيْفَ ذَلِكَ",uz:"Bu qanday bo‘ladi"},{ar:"يَا ابْنَ إِدْرِيسَ؟",uz:"ey Ibn Idris?"}],full_uz:"Bu qanday bo‘ladi, Ibn Idris?",note:null},
{num:102,time:"00:09:18,080 --> 00:09:22,200",arabic:"أَنْتَ تَعْلَمُ أَنَّ بَنِي الْعَبَّاسِ مُنْذُ تَسَلُّمِهِمْ مَقَالِيدَ الْخِلَافَةِ،",segs:[{ar:"أَنْتَ تَعْلَمُ أَنَّ بَنِي الْعَبَّاسِ",uz:"Siz bilasiz, Abbos avlodi"},{ar:"مُنْذُ تَسَلُّمِهِمْ مَقَالِيدَ الْخِلَافَةِ،",uz:"xalifalik boshqaruvini qo‘lga olganidan beri,"}],full_uz:"Siz bilasiz, Abbos avlodi xalifalik boshqaruvini qo‘lga olganidan beri…",note:"مَقَالِيدُ الْخِلَافَةِ — xalifalik boshqaruvi, hokimiyat jilovi. تَسَلُّمٌ — qabul qilib olish."},
{num:103,time:"00:09:22,200 --> 00:09:28,860",arabic:"وَهُمْ لِلْأَسَفِ فِي خِصَامٍ دَائِمٍ مَعَ أَبْنَاءِ عُمُومَتِهِمُ الطَّالِبِيِّينَ.",segs:[{ar:"وَهُمْ لِلْأَسَفِ",uz:"ular, afsuski"},{ar:"فِي خِصَامٍ دَائِمٍ",uz:"doimiy nizoda"},{ar:"مَعَ أَبْنَاءِ عُمُومَتِهِمُ الطَّالِبِيِّينَ.",uz:"amakivachchalari Tolibiylar bilan."}],full_uz:"Ular, afsuski, amakivachchalari Tolibiylar bilan doimiy nizoda.",note:"خِصَامٌ — tortishuv, nizo. أَبْنَاءُ عُمُومَتِهِمْ — ota tomondan qarindoshlari, amakivachchalari."},
{num:104,time:"00:09:28,860 --> 00:09:35,460",arabic:"أَعْلَمُ ذَلِكَ، فَالطَّالِبِيُّونَ كَانُوا قَدْ سَاعَدُوهُمْ فِي إِنْهَاءِ دَوْلَةِ بَنِي أُمَيَّةَ.",segs:[{ar:"أَعْلَمُ ذَلِكَ،",uz:"Buni bilaman"},{ar:"فَالطَّالِبِيُّونَ كَانُوا قَدْ سَاعَدُوهُمْ",uz:"Tolibiylar ularga yordam bergan edilar"},{ar:"فِي إِنْهَاءِ دَوْلَةِ بَنِي أُمَيَّةَ.",uz:"Umaviylar davlatini tugatishda."}],full_uz:"Buni bilaman. Tolibiylar ularga Umaviylar davlatini tugatishda yordam bergan edilar.",note:"كَانُوا قَدْ سَاعَدُوا — avvalroq yordam bergan edilar. إِنْهَاءٌ — tugatish, barham berish."},
{num:105,time:"00:09:35,460 --> 00:09:39,460",arabic:"ثُمَّ لَمَّا اسْتَأْثَرَ بَنُو الْعَبَّاسِ بِالْحُكْمِ دُونَهُمْ،",segs:[{ar:"ثُمَّ لَمَّا اسْتَأْثَرَ بَنُو الْعَبَّاسِ بِالْحُكْمِ",uz:"Keyin Abbos avlodi hokimiyatni o‘ziga xoslab olgach"},{ar:"دُونَهُمْ،",uz:"ularni chetda qoldirib,"}],full_uz:"Keyin Abbos avlodi ularni chetda qoldirib, hokimiyatni o‘ziga xoslab olgach…",note:"اِسْتَأْثَرَ بِـ — boshqalarga ulashmay, o‘ziga xoslab olmoq. بَنُو — gapning egasi bo‘lgani uchun marfu’."},
{num:106,time:"00:09:39,460 --> 00:09:42,180",arabic:"دَبَّ الْخِلَافُ بَيْنَ أَبْنَاءِ الْبَيْتَيْنِ.",segs:[{ar:"دَبَّ الْخِلَافُ",uz:"Nizo yoyildi"},{ar:"بَيْنَ أَبْنَاءِ الْبَيْتَيْنِ.",uz:"ikki xonadon vakillari orasida."}],full_uz:"Ikki xonadon vakillari orasida nizo yoyildi.",note:"دَبَّ الْخِلَافُ — nizo asta-sekin paydo bo‘lib tarqaldi. الْبَيْتَانِ bu yerda ikki sulola, xonadon."},
{num:107,time:"00:09:42,180 --> 00:09:50,300",arabic:"وَقَدْ عَانَى مِنْ وَيْلَاتِ ذَلِكَ الْخَلِيفَةُ الْمَنْصُورُ وَالْخَلِيفَةُ الْمَهْدِيُّ وَالْخَلِيفَةُ الْهَادِي.",segs:[{ar:"وَقَدْ عَانَى مِنْ وَيْلَاتِ ذَلِكَ",uz:"Buning kulfatlaridan aziyat chekkan"},{ar:"الْخَلِيفَةُ الْمَنْصُورُ",uz:"xalifa Mansur"},{ar:"وَالْخَلِيفَةُ الْمَهْدِيُّ وَالْخَلِيفَةُ الْهَادِي.",uz:"xalifa Mahdiy va xalifa Hodiy."}],full_uz:"Buning kulfatlaridan xalifa Mansur, xalifa Mahdiy va xalifa Hodiy aziyat chekkan.",note:"عَانَى مِنْ — ...dan aziyat chekmoq. وَيْلَاتٌ — kulfatlar, og‘ir oqibatlar."},
{num:108,time:"00:09:50,300 --> 00:09:54,759",arabic:"حَتَّى هَارُونُ الرَّشِيدُ لَمْ تَمُرَّ عَلَيْهِ سَنَةٌ،",segs:[{ar:"حَتَّى هَارُونُ الرَّشِيدُ",uz:"Hatto Horun ar-Rashidning ham"},{ar:"لَمْ تَمُرَّ عَلَيْهِ سَنَةٌ،",uz:"biror yili o‘tmagan,"}],full_uz:"Hatto Horun ar-Rashidning ham biror yili o‘tmaganki…",note:"Gap keyingi banddagi إِلَّا bilan davom etadi: har bir yilda shu hodisa bo‘lganini bildiradi."},
{num:109,time:"00:09:54,759 --> 00:09:59,200",arabic:"إِلَّا وَكَدَّرَ صَفْوَهَا نِزَاعٌ مَعَ أَحَدِ أَبْنَاءِ الْبَيْتِ الطَّالِبِيِّ.",segs:[{ar:"إِلَّا وَكَدَّرَ صَفْوَهَا نِزَاعٌ",uz:"uning osoyishtaligini bir nizo buzmagan bo‘lsin"},{ar:"مَعَ أَحَدِ أَبْنَاءِ الْبَيْتِ الطَّالِبِيِّ.",uz:"Tolibiylar xonadoni vakillaridan biri bilan."}],full_uz:"Har yili uning osoyishtaligini Tolibiylar xonadonidan bir kishi bilan nizo buzgan.",note:"كَدَّرَ صَفْوَهَا — uning osoyishtaligini, huzurini buzdi."},
{num:110,time:"00:09:59,200 --> 00:10:05,019",arabic:"وَهَذَا يَحْيَى بْنُ عَبْدِ اللَّهِ بْنِ حَسَنٍ يَقْبَعُ فِي أَحَدِ سُجُونِ الْبَرَامِكَةِ،",segs:[{ar:"وَهَذَا يَحْيَى بْنُ عَبْدِ اللَّهِ بْنِ حَسَنٍ",uz:"Mana Yahyo ibn Abdulloh ibn Hasan"},{ar:"يَقْبَعُ",uz:"qamalib yotibdi"},{ar:"فِي أَحَدِ سُجُونِ الْبَرَامِكَةِ،",uz:"Barmakiylar qamoqxonalaridan birida,"}],full_uz:"Mana Yahyo ibn Abdulloh ibn Hasan Barmakiylar qamoqxonalaridan birida qamalib yotibdi…",note:"قَبَعَ يَقْبَعُ — bir joyda uzoq qolib ketmoq; qamoq haqida aytilganda qamalib yotishni bildiradi."},
{num:111,time:"00:10:05,019 --> 00:10:05,840",arabic:"جَرَّاءَ ذَلِكَ.",segs:null,full_uz:"Shu tufayli.",note:"جَرَّاءَ — sababli, oqibatida."},
{num:112,time:"00:10:05,840 --> 00:10:08,679",arabic:"تَمَامًا، تَمَامًا يَا أَبَا عَبْدِ اللَّهِ.",segs:null,full_uz:"Aynan shunday, aynan shunday, Abu Abdulloh.",note:null},
{num:113,time:"00:10:08,679 --> 00:10:15,840",arabic:"فَلَمَّا كَانَ أَبْنَاءُ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ هُمْ أَبْنَاءَ عُمُومَتِي،",segs:[{ar:"فَلَمَّا كَانَ أَبْنَاءُ عَلِيِّ بْنِ أَبِي طَالِبٍ",uz:"Ali ibn Abu Tolibning avlodi"},{ar:"رَضِيَ اللَّهُ عَنْهُ",uz:"Alloh undan rozi bo‘lsin"},{ar:"هُمْ أَبْنَاءَ عُمُومَتِي،",uz:"mening amakivachchalarim bo‘lgani uchun,"}],full_uz:"Ali ibn Abu Tolibning avlodi — Alloh undan rozi bo‘lsin — mening amakivachchalarim bo‘lgani uchun…",note:"لَمَّا كَانَ bu o‘rinda sababni anglatadi: ...bo‘lgani uchun."},
{num:114,time:"00:10:15,840 --> 00:10:18,720",arabic:"وَفِي ذَاتِ الْوَقْتِ هُمْ أَبْنَاءُ عُمُومَتِهِ،",segs:[{ar:"وَفِي ذَاتِ الْوَقْتِ",uz:"ayni paytda"},{ar:"هُمْ أَبْنَاءُ عُمُومَتِهِ،",uz:"ular uning ham amakivachchalari,"}],full_uz:"Ayni paytda ular uning ham amakivachchalari…",note:"فِي ذَاتِ الْوَقْتِ — ayni paytda, shu bilan bir vaqtda."},
{num:115,time:"00:10:18,720 --> 00:10:23,039",arabic:"فَهُوَ يَخْشَى أَنْ أَكُونَ قَدْ مِلْتُ إِلَيْهِمْ وَلَوْ بِمَحْضِ الْكَلَامِ.",segs:[{ar:"فَهُوَ يَخْشَى",uz:"shuning uchun u qo‘rqadi"},{ar:"أَنْ أَكُونَ قَدْ مِلْتُ إِلَيْهِمْ",uz:"men ularga yon bosgan bo‘lishimdan"},{ar:"وَلَوْ بِمَحْضِ الْكَلَامِ.",uz:"hatto faqat so‘z bilan bo‘lsa ham."}],full_uz:"Shuning uchun u men ularga hatto faqat so‘z bilan bo‘lsa ham yon bosgan bo‘lishimdan qo‘rqadi.",note:"مَالَ إِلَى — moyil bo‘lmoq, yon bosmoq. بِمَحْضِ الْكَلَامِ — faqatgina so‘z bilan."},
{num:116,time:"00:10:23,039 --> 00:10:27,740",arabic:"أَنْتَ تَعْلَمُ أَنَّ اللِّسَانَ أَمْضَى مِنَ السِّنَانِ.",segs:[{ar:"أَنْتَ تَعْلَمُ",uz:"Siz bilasiz"},{ar:"أَنَّ اللِّسَانَ أَمْضَى مِنَ السِّنَانِ.",uz:"til nayza uchidan o‘tkirroq ekanini."}],full_uz:"Til nayza uchidan o‘tkirroq ekanini bilasiz.",note:"سِنَانٌ — nayzaning temir uchi. أَمْضَى — o‘tkirroq, ta’sirchanroq."},
{num:117,time:"00:10:27,740 --> 00:10:33,620",arabic:"فَهِمْتُ مَا تَرْمِي إِلَيْهِ أَيُّهَا الشَّافِعِيُّ.",segs:[{ar:"فَهِمْتُ مَا تَرْمِي إِلَيْهِ",uz:"Nimani nazarda tutayotganingizni tushundim"},{ar:"أَيُّهَا الشَّافِعِيُّ.",uz:"ey Shofe’iy."}],full_uz:"Nimani nazarda tutayotganingizni tushundim, Shofe’iy.",note:"رَمَى إِلَى — ko‘zlamoq, nazarda tutmoq."},
{num:118,time:"00:10:33,620 --> 00:10:39,980",arabic:"فَالرَّشِيدُ يَسْجُنُ حُرِّيَّتَكَ وَيُقَيِّدُ حَرَكَتَكَ،",segs:[{ar:"فَالرَّشِيدُ يَسْجُنُ حُرِّيَّتَكَ",uz:"Rashid erkinligingizni qamoqqa solyapti"},{ar:"وَيُقَيِّدُ حَرَكَتَكَ،",uz:"harakatingizni cheklayapti,"}],full_uz:"Rashid erkinligingizni qamoqqa solib, harakatingizni cheklayapti…",note:"قَيَّدَ حَرَكَتَهُ — uning harakatlanish erkinligini cheklamoq."},
{num:119,time:"00:10:39,980 --> 00:10:42,599",arabic:"وَذَلِكَ بَعْدَ أَنْ ظَهَرَتْ لَهُ بَرَاءَتُكَ،",segs:[{ar:"وَذَلِكَ بَعْدَ أَنْ ظَهَرَتْ لَهُ",uz:"bu unga ayon bo‘lganidan keyin"},{ar:"بَرَاءَتُكَ،",uz:"aybsizligingiz,"}],full_uz:"Bu unga aybsizligingiz ayon bo‘lganidan keyin…",note:null},
{num:120,time:"00:10:42,599 --> 00:10:44,919",arabic:"دَرْءًا لِاحْتِمَالٍ بَسِيطٍ.",segs:null,full_uz:"Arzimas bir ehtimolning oldini olish uchun.",note:"دَرْءٌ — daf qilish, oldini olish. دَرْءًا sabab yoki maqsadni bildiradi."},
{num:121,time:"00:10:44,919 --> 00:10:48,219",arabic:"هَذَا مَا قَصَدْتُهُ يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"هَذَا مَا قَصَدْتُهُ",uz:"Nazarda tutganim shu"},{ar:"يَا أَبَا عَبْدِ اللَّهِ.",uz:"ey Abu Abdulloh."}],full_uz:"Nazarda tutganim shu, Abu Abdulloh.",note:null},
{num:122,time:"00:10:48,220 --> 00:10:53,899",arabic:"إِذَنْ عَلَيَّ أَنْ أُقَدِّمَ شُكْرِي لِأَمِيرِ الْمُؤْمِنِينَ،",segs:[{ar:"إِذَنْ عَلَيَّ أَنْ أُقَدِّمَ شُكْرِي",uz:"Unda minnatdorligimni bildirishim kerak"},{ar:"لِأَمِيرِ الْمُؤْمِنِينَ،",uz:"mo‘minlar amiriga,"}],full_uz:"Unda mo‘minlar amiriga minnatdorligimni bildirishim kerak…",note:"عَلَيَّ أَنْ — men ...qilishim kerak. قَدَّمَ شُكْرَهُ — minnatdorligini bildirmoq."},
{num:123,time:"00:10:53,899 --> 00:10:56,040",arabic:"أَنْ اسْتَبْقَاكَ هُنَا فِي بَغْدَادَ،",segs:[{ar:"أَنْ اسْتَبْقَاكَ هُنَا",uz:"sizni shu yerda olib qolgani uchun"},{ar:"فِي بَغْدَادَ،",uz:"Bag‘dodda,"}],full_uz:"Sizni shu yerda, Bag‘dodda olib qolgani uchun…",note:"اِسْتَبْقَى — olib qolmoq, ketishiga yo‘l qo‘ymay saqlab qolmoq."},
{num:124,time:"00:10:56,040 --> 00:10:58,879",arabic:"حَتَّى نَأْنَسَ بِصُحْبَتِكَ يَا أَبَا مُحَمَّدٍ.",segs:[{ar:"حَتَّى نَأْنَسَ بِصُحْبَتِكَ",uz:"suhbatingizdan huzur topishimiz uchun"},{ar:"يَا أَبَا مُحَمَّدٍ.",uz:"ey Abu Muhammad."}],full_uz:"Suhbatingizdan huzur topishimiz uchun, Abu Muhammad.",note:"أَنِسَ بِـ — ...dan ko‘ngli taskin topmoq, huzurlanmoq. حَتَّى bu yerda maqsad bildiradi."},
{num:125,time:"00:10:58,879 --> 00:11:05,259",arabic:"تَأْنَسُ أَنْتَ بِصُحْبَتِي وَتَتَجَرَّعُ أُمِّي وَأَهْلِي مَرَارَةَ فُرْقَتِي.",segs:[{ar:"تَأْنَسُ أَنْتَ بِصُحْبَتِي",uz:"Siz mening suhbatimdan huzur topasiz"},{ar:"وَتَتَجَرَّعُ أُمِّي وَأَهْلِي",uz:"onam va oilam esa yutadi"},{ar:"مَرَارَةَ فُرْقَتِي.",uz:"mendan ayriliq achchig‘ini."}],full_uz:"Siz mening suhbatimdan huzur topasiz, onam va oilam esa mendan ayriliq achchig‘ini yutadi.",note:"تَجَرَّعَ الْمَرَارَةَ — so‘zma-so‘z «achchiqlikni qultumlab ichdi»; og‘ir iztirobni boshdan kechirish tasviri."},
{num:126,time:"00:11:18,220 --> 00:11:32,080",arabic:"السَّلَامُ عَلَيْكَ يَا أَحْمَدُ.",segs:[{ar:"السَّلَامُ عَلَيْكَ",uz:"Senga salom bo‘lsin"},{ar:"يَا أَحْمَدُ.",uz:"ey Ahmad."}],full_uz:"Assalomu alaykum, Ahmad.",note:null},
{num:127,time:"00:11:32,080 --> 00:11:33,600",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"Sizga ham salom bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ.",uz:"va Allohning rahmati."}],full_uz:"Sizga ham salom va Allohning rahmati bo‘lsin.",note:null},
{num:128,time:"00:11:33,600 --> 00:11:34,980",arabic:"أَهْلًا بِكِ يَا خَالَةُ.",segs:null,full_uz:"Xush kelibsiz, xolajon.",note:"خَالَةٌ — xola; yoshi katta ayolga hurmat bilan murojaatda ham ishlatiladi."},
{num:129,time:"00:11:34,980 --> 00:11:37,180",arabic:"لِي حَاجَةٌ عِنْدَكَ يَا وَلَدِي.",segs:[{ar:"لِي حَاجَةٌ عِنْدَكَ",uz:"Sendan bir iltimosim bor"},{ar:"يَا وَلَدِي.",uz:"o‘g‘lim."}],full_uz:"Sendan bir iltimosim bor, o‘g‘lim.",note:null},
{num:130,time:"00:11:37,180 --> 00:11:39,320",arabic:"تَفَضَّلِي فَأُمِّي دَاخِلَ الْبَيْتِ،",segs:[{ar:"تَفَضَّلِي",uz:"Marhamat, kiring"},{ar:"فَأُمِّي دَاخِلَ الْبَيْتِ،",uz:"onam uy ichidalar,"}],full_uz:"Marhamat, kiring, onam uy ichidalar…",note:null},
{num:131,time:"00:11:39,320 --> 00:11:40,600",arabic:"ثُمَّ نَنْظُرُ لَكِ حَاجَتَكِ.",segs:null,full_uz:"Keyin iltimosingizni ko‘rib chiqamiz.",note:"نَنْظُرُ bu yerda ko‘rishdan ko‘ra ishni ko‘rib chiqish, hal qilishga urinish ma’nosida."},
{num:132,time:"00:11:40,600 --> 00:11:42,480",arabic:"لَنْ أَدْخُلَ إِلَى الْبَيْتِ،",segs:null,full_uz:"Uyga kirmayman…",note:null},
{num:133,time:"00:11:42,480 --> 00:11:45,440",arabic:"قَبْلَ أَنْ تَعِدَنِي أَنْ تُلَبِّيَ لِي حَاجَتِي.",segs:[{ar:"قَبْلَ أَنْ تَعِدَنِي",uz:"menga va’da bermaguningcha"},{ar:"أَنْ تُلَبِّيَ لِي حَاجَتِي.",uz:"iltimosimni bajarishga."}],full_uz:"Iltimosimni bajarishga va’da bermaguningcha.",note:"وَعَدَ يَعِدُ — va’da bermoq. لَبَّى الْحَاجَةَ — ehtiyoj yoki iltimosni qondirmoq."},
{num:134,time:"00:11:46,720 --> 00:11:49,460",arabic:"تَفَضَّلِي، وَإِنْ شَاءَ اللَّهُ لَنْ تَخْرُجِي إِلَّا رَاضِيَةً.",segs:[{ar:"تَفَضَّلِي،",uz:"Marhamat, kiring"},{ar:"وَإِنْ شَاءَ اللَّهُ",uz:"Alloh xohlasa"},{ar:"لَنْ تَخْرُجِي إِلَّا رَاضِيَةً.",uz:"faqat rozi holda chiqasiz."}],full_uz:"Marhamat, kiring. Alloh xohlasa, rozi bo‘lib chiqasiz.",note:"رَاضِيَةً — ayol kishining holatini bildiruvchi hol. لَنْ تَخْرُجِي da besh fe’lning nuni tushgan."},
{num:135,time:"00:11:50,040 --> 00:12:00,940",arabic:"مَاذَا؟ أَصَابَكَ الْعَمَى؟",segs:[{ar:"مَاذَا؟",uz:"Nima?"},{ar:"أَصَابَكَ الْعَمَى؟",uz:"Ko‘r bo‘lib qoldingmi?"}],full_uz:"Nima? Ko‘r bo‘lib qoldingmi?",note:"الْعَمَى — ko‘rlik. أَصَابَكَ — senga yetdi, seni tutdi."},
{num:136,time:"00:12:00,940 --> 00:12:02,139",arabic:"لِمَاذَا لَا تَسْكُتِينَ؟",segs:null,full_uz:"Nega jim bo‘lmaysan?",note:null},
{num:137,time:"00:12:02,139 --> 00:12:05,720",arabic:"اُسْكُتِي، أَلَا تَرَيْنَنِي لَا يَقِرُّ لِي قَرَارٌ وَلَا يَهْدَأُ لِي بَالٌ؟",segs:[{ar:"اُسْكُتِي،",uz:"Jim bo‘l"},{ar:"أَلَا تَرَيْنَنِي",uz:"ko‘rmayapsanmi"},{ar:"لَا يَقِرُّ لِي قَرَارٌ",uz:"bir joyda tinch turolmayapman"},{ar:"وَلَا يَهْدَأُ لِي بَالٌ؟",uz:"xayolim ham tinchimayapti?"}],full_uz:"Jim bo‘l! Bir joyda tinch turolmayotganimni, xayolim ham tinchimayotganini ko‘rmayapsanmi?",note:"لَا يَقِرُّ لِي قَرَارٌ — o‘zimni qo‘yarga joy topolmayapman. لَا يَهْدَأُ لِي بَالٌ — ko‘nglim, xayolim tinchimaydi."},
{num:138,time:"00:12:05,720 --> 00:12:10,840",arabic:"كَيْفَ يَرَى أَمَامَهُ مَنْ أَفْقَدَهُ الْقَلَقُ بَصَرَهُ وَأَضَلَّهُ طَرِيقَهُ؟ كَيْفَ؟",segs:[{ar:"كَيْفَ يَرَى أَمَامَهُ",uz:"Oldini qanday ko‘rsin"},{ar:"مَنْ أَفْقَدَهُ الْقَلَقُ بَصَرَهُ",uz:"xavotir ko‘zini ko‘r qilgan kishi"},{ar:"وَأَضَلَّهُ طَرِيقَهُ؟",uz:"va yo‘lidan adashtirgan?"},{ar:"كَيْفَ؟",uz:"Qanday?"}],full_uz:"Xavotir ko‘zini ko‘r qilib, yo‘lidan adashtirgan kishi oldini qanday ko‘rsin? Qanday?",note:"أَفْقَدَهُ بَصَرَهُ — uni ko‘rish qobiliyatidan mahrum qildi. أَضَلَّهُ — adashtirdi."},
{num:139,time:"00:12:10,840 --> 00:12:15,820",arabic:"إِذَنْ لِمَاذَا لَا تَجْلِسُ فِي مَكَانٍ مَا وَتَقْلَقُ كَمَا تَشَاءُ وَتَدَعُنِي أَعْمَلُ؟",segs:[{ar:"إِذَنْ لِمَاذَا لَا تَجْلِسُ",uz:"Unda nega o‘tirmaysan"},{ar:"فِي مَكَانٍ مَا",uz:"biror joyda"},{ar:"وَتَقْلَقُ كَمَا تَشَاءُ",uz:"va xohlaganingcha xavotir olmaysan"},{ar:"وَتَدَعُنِي أَعْمَلُ؟",uz:"menga esa ishlashga qo‘yib bermaysan?"}],full_uz:"Unda nega biror joyda o‘tirib, xohlaganingcha xavotir olmaysan-u, menga ishlashga qo‘yib bermaysan?",note:"مَكَانٌ مَا — qandaydir joy, biror joy. Ot ortidan kelgan مَا noaniqlikni kuchaytiradi."},
{num:140,time:"00:12:15,820 --> 00:12:19,540",arabic:"لِمَ لَا تَسْكُتِينَ وَتَدَعِينَنِي أَقْلَقُ عَلَى رَاحَتِي؟",segs:[{ar:"لِمَ لَا تَسْكُتِينَ",uz:"Nega jim bo‘lmaysan"},{ar:"وَتَدَعِينَنِي أَقْلَقُ",uz:"va menga xavotir olishga qo‘ymaysan"},{ar:"عَلَى رَاحَتِي؟",uz:"o‘z holimcha?"}],full_uz:"Nega jim bo‘lib, o‘z holimcha xavotir olishimga qo‘ymaysan?",note:"عَلَى رَاحَتِي — o‘z istagimcha, bemalol, hech kim xalaqit bermay."},
{num:141,time:"00:12:19,540 --> 00:12:23,240",arabic:"مُنْذُ الْأَمْسِ وَأَنْتَ عَلَى هَذِهِ الْحَالِ.",segs:[{ar:"مُنْذُ الْأَمْسِ",uz:"Kechadan beri"},{ar:"وَأَنْتَ عَلَى هَذِهِ الْحَالِ.",uz:"shu ahvoldasan."}],full_uz:"Kechadan beri shu ahvoldasan.",note:null},
{num:142,time:"00:12:23,240 --> 00:12:25,820",arabic:"سَنُصَابُ كُلُّنَا بِعَدْوَى قَلَقِكَ.",segs:[{ar:"سَنُصَابُ كُلُّنَا",uz:"Hammamizga yuqadi"},{ar:"بِعَدْوَى قَلَقِكَ.",uz:"sening xavotiring."}],full_uz:"Sening xavotiring hammamizga yuqadi.",note:"نُصَابُ — bizga yuqadi yoki biz duchor bo‘lamiz; majhul shakl."},
{num:143,time:"00:12:25,820 --> 00:12:29,560",arabic:"ثُمَّ قُلْ لِي، هَلْ سَتَنْقَلِبُ الدُّنْيَا إِنْ تَرَكْتَ الدُّكَّانَ؟",segs:[{ar:"ثُمَّ قُلْ لِي،",uz:"Keyin menga ayt"},{ar:"هَلْ سَتَنْقَلِبُ الدُّنْيَا",uz:"dunyo ostin-ustun bo‘ladimi"},{ar:"إِنْ تَرَكْتَ الدُّكَّانَ؟",uz:"do‘konni tashlab ketsang?"}],full_uz:"Keyin menga ayt: do‘konni tashlab ketsang, dunyo ostin-ustun bo‘ladimi?",note:"اِنْقَلَبَتِ الدُّنْيَا — dunyo ostin-ustun bo‘ldi; katta falokatni mubolag‘a bilan ifodalaydi."},
{num:144,time:"00:12:29,560 --> 00:12:33,940",arabic:"سَلَمَةُ، زَوْجَتِي، أُمَّ عُمَيْرٍ، هَلْ سَتُفْلِحُ أُمِّي فِي مَسْعَاهَا؟",segs:[{ar:"سَلَمَةُ، زَوْجَتِي، أُمَّ عُمَيْرٍ،",uz:"Salama, xotinim, Umm Umayr"},{ar:"هَلْ سَتُفْلِحُ أُمِّي",uz:"onam muvaffaq bo‘larmikan"},{ar:"فِي مَسْعَاهَا؟",uz:"bu urinishlarida?"}],full_uz:"Salama, xotinim, Umm Umayr, onam bu urinishlarida muvaffaq bo‘larmikan?",note:"أَفْلَحَ فِي — muvaffaq bo‘lmoq. مَسْعًى — intilish, bir maqsad yo‘lidagi urinish."},
{num:145,time:"00:12:33,940 --> 00:12:36,940",arabic:"وَهَلْ تَعْجِزُ أُمُّكَ عَنْ فِعْلِ شَيْءٍ؟",segs:[{ar:"وَهَلْ تَعْجِزُ أُمُّكَ",uz:"Onang ojiz qoladimi"},{ar:"عَنْ فِعْلِ شَيْءٍ؟",uz:"biror ishni qilishdan?"}],full_uz:"Onang biror ishni qilishdan ojiz qoladimi o‘zi?",note:"عَجَزَ عَنْ — bir ishga kuchi yetmaslik, uni bajara olmaslik."},
{num:146,time:"00:12:36,940 --> 00:12:39,820",arabic:"أَلَا يَكْفِي أَنَّهَا أَفْلَحَتْ فِي تَزْوِيجِي بِكَ؟",segs:[{ar:"أَلَا يَكْفِي أَنَّهَا أَفْلَحَتْ",uz:"Uning uddasidan chiqqani yetarli emasmi"},{ar:"فِي تَزْوِيجِي بِكَ؟",uz:"meni senga turmushga berishning?"}],full_uz:"Meni senga turmushga berishning uddasidan chiqqani yetarli emasmi?",note:"تَزْوِيجِي — meni turmushga berish; masdardagi ي ishning bajaruvchisini emas, ta’sir oluvchini bildirgan."},
{num:147,time:"00:12:45,820 --> 00:12:57,740",arabic:"مَا الْأَخْبَارُ يَا أُمِّي؟",segs:null,full_uz:"Qanday yangiliklar bor, onajon?",note:null},
{num:148,time:"00:12:57,740 --> 00:12:59,879",arabic:"الْأَخْبَارُ جَيِّدَةٌ أَيُّهَا الْإِسْكَافِيُّ.",segs:[{ar:"الْأَخْبَارُ جَيِّدَةٌ",uz:"Yangiliklar yaxshi"},{ar:"أَيُّهَا الْإِسْكَافِيُّ.",uz:"ey etikdo‘z."}],full_uz:"Yangiliklar yaxshi, ey etikdo‘z.",note:null},
{num:149,time:"00:12:59,879 --> 00:13:03,720",arabic:"وَلَكِنْ دَعْنِي أَلْتَقِطْ أَنْفَاسِي فَقَدْ أَتْعَبَنِي طُولُ الطَّرِيقِ.",segs:[{ar:"وَلَكِنْ دَعْنِي أَلْتَقِطْ أَنْفَاسِي",uz:"Ammo nafasimni rostlab olay"},{ar:"فَقَدْ أَتْعَبَنِي طُولُ الطَّرِيقِ.",uz:"uzoq yo‘l meni charchatdi."}],full_uz:"Ammo nafasimni rostlab olay, uzoq yo‘l meni charchatdi.",note:"اِلْتَقَطَ أَنْفَاسَهُ — nafasini rostlab olmoq."},
{num:150,time:"00:13:03,720 --> 00:13:07,260",arabic:"وَأَنَا يَا أُمِّي طُولُ مُكُوثِي فِي الْبَيْتِ أَقْلَقَنِي.",segs:[{ar:"وَأَنَا يَا أُمِّي",uz:"Meni esa, onajon"},{ar:"طُولُ مُكُوثِي فِي الْبَيْتِ",uz:"uyda uzoq qolishim"},{ar:"أَقْلَقَنِي.",uz:"bezovta qildi."}],full_uz:"Meni esa uyda uzoq qolishim bezovta qildi, onajon.",note:"مُكُوثٌ — bir joyda qolish, turish. أَقْلَقَ — xavotirga solmoq."},
{num:151,time:"00:13:07,260 --> 00:13:10,820",arabic:"يَعْنِي مَا الْخَبَرُ؟ أَخْبِرِينِي، هَلْ وَافَقَ؟",segs:[{ar:"يَعْنِي مَا الْخَبَرُ؟",uz:"Xo‘sh, qanday xabar?"},{ar:"أَخْبِرِينِي،",uz:"Menga ayting"},{ar:"هَلْ وَافَقَ؟",uz:"u rozi bo‘ldimi?"}],full_uz:"Xo‘sh, qanday xabar? Menga ayting, u rozi bo‘ldimi?",note:null},
{num:152,time:"00:13:11,720 --> 00:13:14,580",arabic:"عَدِمَتْكَ أُمُّكَ يَا عَامِرُ، قُلْ مَعِي آمِينَ.",segs:[{ar:"عَدِمَتْكَ أُمُّكَ يَا عَامِرُ،",uz:"Onang sendan ayrilsin, Omir"},{ar:"قُلْ مَعِي آمِينَ.",uz:"men bilan omin de."}],full_uz:"Onang sendan ayrilsin, Omir! Men bilan omin de.",note:"عَدِمَتْكَ أُمُّكَ — qattiq koyish iborasi; har doim ham so‘zma-so‘z yomon tilak nazarda tutilmaydi."},
{num:153,time:"00:13:14,580 --> 00:13:15,580",arabic:"آمِينَ.",segs:null,full_uz:"Omin.",note:"آمِينَ — duo qabul bo‘lishini so‘rash: qabul qilgin."},
{num:154,time:"00:13:15,580 --> 00:13:18,500",arabic:"وَافَقَ ابْنُ حَنْبَلٍ أَنْ تَعُودَ إِلَى الدُّكَّانِ،",segs:[{ar:"وَافَقَ ابْنُ حَنْبَلٍ",uz:"Ibn Hanbal rozi bo‘ldi"},{ar:"أَنْ تَعُودَ إِلَى الدُّكَّانِ،",uz:"do‘konga qaytishingga,"}],full_uz:"Ibn Hanbal do‘konga qaytishingga rozi bo‘ldi…",note:null},
{num:155,time:"00:13:18,500 --> 00:13:22,080",arabic:"شَرِيطَةَ أَلَّا تَعُودَ لِذِكْرِ بَيْعِهَا أَوْ شِرَائِهَا.",segs:[{ar:"شَرِيطَةَ أَلَّا تَعُودَ لِذِكْرِ",uz:"yana tilga olmasliging sharti bilan"},{ar:"بَيْعِهَا أَوْ شِرَائِهَا.",uz:"uni sotish yoki sotib olishni."}],full_uz:"Uni sotish yoki sotib olishni yana tilga olmasliging sharti bilan.",note:"شَرِيطَةَ أَنْ — ...sharti bilan. أَلَّا — أَنْ + لَا."},
{num:156,time:"00:13:22,080 --> 00:13:27,340",arabic:"الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ يَا أُمِّي.",segs:[{ar:"الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ،",uz:"Allohga hamd, Allohga hamd"},{ar:"الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ يَا أُمِّي.",uz:"Allohga hamd, Allohga hamd, onajon."}],full_uz:"Allohga hamd, Allohga hamd, Allohga hamd, Allohga hamd, onajon.",note:null},
{num:157,time:"00:13:27,340 --> 00:13:31,139",arabic:"أُمِّي، قُولِي لَهُ إِنَّنِي لَنْ أَعُودَ لِذِكْرِ ذَلِكَ أَبَدًا.",segs:[{ar:"أُمِّي، قُولِي لَهُ",uz:"Onajon, unga ayting"},{ar:"إِنَّنِي لَنْ أَعُودَ لِذِكْرِ ذَلِكَ أَبَدًا.",uz:"buni boshqa hech qachon tilga olmasligimni."}],full_uz:"Onajon, unga buni boshqa hech qachon tilga olmasligimni ayting.",note:"قُولِي — ayol kishiga buyruq; erkakka قُلْ deyiladi."},
{num:158,time:"00:13:31,139 --> 00:13:36,340",arabic:"تُرِيدُنِي أَنْ أَعُودَ لَهُ وَأَقُولَ لَهُ مَا قُلْتَ؟",segs:[{ar:"تُرِيدُنِي أَنْ أَعُودَ لَهُ",uz:"Uning oldiga qaytishimni istayapsanmi"},{ar:"وَأَقُولَ لَهُ مَا قُلْتَ؟",uz:"va unga aytganingni aytishimni?"}],full_uz:"Uning oldiga qaytib, aytganingni unga yetkazishimni istayapsanmi?",note:null},
{num:159,time:"00:13:36,340 --> 00:13:37,420",arabic:"أَحْمَقُ أَنْتَ!",segs:null,full_uz:"Ahmoqsan sen!",note:"أَحْمَقُ — oldinga chiqqan xabar; أَنْتَ — ega."},
{num:160,time:"00:13:37,420 --> 00:13:38,840",arabic:"انْتَهَى الْأَمْرُ.",segs:null,full_uz:"Masala hal bo‘ldi.",note:null},
{num:161,time:"00:13:38,840 --> 00:13:40,580",arabic:"تَعُودُ إِلَى الدُّكَّانِ،",segs:null,full_uz:"Do‘konga qaytasan…",note:null},
{num:162,time:"00:13:40,580 --> 00:13:43,379",arabic:"وَابْنُ حَنْبَلٍ لَا يَحْتَاجُ إِلَى وُعُودٍ مِنْكَ.",segs:[{ar:"وَابْنُ حَنْبَلٍ لَا يَحْتَاجُ",uz:"Ibn Hanbal muhtoj emas"},{ar:"إِلَى وُعُودٍ مِنْكَ.",uz:"sening va’dalaringga."}],full_uz:"Ibn Hanbal sening va’dalaringga muhtoj emas.",note:"وُعُودٌ — وَعْدٌ ning ko‘pligi: va’dalar."},
{num:163,time:"00:13:43,379 --> 00:13:49,159",arabic:"أَلَمْ أَقُلْ لَكَ يَا عَامِرُ؟ إِنَّ أُمَّ عَامِرٍ لَا تَعْجِزُ عَنْ شَيْءٍ تُلِحُّ عَلَيْهِ.",segs:[{ar:"أَلَمْ أَقُلْ لَكَ يَا عَامِرُ؟",uz:"Senga aytmadimmi, Omir?"},{ar:"إِنَّ أُمَّ عَامِرٍ لَا تَعْجِزُ عَنْ شَيْءٍ",uz:"Umm Omir biror ishda ojiz qolmaydi"},{ar:"تُلِحُّ عَلَيْهِ.",uz:"unga qat’iy kirishgan bo‘lsa."}],full_uz:"Senga aytmadimmi, Omir? Umm Omir qat’iy kirishgan ishida ojiz qolmaydi.",note:"أَلَحَّ عَلَى — qat’iy talab qilmoq, tinmay urinmoq."},
{num:164,time:"00:13:49,159 --> 00:13:51,519",arabic:"لَكِنَّهُ اشْتَرَطَ شَرْطًا آخَرَ.",segs:null,full_uz:"Ammo u yana bir shart qo‘ydi.",note:"اِشْتَرَطَ — shart qo‘ymoq."},
{num:165,time:"00:13:51,519 --> 00:13:57,279",arabic:"اشْتَرَطَ شَرْطًا آخَرَ؟ مَا هُوَ الشَّرْطُ الَّذِي اشْتَرَطَهُ أَحْمَدُ؟ قُولِي يَا أُمِّي.",segs:[{ar:"اشْتَرَطَ شَرْطًا آخَرَ؟",uz:"Yana bir shart qo‘ydimi?"},{ar:"مَا هُوَ الشَّرْطُ الَّذِي اشْتَرَطَهُ أَحْمَدُ؟",uz:"Ahmad qo‘ygan shart nima ekan?"},{ar:"قُولِي يَا أُمِّي.",uz:"Ayting, onajon."}],full_uz:"Yana bir shart qo‘ydimi? Ahmad qo‘ygan shart nima ekan? Ayting, onajon.",note:null},
{num:166,time:"00:13:57,279 --> 00:13:59,820",arabic:"أَنْ تَنْتَظِمَ بِدَفْعِ الْأُجْرَةِ مَعَ كُلِّ هِلَالٍ.",segs:[{ar:"أَنْ تَنْتَظِمَ بِدَفْعِ الْأُجْرَةِ",uz:"Ijara haqini muntazam to‘lashing"},{ar:"مَعَ كُلِّ هِلَالٍ.",uz:"har yangi oy chiqqanida."}],full_uz:"Har yangi oy chiqqanida ijara haqini muntazam to‘lashing.",note:"هِلَالٌ — yangi oy, hilol. مَعَ كُلِّ هِلَالٍ bu yerda har qamariy oy boshida degani."},
{num:167,time:"00:13:59,820 --> 00:14:02,659",arabic:"لَا بَأْسَ، مَعَ كُلِّ هِلَالٍ أَفْعَلُ يَا أُمِّي، أَفْعَلُ.",segs:[{ar:"لَا بَأْسَ،",uz:"Mayli"},{ar:"مَعَ كُلِّ هِلَالٍ أَفْعَلُ يَا أُمِّي،",uz:"har yangi oyda to‘layman, onajon"},{ar:"أَفْعَلُ.",uz:"to‘layman."}],full_uz:"Mayli, har yangi oyda to‘layman, onajon, to‘layman.",note:"أَفْعَلُ so‘zma-so‘z «qilaman»; bu yerda oldingi to‘lash ishini anglatadi."},
{num:168,time:"00:14:02,659 --> 00:14:05,620",arabic:"وَلَا تَنْسَ أَنْ تَدْفَعَ لَهُ أُجْرَةَ الْأَشْهُرِ الْمَاضِيَةِ.",segs:[{ar:"وَلَا تَنْسَ أَنْ تَدْفَعَ لَهُ",uz:"Unga to‘lashni ham unutma"},{ar:"أُجْرَةَ الْأَشْهُرِ الْمَاضِيَةِ.",uz:"o‘tgan oylarning ijara haqini."}],full_uz:"Unga o‘tgan oylarning ijara haqini to‘lashni ham unutma.",note:"تَنْسَى taqiq لَا sidan keyin لَا تَنْسَ bo‘ladi: oxirgi zaif harf tushadi."},
{num:169,time:"00:14:05,620 --> 00:14:07,419",arabic:"زَوْجَتِي، أَفْعَلُ، لَا بَأْسَ، أَفْعَلُ.",segs:[{ar:"زَوْجَتِي، أَفْعَلُ،",uz:"Xotinim, qilaman"},{ar:"لَا بَأْسَ، أَفْعَلُ.",uz:"mayli, qilaman."}],full_uz:"Xotinim, qilaman, mayli, qilaman.",note:null},
{num:170,time:"00:14:07,419 --> 00:14:13,439",arabic:"كُنْتُ أَنَا وَأَخِي عِيسَى فِي الْكُتَّابِ،",segs:[{ar:"كُنْتُ أَنَا وَأَخِي عِيسَى",uz:"Men va akam Iso edik"},{ar:"فِي الْكُتَّابِ،",uz:"boshlang‘ich maktabda,"}],full_uz:"Men va akam Iso boshlang‘ich maktabda edik…",note:"كُتَّابٌ — an’anaviy boshlang‘ich maktab; كِتَابٌ — kitob."},
{num:171,time:"00:14:13,439 --> 00:14:18,719",arabic:"وَكُنَّا نَصَارَى عَلَى دِينِ عِيسَى عَلَيْهِ وَعَلَى نَبِيِّنَا السَّلَامُ،",segs:[{ar:"وَكُنَّا نَصَارَى",uz:"Biz nasroniy edik"},{ar:"عَلَى دِينِ عِيسَى",uz:"Iso dinida"},{ar:"عَلَيْهِ وَعَلَى نَبِيِّنَا السَّلَامُ،",uz:"unga va payg‘ambarimizga salom bo‘lsin,"}],full_uz:"Biz Iso dinidagi nasroniy edik. Unga va payg‘ambarimizga salom bo‘lsin.",note:"نَصَارَى — نَصْرَانِيٌّ ning ko‘pligi: nasroniylar."},
{num:172,time:"00:14:18,719 --> 00:14:22,860",arabic:"وَكَانَ الْمُعَلِّمُ يُعَلِّمُ الصِّبْيَانَ،",segs:[{ar:"وَكَانَ الْمُعَلِّمُ",uz:"Muallim esa"},{ar:"يُعَلِّمُ الصِّبْيَانَ،",uz:"bolalarga o‘rgatar edi,"}],full_uz:"Muallim bolalarga o‘rgatar edi…",note:"صِبْيَانٌ — صَبِيٌّ ning ko‘pligi: bolalar."},
{num:173,time:"00:14:22,860 --> 00:14:26,679",arabic:"أَبٌ وَابْنٌ وَرُوحُ قُدُسٍ.",segs:[{ar:"أَبٌ وَابْنٌ",uz:"Ota va O‘g‘il"},{ar:"وَرُوحُ قُدُسٍ.",uz:"va Muqaddas Ruh."}],full_uz:"Ota, O‘g‘il va Muqaddas Ruh.",note:null},
{num:174,time:"00:14:26,679 --> 00:14:31,099",arabic:"فَكُنْتُ أَعْتَرِضُ عَلَيْهِ وَأَقُولُ: بَلْ أَحَدٌ، أَحَدٌ.",segs:[{ar:"فَكُنْتُ أَعْتَرِضُ عَلَيْهِ",uz:"Men unga e’tiroz bildirardim"},{ar:"وَأَقُولُ:",uz:"va derdim"},{ar:"بَلْ أَحَدٌ، أَحَدٌ.",uz:"yo‘q, Yagona, Yagona."}],full_uz:"Men unga e’tiroz bildirib: «Yo‘q, Yagona, Yagona», derdim.",note:"اِعْتَرَضَ عَلَى — ...ga e’tiroz bildirmoq."},
{num:175,time:"00:14:31,099 --> 00:14:35,199",arabic:"فَيَضْرِبُنِي الْمُعَلِّمُ عَلَى ذَلِكَ ضَرْبًا شَدِيدًا،",segs:[{ar:"فَيَضْرِبُنِي الْمُعَلِّمُ عَلَى ذَلِكَ",uz:"Muallim buning uchun meni urardi"},{ar:"ضَرْبًا شَدِيدًا،",uz:"qattiq urardi,"}],full_uz:"Muallim buning uchun meni qattiq urardi…",note:"ضَرْبًا شَدِيدًا — fe’lning qanday bajarilganini ko‘rsatuvchi maf’ul mutlaq va uning sifati."},
{num:176,time:"00:14:35,200 --> 00:14:41,540",arabic:"حَتَّى كَانَ يَوْمٌ ضَرَبَنِي فِيهِ الْمُعَلِّمُ ضَرْبًا مُبَرِّحًا،",segs:[{ar:"حَتَّى كَانَ يَوْمٌ",uz:"Nihoyat bir kun bo‘ldiki"},{ar:"ضَرَبَنِي فِيهِ الْمُعَلِّمُ",uz:"o‘sha kuni muallim meni urdi"},{ar:"ضَرْبًا مُبَرِّحًا،",uz:"ayovsiz ravishda,"}],full_uz:"Nihoyat bir kuni muallim meni ayovsiz urdi…",note:"ضَرْبٌ مُبَرِّحٌ — juda qattiq, og‘riqli kaltaklash."},
{num:177,time:"00:14:41,540 --> 00:14:47,900",arabic:"فَهِمْتُ عَلَى وَجْهِي يَوْمَهَا فِي بِلَادِ اللَّهِ الْوَاسِعَةِ.",segs:[{ar:"فَهِمْتُ عَلَى وَجْهِي يَوْمَهَا",uz:"O‘sha kuni boshim oqqan tomonga ketdim"},{ar:"فِي بِلَادِ اللَّهِ الْوَاسِعَةِ.",uz:"Allohning keng yerlarida."}],full_uz:"O‘sha kuni Allohning keng yerlarida boshim oqqan tomonga ketdim.",note:"هِمْتُ — هَامَ يَهِيمُ fe’lidan: kezdim, tentiradim. Boshidagi فَـ bilan فَهِمْتُ yoziladi; bu yerda فَهِمَ — tushunmoq fe’li emas."},
{num:178,time:"00:14:47,900 --> 00:14:51,560",arabic:"فَخَافَ عَلَيَّ أَهْلِي كَثِيرًا.",segs:null,full_uz:"Oilam mendan juda xavotir oldi.",note:"خَافَ عَلَيَّ — menga biror yomonlik yetishidan qo‘rqdi; خَافَ مِنِّي — mendan qo‘rqdi."},
{num:179,time:"00:14:51,560 --> 00:14:54,060",arabic:"وَكَانَتْ أُمِّي تَقُولُ،",segs:null,full_uz:"Onam aytar edi…",note:null},
{num:180,time:"00:14:54,060 --> 00:14:57,620",arabic:"لَئِنْ رَدَّ اللَّهُ عَلَيَّ ابْنِي مَعْرُوفًا،",segs:[{ar:"لَئِنْ رَدَّ اللَّهُ عَلَيَّ",uz:"Qasamki, agar Alloh menga qaytarsa"},{ar:"ابْنِي مَعْرُوفًا،",uz:"o‘g‘lim Ma’rufni,"}],full_uz:"Qasamki, agar Alloh o‘g‘lim Ma’rufni menga qaytarsa…",note:"لَئِنْ — qasam bilan bog‘langan shart. مَعْرُوفًا bu yerda kishining ismi."},
{num:181,time:"00:14:57,620 --> 00:15:00,740",arabic:"لَأَتَّبِعَنَّهُ عَلَى أَيِّ دِينٍ كَانَ.",segs:[{ar:"لَأَتَّبِعَنَّهُ",uz:"unga albatta ergashaman"},{ar:"عَلَى أَيِّ دِينٍ كَانَ.",uz:"qaysi dinda bo‘lishidan qat’i nazar."}],full_uz:"Qaysi dinda bo‘lishidan qat’i nazar, unga albatta ergashaman.",note:"لَـ va نَّ qasam javobini kuchaytiradi. Oxirgi هُ — unga, uni."},
{num:182,time:"00:15:00,740 --> 00:15:05,060",arabic:"ثُمَّ قَدِمْتُ إِلَيْهِمْ بَعْدَ سِنِينَ عِدَّةٍ،",segs:[{ar:"ثُمَّ قَدِمْتُ إِلَيْهِمْ",uz:"Keyin ularning oldiga keldim"},{ar:"بَعْدَ سِنِينَ عِدَّةٍ،",uz:"bir necha yildan so‘ng,"}],full_uz:"Keyin bir necha yildan so‘ng ularning oldiga keldim…",note:"سِنِينَ عِدَّةٍ — bir necha yil. قَدِمَ — kelmoq, yetib kelmoq."},
{num:183,time:"00:15:05,060 --> 00:15:08,539",arabic:"فَفَرِحَتْ أُمِّي بِلِقَائِي كَثِيرًا،",segs:[{ar:"فَفَرِحَتْ أُمِّي",uz:"Onam xursand bo‘ldi"},{ar:"بِلِقَائِي كَثِيرًا،",uz:"men bilan uchrashganidan juda,"}],full_uz:"Onam men bilan uchrashganidan juda xursand bo‘ldi…",note:"فَرِحَ بِـ — ...dan xursand bo‘lmoq."},
{num:184,time:"00:15:08,539 --> 00:15:10,700",arabic:"ثُمَّ قَالَتْ لِي،",segs:null,full_uz:"Keyin menga dedi…",note:null},
{num:185,time:"00:15:12,500 --> 00:15:16,259",arabic:"عَلَى أَيِّ دِينٍ أَنْتَ؟",segs:null,full_uz:"Sen qaysi dindasan?",note:null},
{num:186,time:"00:15:16,259 --> 00:15:17,740",arabic:"فَقُلْتُ: عَلَى دِينِ الْإِسْلَامِ.",segs:[{ar:"فَقُلْتُ:",uz:"Men dedim"},{ar:"عَلَى دِينِ الْإِسْلَامِ.",uz:"Islom dinidaman."}],full_uz:"Men: «Islom dinidaman», dedim.",note:null},
{num:187,time:"00:15:17,740 --> 00:15:22,120",arabic:"قَالَتْ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ،",segs:[{ar:"قَالَتْ: أَشْهَدُ",uz:"U dedi: guvohlik beraman"},{ar:"أَنْ لَا إِلَهَ إِلَّا اللَّهُ،",uz:"Allohdan o‘zga iloh yo‘qligiga,"}],full_uz:"U: «Allohdan o‘zga iloh yo‘qligiga guvohlik beraman…», dedi.",note:"أَشْهَدُ — guvohlik beraman; أُشْهِدُ — guvoh qilaman."},
{num:188,time:"00:15:22,120 --> 00:15:25,039",arabic:"وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ.",segs:[{ar:"وَأَشْهَدُ",uz:"Va guvohlik beraman"},{ar:"أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ.",uz:"Muhammad Allohning Rasuli ekaniga."}],full_uz:"Va Muhammad Allohning Rasuli ekaniga guvohlik beraman.",note:null},
{num:189,time:"00:15:25,039 --> 00:15:27,539",arabic:"فَأَسْلَمَتْ أُمِّي،",segs:null,full_uz:"Shunday qilib, onam musulmon bo‘ldi…",note:"أَسْلَمَ — Islomni qabul qilmoq; boshqa kontekstlarda taslim bo‘lmoq."},
{num:190,time:"00:15:27,539 --> 00:15:30,819",arabic:"ثُمَّ أَسْلَمَ أَبِي وَأَخِي عِيسَى،",segs:[{ar:"ثُمَّ أَسْلَمَ أَبِي",uz:"Keyin otam musulmon bo‘ldi"},{ar:"وَأَخِي عِيسَى،",uz:"akam Iso ham,"}],full_uz:"Keyin otam va akam Iso ham musulmon bo‘ldi…",note:null},
{num:191,time:"00:15:30,819 --> 00:15:34,299",arabic:"وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ،",segs:[{ar:"وَالْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"رَبِّ الْعَالَمِينَ،",uz:"olamlarning Rabbiga,"}],full_uz:"Olamlarning Rabbi Allohga hamd bo‘lsin…",note:null},
{num:192,time:"00:15:34,299 --> 00:15:39,500",arabic:"الَّذِي مَنَّ عَلَيَّ وَعَلَى أَهْلِي بِنِعْمَةِ الْإِيمَانِ وَالْإِسْلَامِ.",segs:[{ar:"الَّذِي مَنَّ عَلَيَّ وَعَلَى أَهْلِي",uz:"U menga va oilamga ato etdi"},{ar:"بِنِعْمَةِ الْإِيمَانِ وَالْإِسْلَامِ.",uz:"iymon va Islom ne’matini."}],full_uz:"U menga va oilamga iymon va Islom ne’matini ato etdi.",note:"مَنَّ عَلَيْهِ بِـ — unga bir ne’mat ato etmoq."},
{num:193,time:"00:15:39,500 --> 00:15:49,740",arabic:"مَا بَالُ أُمِّي نَائِمَةً فِي مِثْلِ هَذِهِ السَّاعَةِ؟",segs:[{ar:"مَا بَالُ أُمِّي نَائِمَةً",uz:"Nega onam uxlab yotibdi"},{ar:"فِي مِثْلِ هَذِهِ السَّاعَةِ؟",uz:"bunday paytda?"}],full_uz:"Nega onam bunday paytda uxlab yotibdi?",note:"مَا بَالُ ...؟ — ...ga nima bo‘ldi, nega ...? نَائِمَةً — onaning holatini bildiruvchi hol."},
{num:194,time:"00:15:59,620 --> 00:16:02,419",arabic:"أُمَّ عَامِرٍ، أَنَا عَامِرٌ وَلَدُكِ.",segs:[{ar:"أُمَّ عَامِرٍ،",uz:"Umm Omir,"},{ar:"أَنَا عَامِرٌ وَلَدُكِ.",uz:"men Omirman, o‘g‘lingizman."}],full_uz:"Umm Omir, men o‘g‘lingiz Omirman.",note:"وَلَدُكِ — sening farzanding; ـكِ ayol kishiga murojaatni bildiradi."},
{num:195,time:"00:16:02,419 --> 00:16:03,500",arabic:"هَيَّا انْهَضِي.",segs:null,full_uz:"Qani, turing.",note:"انْهَضِي — ayol kishiga qaratilgan tur buyrug‘i; erkakka انْهَضْ deyiladi."},
{num:196,time:"00:16:06,099 --> 00:16:07,699",arabic:"مَا بِكِ يَا أُمِّي؟",segs:[{ar:"مَا بِكِ",uz:"Sizga nima bo‘ldi"},{ar:"يَا أُمِّي؟",uz:"onajon?"}],full_uz:"Sizga nima bo‘ldi, onajon?",note:"مَا بِكَ؟ erkakka, مَا بِكِ؟ ayolga sizga nima bo‘ldi? deb murojaat qilish uchun ishlatiladi."},
{num:197,time:"00:16:07,699 --> 00:16:09,620",arabic:"يَا وَيْلِي، أُمِّي مَاتَتْ!",segs:[{ar:"يَا وَيْلِي،",uz:"Voy, sho‘rim!"},{ar:"أُمِّي مَاتَتْ!",uz:"Onam vafot etdi!"}],full_uz:"Voy, sho‘rim! Onam vafot etdi!",note:"يَا وَيْلِي — kuchli qayg‘u yoki vahimani ifodalovchi undov."},
{num:198,time:"00:16:09,620 --> 00:16:12,219",arabic:"أُمُّكَ يَا عَامِرُ مَاتَتْ!",segs:[{ar:"أُمُّكَ يَا عَامِرُ",uz:"Onang, ey Omir,"},{ar:"مَاتَتْ!",uz:"vafot etdi!"}],full_uz:"Omir, onang vafot etdi!",note:null},
{num:199,time:"00:16:12,219 --> 00:16:15,159",arabic:"يَا حَسْرَتِي، يَا وَيْلِي!",segs:[{ar:"يَا حَسْرَتِي،",uz:"Voy, hasratim!"},{ar:"يَا وَيْلِي!",uz:"Voy, sho‘rim!"}],full_uz:"Voy, hasratim! Voy, sho‘rim!",note:"حَسْرَةٌ — qattiq afsus va armon."},
{num:200,time:"00:16:18,339 --> 00:16:20,319",arabic:"يَا سَلَمَةُ، أُمِّي مَاتَتْ!",segs:[{ar:"يَا سَلَمَةُ،",uz:"Salama!"},{ar:"أُمِّي مَاتَتْ!",uz:"Onam vafot etdi!"}],full_uz:"Salama, onam vafot etdi!",note:null},
{num:201,time:"00:16:20,319 --> 00:16:22,439",arabic:"يَا عُمَيْرُ، جَدَّتُكَ مَاتَتْ!",segs:[{ar:"يَا عُمَيْرُ،",uz:"Umayr!"},{ar:"جَدَّتُكَ مَاتَتْ!",uz:"Buving vafot etdi!"}],full_uz:"Umayr, buving vafot etdi!",note:"جَدَّةٌ — buvi; جَدٌّ — bobo."},
{num:202,time:"00:16:22,439 --> 00:16:23,980",arabic:"يَا وَيْلِي!",segs:null,full_uz:"Voy, sho‘rim!",note:null},
{num:203,time:"00:16:23,980 --> 00:16:26,860",arabic:"يَا وَيْلِي عَلَيْكَ يَا عَامِرُ!",segs:[{ar:"يَا وَيْلِي عَلَيْكَ",uz:"Sening holingga voy!"},{ar:"يَا عَامِرُ!",uz:"Ey Omir!"}],full_uz:"Voy holingga, Omir!",note:null},
{num:204,time:"00:16:26,860 --> 00:16:32,759",arabic:"أُمِّي مَاتَتْ يَا سَلَمَةُ!",segs:[{ar:"أُمِّي مَاتَتْ",uz:"Onam vafot etdi"},{ar:"يَا سَلَمَةُ!",uz:"Salama!"}],full_uz:"Onam vafot etdi, Salama!",note:null},
{num:205,time:"00:16:32,759 --> 00:16:34,879",arabic:"اتَّقِ اللَّهَ يَا عَامِرُ.",segs:[{ar:"اتَّقِ اللَّهَ",uz:"Allohdan qo‘rq"},{ar:"يَا عَامِرُ.",uz:"Omir."}],full_uz:"Allohdan qo‘rq, Omir.",note:"اتَّقِ — اِتَّقَى fe’lining buyruq shakli; saqlan, taqvo qil ma’nolarida keladi."},
{num:206,time:"00:16:34,879 --> 00:16:36,879",arabic:"مَا لَكَ تُوَلْوِلُ كَالنِّسَاءِ؟",segs:[{ar:"مَا لَكَ تُوَلْوِلُ",uz:"Nega voy-voylab yig‘layapsan"},{ar:"كَالنِّسَاءِ؟",uz:"ayollardek?"}],full_uz:"Nega ayollardek voy-voylab yig‘layapsan?",note:"وَلْوَلَ — voy-voylab yig‘lamoq; كَـ — kabi, o‘xshab."},
{num:207,time:"00:16:36,879 --> 00:16:39,120",arabic:"مَوْتُهَا أَرْوَحُ لَهَا وَلِغَيْرِهَا.",segs:[{ar:"مَوْتُهَا أَرْوَحُ لَهَا",uz:"Uning o‘limi o‘ziga tinchroq"},{ar:"وَلِغَيْرِهَا.",uz:"boshqalarga ham."}],full_uz:"Uning o‘limi o‘ziga ham, boshqalarga ham tinchroq.",note:"أَرْوَحُ — ko‘proq rohat yoki yengillik keltiradigan."},
{num:208,time:"00:16:39,120 --> 00:16:41,379",arabic:"يَكْفِيهَا مِنَ الْعُمُرِ مَا عَاشَتْ.",segs:[{ar:"يَكْفِيهَا مِنَ الْعُمُرِ",uz:"Umrdan unga yetadi"},{ar:"مَا عَاشَتْ.",uz:"yashaganicha."}],full_uz:"Shuncha yashagani unga yetadi.",note:"مَا عَاشَتْ — bu yerda uning yashagani, yashagan muddati ma’nosida."},
{num:209,time:"00:16:41,379 --> 00:16:44,159",arabic:"أَلَمْ يُصْبِحْ عُمْرُهَا مِئَتَيْ سَنَةٍ؟",segs:[{ar:"أَلَمْ يُصْبِحْ عُمْرُهَا",uz:"Uning yoshi bo‘lmadimi"},{ar:"مِئَتَيْ سَنَةٍ؟",uz:"ikki yuz yosh?"}],full_uz:"Uning yoshi ikki yuzga yetmadimi?",note:"مِئَتَيْ — مِئَتَانِ so‘zining tushum yoki qaratqich shakli; izofada oxirgi ن tushadi."},
{num:210,time:"00:16:44,159 --> 00:16:46,259",arabic:"خَسِئْتِ أَيَّتُهَا الْحِرْبَاءُ!",segs:[{ar:"خَسِئْتِ",uz:"Yo‘qol!"},{ar:"أَيَّتُهَا الْحِرْبَاءُ!",uz:"Ey buqalamun!"}],full_uz:"Yo‘qol, ey buqalamun!",note:"حِرْبَاءٌ — buqalamun; odamga nisbatan haqorat sifatida ham ishlatiladi."},
{num:211,time:"00:16:46,259 --> 00:16:48,139",arabic:"خَيَّبَ اللَّهُ ظُنُونَكِ!",segs:null,full_uz:"Alloh o‘ylaganlaringni puchga chiqarsin!",note:"خَيَّبَ — umidini puchga chiqardi. O‘tgan zamon shakli bu yerda qarg‘ish ma’nosida."},
{num:212,time:"00:16:52,180 --> 00:16:54,440",arabic:"الْحَمْدُ لِلَّهِ، أَحْمَدُكَ يَا رَبِّ!",segs:[{ar:"الْحَمْدُ لِلَّهِ،",uz:"Allohga hamd bo‘lsin!"},{ar:"أَحْمَدُكَ يَا رَبِّ!",uz:"Senga hamd aytaman, Rabbim!"}],full_uz:"Allohga hamd bo‘lsin! Senga hamd aytaman, Rabbim!",note:null},
{num:213,time:"00:16:54,440 --> 00:16:56,180",arabic:"أُمِّي لَمْ تَمُتْ يَا سَلَمَةُ!",segs:[{ar:"أُمِّي لَمْ تَمُتْ",uz:"Onam vafot etmabdi"},{ar:"يَا سَلَمَةُ!",uz:"Salama!"}],full_uz:"Onam vafot etmabdi, Salama!",note:"لَمْ تَمُتْ — o‘lmadi; لَمْ dan keyin تَمُوتُ fe’li jazm bo‘lib, o‘rtadagi و tushadi."},
{num:214,time:"00:16:56,179 --> 00:16:59,679",arabic:"لَيْسَ قَبْلَ أَنْ تَمُوتَ زَوْجَتُكَ الْقَبِيحَةُ.",segs:[{ar:"لَيْسَ قَبْلَ أَنْ تَمُوتَ",uz:"O‘lmagunicha emas"},{ar:"زَوْجَتُكَ الْقَبِيحَةُ.",uz:"sening xunuk xotining."}],full_uz:"Xunuk xotining o‘lmagunicha o‘lmayman.",note:"Javobda oldingi gapdan anglashiladigan o‘lmayman mazmuni qisqartirib aytilgan."},
{num:215,time:"00:16:59,679 --> 00:17:01,919",arabic:"لَا تَمُوتُ الْأَفْعَى مَا لَمْ تُقْتَلْ.",segs:[{ar:"لَا تَمُوتُ الْأَفْعَى",uz:"Ilon o‘lmaydi"},{ar:"مَا لَمْ تُقْتَلْ.",uz:"o‘ldirilmagunicha."}],full_uz:"Ilon o‘ldirilmagunicha o‘lmaydi.",note:"تُقْتَلْ — majhul nisbat: o‘ldirilsa. مَا لَمْ — ...magunicha, ...masa."},
{num:216,time:"00:17:01,919 --> 00:17:03,519",arabic:"تَعْسًا لَكَ يَا عَامِرُ!",segs:[{ar:"تَعْسًا لَكَ",uz:"Qurib ketgur"},{ar:"يَا عَامِرُ!",uz:"Omir!"}],full_uz:"Qurib ketgur, Omir!",note:"تَعْسًا لَكَ — birovga baxtsizlik tilab aytiladigan qarg‘ish."},
{num:217,time:"00:17:03,519 --> 00:17:08,220",arabic:"لَنْ أَمُوتَ قَبْلَ أَنْ تَمُوتِي بِغَيْظِكِ يَا ابْنَةَ الْجَزَّارِ!",segs:[{ar:"لَنْ أَمُوتَ",uz:"Men o‘lmayman"},{ar:"قَبْلَ أَنْ تَمُوتِي بِغَيْظِكِ",uz:"sen alamdan o‘lmaguningcha"},{ar:"يَا ابْنَةَ الْجَزَّارِ!",uz:"ey qassobning qizi!"}],full_uz:"Sen alamdan o‘lmaguningcha men o‘lmayman, ey qassobning qizi!",note:"غَيْظٌ — kuchli g‘azab, alam. أَنْ dan keyin تَمُوتِينَ shaklidagi ن tushadi: تَمُوتِي."},
{num:218,time:"00:17:08,220 --> 00:17:12,279",arabic:"الْحَمْدُ لِلَّهِ، أُمِّي عَلَى قَيْدِ الْحَيَاةِ!",segs:[{ar:"الْحَمْدُ لِلَّهِ،",uz:"Allohga hamd bo‘lsin!"},{ar:"أُمِّي عَلَى قَيْدِ الْحَيَاةِ!",uz:"Onam tirik!"}],full_uz:"Allohga hamd bo‘lsin, onam tirik!",note:"عَلَى قَيْدِ الْحَيَاةِ — tirik, hayot bo‘lgan."},
{num:219,time:"00:17:12,279 --> 00:17:14,019",arabic:"أَحْمَدُكَ يَا رَبِّ!",segs:[{ar:"أَحْمَدُكَ",uz:"Senga hamd aytaman"},{ar:"يَا رَبِّ!",uz:"ey Rabbim!"}],full_uz:"Senga hamd aytaman, Rabbim!",note:null},
{num:220,time:"00:17:14,019 --> 00:17:16,299",arabic:"أُمِّي، ذَهَبَ عَقْلِي خَوْفًا عَلَيْكِ!",segs:[{ar:"أُمِّي،",uz:"Onajon,"},{ar:"ذَهَبَ عَقْلِي",uz:"aqlimni yo‘qotay dedim"},{ar:"خَوْفًا عَلَيْكِ!",uz:"sizdan xavotir olib!"}],full_uz:"Onajon, sizdan xavotir olib, aqlimni yo‘qotay dedim!",note:"خَوْفًا — harakatning sababini bildiradi: qo‘rqqanimdan. خَافَ عَلَى — birovdan xavotir olmoq."},
{num:221,time:"00:17:16,299 --> 00:17:19,019",arabic:"مُتَأَكِّدَةٌ أَنَّكِ عَلَى قَيْدِ الْحَيَاةِ؟",segs:[{ar:"مُتَأَكِّدَةٌ",uz:"Ishonchingiz komilmi"},{ar:"أَنَّكِ عَلَى قَيْدِ الْحَيَاةِ؟",uz:"tirik ekaningizga?"}],full_uz:"Tirik ekaningizga ishonchingiz komilmi?",note:"مُتَأَكِّدَةٌ — ishonchi komil bo‘lgan ayol; erkak uchun مُتَأَكِّدٌ."},
{num:222,time:"00:17:20,119 --> 00:17:23,200",arabic:"لَوْلَا أَنِّي سَمِعْتُكَ تَبْكِي عَلَيَّ بِقَلْبٍ صَادِقٍ،",segs:[{ar:"لَوْلَا أَنِّي سَمِعْتُكَ",uz:"Agar seni eshitmaganimda"},{ar:"تَبْكِي عَلَيَّ",uz:"men uchun yig‘layotganingni"},{ar:"بِقَلْبٍ صَادِقٍ،",uz:"chin dildan,"}],full_uz:"Agar men uchun chin dildan yig‘layotganingni eshitmaganimda,",note:"لَوْلَا أَنِّي... — agar men ...maganimda. Shartning javobi keyingi parchada keladi."},
{num:223,time:"00:17:23,200 --> 00:17:27,220",arabic:"لَقُلْتُ إِنَّكَ خَبِيثٌ مِثْلُ زَوْجَتِكَ.",segs:[{ar:"لَقُلْتُ إِنَّكَ خَبِيثٌ",uz:"seni ham yovuz degan bo‘lardim"},{ar:"مِثْلُ زَوْجَتِكَ.",uz:"xotining kabi."}],full_uz:"Seni ham xotining kabi yovuz degan bo‘lardim.",note:"لَقُلْتُ — oldingi لَوْلَا shartining javobi: aytgan bo‘lardim."},
{num:224,time:"00:17:27,220 --> 00:17:32,240",arabic:"ثُمَّ كَيْفَ لَا أَكُونُ عَلَى قَيْدِ الْحَيَاةِ وَأَنَا أُكَلِّمُكَ أَيُّهَا الْأَحْمَقُ؟",segs:[{ar:"ثُمَّ كَيْفَ لَا أَكُونُ عَلَى قَيْدِ الْحَيَاةِ",uz:"Qolaversa, qanday qilib tirik bo‘lmay"},{ar:"وَأَنَا أُكَلِّمُكَ",uz:"senga gapirib turgan bo‘lsam"},{ar:"أَيُّهَا الْأَحْمَقُ؟",uz:"ey ahmoq?"}],full_uz:"Qolaversa, senga gapirib turib, qanday qilib tirik bo‘lmayman, ey ahmoq?",note:"وَأَنَا أُكَلِّمُكَ — hol jumlasi: senga gapirib turgan holimda."},
{num:225,time:"00:17:32,240 --> 00:17:35,100",arabic:"صَحِيحٌ، تُكَلِّمِينَنِي يَا أُمَّاهُ.",segs:[{ar:"صَحِيحٌ،",uz:"To‘g‘ri,"},{ar:"تُكَلِّمِينَنِي يَا أُمَّاهُ.",uz:"menga gapiryapsiz, onajon."}],full_uz:"To‘g‘ri, menga gapiryapsiz, onajon.",note:"تُكَلِّمِينَنِي — sen menga gapiryapsan; oxirgi ـنِي meni yoki menga ma’nosini beradi."},
{num:226,time:"00:17:35,100 --> 00:17:37,840",arabic:"رُبَّمَا كَانَتْ هَذِهِ فَوَاقَ الْمَوْتِ.",segs:[{ar:"رُبَّمَا كَانَتْ هَذِهِ",uz:"Balki bu"},{ar:"فَوَاقَ الْمَوْتِ.",uz:"o‘lim oldidagi qisqa o‘ziga kelishdir."}],full_uz:"Balki bu o‘lim oldidagi qisqa o‘ziga kelishdir.",note:"فَوَاقٌ — qisqa muddatli tin olish yoki o‘ziga kelish; bu yerda o‘lim oldidagi holat nazarda tutilgan."},
{num:227,time:"00:17:37,840 --> 00:17:39,420",arabic:"فَوَاقُ الْمَوْتِ؟",segs:null,full_uz:"O‘lim oldidagi o‘ziga kelishmi?",note:null},
{num:228,time:"00:17:39,740 --> 00:17:40,600",arabic:"اغْرُبْ عَنْ وَجْهِي!",segs:null,full_uz:"Ko‘zimdan yo‘qol!",note:"اغْرُبْ عَنْ وَجْهِي — ko‘zimga ko‘rinma, ko‘zimdan yo‘qol ma’nosidagi ibora."},
{num:229,time:"00:17:41,700 --> 00:17:43,819",arabic:"اغْرُبْ عَنْ وَجْهِي، قَبَّحَكَ اللَّهُ!",segs:[{ar:"اغْرُبْ عَنْ وَجْهِي،",uz:"Ko‘zimdan yo‘qol!"},{ar:"قَبَّحَكَ اللَّهُ!",uz:"Alloh yuzingni qora qilsin!"}],full_uz:"Ko‘zimdan yo‘qol, Alloh yuzingni qora qilsin!",note:"قَبَّحَكَ اللَّهُ — qarg‘ish iborasi; so‘zma-so‘z: Alloh seni xunuk qilsin."},
{num:230,time:"00:17:43,819 --> 00:17:45,480",arabic:"اسْتَغْفِرِي اللَّهَ يَا أُمِّي.",segs:[{ar:"اسْتَغْفِرِي اللَّهَ",uz:"Allohdan mag‘firat so‘rang"},{ar:"يَا أُمِّي.",uz:"onajon."}],full_uz:"Allohdan mag‘firat so‘rang, onajon.",note:"اسْتَغْفِرِي — ayol kishiga qaratilgan buyruq: mag‘firat so‘ra."},
{num:231,time:"00:17:45,480 --> 00:17:45,980",arabic:"اذْهَبْ!",segs:null,full_uz:"Ket!",note:null},
{num:232,time:"00:17:48,640 --> 00:17:51,840",arabic:"قَبَّحَكَ اللَّهُ وَقَبَّحَ زَوْجَتَكَ!",segs:[{ar:"قَبَّحَكَ اللَّهُ",uz:"Alloh sening yuzingni qora qilsin"},{ar:"وَقَبَّحَ زَوْجَتَكَ!",uz:"xotiningnikini ham!"}],full_uz:"Alloh sening ham, xotiningning ham yuzini qora qilsin!",note:null},
{num:233,time:"00:17:51,839 --> 00:17:56,859",arabic:"أَخْبَرَنَا مَالِكٌ عَنْ صَفْوَانَ بْنِ سُلَيْمٍ،",segs:[{ar:"أَخْبَرَنَا مَالِكٌ",uz:"Bizga Molik xabar berdi"},{ar:"عَنْ صَفْوَانَ بْنِ سُلَيْمٍ،",uz:"Safvon ibn Sulaymdan,"}],full_uz:"Bizga Molik Safvon ibn Sulaymdan rivoyat qildi,",note:"أَخْبَرَنَا — bizga xabar berdi; عَنْ rivoyat kimdan olinganini bildiradi."},
{num:234,time:"00:17:56,859 --> 00:17:59,599",arabic:"عَنْ عَطَاءِ بْنِ يَسَارٍ،",segs:null,full_uz:"u Ato ibn Yasordan,",note:"عَنْ bilan boshlangan bu parcha oldingi rivoyat zanjirini davom ettiradi."},
{num:235,time:"00:17:59,599 --> 00:18:01,299",arabic:"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ،",segs:null,full_uz:"u Abu Sa’id Xudriydan rivoyat qildi:",note:"أَبُو so‘zi عَنْ dan keyin qaratqich holatida أَبِي shaklida keladi."},
{num:236,time:"00:18:01,299 --> 00:18:04,720",arabic:"أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:",segs:[{ar:"أَنَّ رَسُولَ اللَّهِ",uz:"Allohning Rasuli"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salavot va salom yo‘llasin"},{ar:"قَالَ:",uz:"dedilar:"}],full_uz:"Allohning Rasuli, sollallohu alayhi vasallam, dedilar:",note:"أَنَّ oldingi rivoyatning mazmunini kiritadi; undan keyingi رَسُولَ tushum holatida kelgan."},
{num:237,time:"00:18:04,720 --> 00:18:08,019",arabic:"غُسْلُ يَوْمِ الْجُمُعَةِ،",segs:null,full_uz:"Juma kuni g‘usl qilish",note:"غُسْلٌ — g‘usl, butun badanni yuvish. Gapning kesimi keyingi parchada."},
{num:238,time:"00:18:08,019 --> 00:18:10,500",arabic:"وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ.",segs:[{ar:"وَاجِبٌ",uz:"vojibdir"},{ar:"عَلَى كُلِّ مُحْتَلِمٍ.",uz:"har bir balog‘atga yetgan kishiga."}],full_uz:"Har bir balog‘atga yetgan kishiga vojibdir.",note:"مُحْتَلِمٌ — aslida ehtilom bo‘lgan kishi; bu gapda balog‘atga yetgan kishi ma’nosida."},
{num:239,time:"00:18:10,500 --> 00:18:12,819",arabic:"وَالْأَمْرُ بِالْغُسْلِ،",segs:null,full_uz:"G‘usl qilish haqidagi buyruq esa",note:"الْأَمْرُ بِـ — biror narsani buyurish. Fikr keyingi parchada davom etadi."},
{num:240,time:"00:18:12,819 --> 00:18:15,179",arabic:"يَحْتَمِلُ مَعْنَيَيْنِ.",segs:null,full_uz:"ikki ma’noni anglatishi mumkin.",note:"مَعْنَيَيْنِ — ikkita ma’no; مَعْنًى so‘zining ikkilik tushum shakli."},
{num:241,time:"00:18:15,179 --> 00:18:19,299",arabic:"الظَّاهِرُ مِنْهُمَا أَنَّهُ وَاجِبٌ،",segs:[{ar:"الظَّاهِرُ مِنْهُمَا",uz:"U ikkisidan zohir bo‘lgani"},{ar:"أَنَّهُ وَاجِبٌ،",uz:"uning vojib ekanidir,"}],full_uz:"U ikki ma’nodan zohir bo‘lgani — uning vojib ekanidir.",note:"مِنْهُمَا — u ikkisidan; ـهُمَا ikkilik olmoshi."},
{num:242,time:"00:18:19,299 --> 00:18:24,720",arabic:"فَلَا تُجْزِئُ الطَّهَارَةُ لِصَلَاةِ الْجُمُعَةِ إِلَّا بِالْغُسْلِ،",segs:[{ar:"فَلَا تُجْزِئُ الطَّهَارَةُ",uz:"Shunda poklanish kifoya qilmaydi"},{ar:"لِصَلَاةِ الْجُمُعَةِ",uz:"juma namozi uchun"},{ar:"إِلَّا بِالْغُسْلِ،",uz:"g‘usl bilangina kifoya qiladi,"}],full_uz:"Bunda juma namozi uchun poklanish faqat g‘usl bilangina kifoya qiladi.",note:"أَجْزَأَ — kifoya qilmoq, talabni qondirmoq. لَا ... إِلَّا — faqat ...gina."},
{num:243,time:"00:18:24,720 --> 00:18:30,680",arabic:"كَمَا لَا يُجْزِئُ فِي طَهَارَةِ الْجُنُبِ غَيْرُ الْغُسْلِ.",segs:[{ar:"كَمَا لَا يُجْزِئُ",uz:"Xuddi kifoya qilmaganidek"},{ar:"فِي طَهَارَةِ الْجُنُبِ",uz:"junub kishining poklanishida"},{ar:"غَيْرُ الْغُسْلِ.",uz:"g‘usldan boshqa narsa."}],full_uz:"Xuddi junub kishining poklanishida g‘usldan boshqa narsa kifoya qilmaganidek.",note:"الْجُنُبُ — junublik holatidagi kishi. غَيْرُ الْغُسْلِ — g‘usldan boshqa narsa."},
{num:244,time:"00:18:30,680 --> 00:18:36,519",arabic:"وَيَحْتَمِلُ أَنَّهُ وَاجِبٌ فِي الِاخْتِيَارِ وَالْأَخْلَاقِ وَالنَّظَافَةِ.",segs:[{ar:"وَيَحْتَمِلُ أَنَّهُ وَاجِبٌ",uz:"Yana uning zarur ekani nazarda tutilgan bo‘lishi mumkin"},{ar:"فِي الِاخْتِيَارِ",uz:"afzal ko‘rish jihatidan"},{ar:"وَالْأَخْلَاقِ وَالنَّظَافَةِ.",uz:"odob va tozalik jihatidan."}],full_uz:"Yoki uning afzal ko‘rish, odob va tozalik jihatidan zarurligi nazarda tutilgan bo‘lishi mumkin.",note:"يَحْتَمِلُ أَنَّ — ...degan ma’noni ham anglatishi mumkin; talqin ehtimolini bildiradi."},
{num:245,time:"00:18:36,519 --> 00:18:38,299",arabic:"وَاللَّهُ أَعْلَمُ.",segs:null,full_uz:"Alloh yaxshiroq biladi.",note:"أَعْلَمُ — yaxshiroq biluvchi; أَفْعَلُ qolipidagi orttirma-qiyosiy shakl."},
{num:246,time:"00:18:38,299 --> 00:18:46,680",arabic:"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ.",segs:[{ar:"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ،",uz:"Allohim, Senga hamd aytib, Seni barcha nuqsonlardan pok deb bilaman."},{ar:"أَشْهَدُ",uz:"Guvohlik beraman"},{ar:"أَنْ لَا إِلَهَ إِلَّا أَنْتَ،",uz:"Sendan boshqa iloh yo‘qligiga."},{ar:"أَسْتَغْفِرُكَ",uz:"Sendan mag‘firat so‘rayman"},{ar:"وَأَتُوبُ إِلَيْكَ.",uz:"va Senga tavba qilaman."}],full_uz:"Allohim, Senga hamd aytib, Seni barcha nuqsonlardan pok deb bilaman. Sendan boshqa iloh yo‘qligiga guvohlik beraman. Sendan mag‘firat so‘rayman va Senga tavba qilaman.",note:"اللَّهُمَّ — ey Alloh. أَسْتَغْفِرُكَ — Sendan kechirim so‘rayman; أَتُوبُ إِلَيْكَ — Senga tavba qilaman."},
{num:247,time:"00:18:46,680 --> 00:18:50,120",arabic:"ائْذَنُوا لِي أَيُّهَا الْإِخْوَةُ، أَسْتَوْدِعُكُمُ اللَّهَ.",segs:[{ar:"ائْذَنُوا لِي",uz:"Menga ruxsat bering"},{ar:"أَيُّهَا الْإِخْوَةُ،",uz:"birodarlar."},{ar:"أَسْتَوْدِعُكُمُ اللَّهَ.",uz:"Sizlarni Allohga omonat topshiraman."}],full_uz:"Ruxsat bering, birodarlar. Sizlarni Allohga omonat topshiraman.",note:"أَسْتَوْدِعُكُمُ اللَّهَ — xayrlashishda aytiladigan Allohga omonat bo‘linglar mazmunidagi ibora."},
{num:248,time:"00:18:50,120 --> 00:19:08,500",arabic:"لَوْ تَدْرِي مَا نُحَصِّلُهُ مِنَ الْعِلْمِ بِجُلُوسِنَا مَعَ الشَّيْخَيْنِ الْمَرِيسِيِّ وَابْنِ الْأَشْرَسِ يَا صُهَيْبُ!",segs:[{ar:"لَوْ تَدْرِي",uz:"Qaniydi bilsang"},{ar:"مَا نُحَصِّلُهُ مِنَ الْعِلْمِ",uz:"qancha ilm olayotganimizni"},{ar:"بِجُلُوسِنَا مَعَ الشَّيْخَيْنِ",uz:"ikki shayx bilan birga o‘tirib"},{ar:"الْمَرِيسِيِّ وَابْنِ الْأَشْرَسِ",uz:"Marisiy va Ibn Ashras bilan"},{ar:"يَا صُهَيْبُ!",uz:"Suhayb!"}],full_uz:"Suhayb, ikki shayx — Marisiy va Ibn Ashras bilan birga o‘tirib qancha ilm olayotganimizni bilsang edi!",note:"لَوْ تَدْرِي — bilsang edi; bu yerda hayrat va istakni bildiradi. الشَّيْخَيْنِ — ikki shayx."},
{num:249,time:"00:19:08,500 --> 00:19:14,600",arabic:"أَتَدْرِي أَنَّ شَيْخَنَا الْمَرِيسِيَّ كَانَ مِنْ تَلَامِيذِ الْإِمَامِ أَبِي يُوسُفَ الْقَاضِي رَحِمَهُ اللَّهُ؟",segs:[{ar:"أَتَدْرِي",uz:"Bilasanmi"},{ar:"أَنَّ شَيْخَنَا الْمَرِيسِيَّ",uz:"shayximiz Marisiy"},{ar:"كَانَ مِنْ تَلَامِيذِ الْإِمَامِ أَبِي يُوسُفَ الْقَاضِي",uz:"imom qozi Abu Yusufning shogirdlaridan bo‘lganini"},{ar:"رَحِمَهُ اللَّهُ؟",uz:"Alloh uni rahmat qilsin?"}],full_uz:"Shayximiz Marisiy imom qozi Abu Yusufning shogirdlaridan bo‘lganini bilasanmi? Alloh uni rahmat qilsin.",note:"تَلَامِيذُ — تِلْمِيذٌ so‘zining ko‘pligi: shogirdlar."},
{num:250,time:"00:19:14,599 --> 00:19:18,559",arabic:"أَحَقًّا مَا تَقُولُ؟",segs:null,full_uz:"Aytayotganing rostmi?",note:"أَحَقًّا — rostdanmi, haqiqatanmi; أَـ so‘roq yuklamasi."},
{num:251,time:"00:19:18,559 --> 00:19:22,259",arabic:"أَجَلْ، إِنَّهُ ظَرْفٌ مُلِئَ عِلْمًا وَفِقْهًا يَا صُهَيْبُ.",segs:[{ar:"أَجَلْ،",uz:"Ha,"},{ar:"إِنَّهُ ظَرْفٌ",uz:"u bir idishki"},{ar:"مُلِئَ عِلْمًا وَفِقْهًا",uz:"ilm va fiqh bilan to‘ldirilgan"},{ar:"يَا صُهَيْبُ.",uz:"Suhayb."}],full_uz:"Ha, Suhayb, u ilm va fiqh bilan to‘lgan idishdir.",note:"ظَرْفٌ — bu yerda idish ma’nosida, bilimdon insonga o‘xshatish uchun ishlatilgan. مُلِئَ — to‘ldirildi."},
{num:252,time:"00:19:22,259 --> 00:19:27,859",arabic:"لَيْتَكَ تُرَافِقُنِي ذَاتَ مَرَّةٍ وَتَرَى بِعَيْنِكَ وَتَسْمَعُ بِأُذُنِكَ مَا أَقُولُهُ لَكَ.",segs:[{ar:"لَيْتَكَ تُرَافِقُنِي",uz:"Qaniydi menga hamroh bo‘lsang"},{ar:"ذَاتَ مَرَّةٍ",uz:"bir safar"},{ar:"وَتَرَى بِعَيْنِكَ",uz:"va o‘z ko‘zing bilan ko‘rsang"},{ar:"وَتَسْمَعُ بِأُذُنِكَ",uz:"o‘z qulog‘ing bilan eshitsang"},{ar:"مَا أَقُولُهُ لَكَ.",uz:"senga aytayotganlarimni."}],full_uz:"Qaniydi bir safar menga hamroh bo‘lib, senga aytayotganlarimni o‘z ko‘zing bilan ko‘rib, o‘z qulog‘ing bilan eshitsang.",note:"لَيْتَكَ — qaniydi sen; istak bildiradi. ذَاتَ مَرَّةٍ — bir safar."},
{num:253,time:"00:19:27,859 --> 00:19:46,000",arabic:"كَأَنِّي بِكَ يَا صَدِيقِي تُقْنِعُنِي بِالِانْضِمَامِ إِلَى الْمُعْتَزِلَةِ؟",segs:[{ar:"كَأَنِّي بِكَ يَا صَدِيقِي",uz:"Menimcha, do‘stim, sen"},{ar:"تُقْنِعُنِي بِالِانْضِمَامِ",uz:"meni qo‘shilishga ko‘ndiryapsan"},{ar:"إِلَى الْمُعْتَزِلَةِ؟",uz:"mu’tazilalarga?"}],full_uz:"Do‘stim, meni mu’tazilalarga qo‘shilishga ko‘ndirmoqchiga o‘xshaysan?",note:"أَقْنَعَ بِـ — biror narsaga ko‘ndirmoq. الِانْضِمَامُ إِلَى — ...ga qo‘shilish."},
{num:254,time:"00:19:46,000 --> 00:19:50,939",arabic:"وَهَلْ أَنْتَ فَتًى غِرٌّ حَتَّى أُقْنِعَكَ بِمَا لَا تُحِبُّ؟",segs:[{ar:"وَهَلْ أَنْتَ فَتًى غِرٌّ",uz:"Sen sodda bir yigitmisan"},{ar:"حَتَّى أُقْنِعَكَ",uz:"men seni ko‘ndira oladigan"},{ar:"بِمَا لَا تُحِبُّ؟",uz:"o‘zing yoqtirmagan narsaga?"}],full_uz:"Sen o‘zing yoqtirmagan narsaga ko‘ndirishim mumkin bo‘lgan sodda bir yigitmisan?",note:"غِرٌّ — tajribasiz, sodda, oson ishonadigan."},
{num:255,time:"00:19:50,939 --> 00:19:54,099",arabic:"إِنَّمَا أَرَدْتُ مِنْكَ أَنْ تَرَى بِنَفْسِكَ وَتَحْكُمَ بِعَقْلِكَ.",segs:[{ar:"إِنَّمَا أَرَدْتُ مِنْكَ",uz:"Men sendan faqat shuni istadim"},{ar:"أَنْ تَرَى بِنَفْسِكَ",uz:"o‘zing ko‘rishingni"},{ar:"وَتَحْكُمَ بِعَقْلِكَ.",uz:"va o‘z aqling bilan hukm qilishingni."}],full_uz:"Men faqat o‘zing ko‘rib, o‘z aqling bilan hukm qilishingni istadim.",note:"إِنَّمَا — faqat, xolos; fikrni ma’lum doira bilan cheklaydi."},
{num:256,time:"00:19:54,099 --> 00:19:57,379",arabic:"فَعَقْلُ الْإِنْسَانِ أَدَاتُهُ لِلْحُكْمِ وَالْقَرَارِ.",segs:[{ar:"فَعَقْلُ الْإِنْسَانِ أَدَاتُهُ",uz:"Chunki insonning aqli uning vositasidir"},{ar:"لِلْحُكْمِ وَالْقَرَارِ.",uz:"hukm qilish va qaror qabul qilish uchun."}],full_uz:"Chunki insonning aqli uning hukm qilish va qaror qabul qilish vositasidir.",note:"أَدَاةٌ — vosita, asbob; أَدَاتُهُ — uning vositasi."},
{num:257,time:"00:19:57,380 --> 00:20:00,820",arabic:"أَوَلَيْسَتِ الْحِكْمَةُ ضَالَّةَ الْمُؤْمِنِ؟",segs:[{ar:"أَوَلَيْسَتِ الْحِكْمَةُ",uz:"Axir hikmat emasmi"},{ar:"ضَالَّةَ الْمُؤْمِنِ؟",uz:"mo‘minning yo‘qotgan narsasi?"}],full_uz:"Axir hikmat mo‘minning yo‘qotgan narsasi emasmi?",note:"ضَالَّةٌ — yo‘qotilib, qidirilayotgan narsa; bu yerda doimo izlanadigan hikmatga o‘xshatish."},
{num:258,time:"00:20:00,820 --> 00:20:07,260",arabic:"نَعَمْ، الْحِكْمَةُ ضَالَّةُ الْمُؤْمِنِ، وَالدِّينُ النَّصِيحَةُ.",segs:[{ar:"نَعَمْ،",uz:"Ha,"},{ar:"الْحِكْمَةُ ضَالَّةُ الْمُؤْمِنِ،",uz:"hikmat mo‘minning yo‘qotgan narsasidir,"},{ar:"وَالدِّينُ النَّصِيحَةُ.",uz:"din esa nasihatdir."}],full_uz:"Ha, hikmat mo‘minning yo‘qotgan narsasidir, din esa nasihatdir.",note:"النَّصِيحَةُ — samimiy maslahat, yaxshilikni istash."},
{num:259,time:"00:20:07,260 --> 00:20:10,780",arabic:"وَأَنَا أَنْصَحُكَ يَا بَدْرُ أَنْ تَبْتَعِدَ عَنْ هَؤُلَاءِ الْقَوْمِ.",segs:[{ar:"وَأَنَا أَنْصَحُكَ يَا بَدْرُ",uz:"Men esa senga maslahat beraman, Badr"},{ar:"أَنْ تَبْتَعِدَ",uz:"uzoq yurishni"},{ar:"عَنْ هَؤُلَاءِ الْقَوْمِ.",uz:"bu kishilardan."}],full_uz:"Badr, men esa senga bu kishilardan uzoq yurishni maslahat beraman.",note:"ابْتَعَدَ عَنْ — ...dan uzoqlashmoq, uzoq yurmoq."},
{num:260,time:"00:20:10,780 --> 00:20:13,520",arabic:"فَهُمْ خُصُومُ أَمِيرِ الْمُؤْمِنِينَ الرَّشِيدِ.",segs:[{ar:"فَهُمْ خُصُومُ",uz:"Chunki ular dushmanlaridir"},{ar:"أَمِيرِ الْمُؤْمِنِينَ الرَّشِيدِ.",uz:"mo‘minlar amiri Rashidning."}],full_uz:"Chunki ular mo‘minlar amiri Rashidning dushmanlaridir.",note:"خُصُومٌ — خَصْمٌ so‘zining ko‘pligi: raqiblar, dushmanlar."},
{num:261,time:"00:20:13,520 --> 00:20:17,320",arabic:"غَفَرَ اللَّهُ لَكَ يَا صَاحِبِي، غَفَرَ اللَّهُ لَكَ.",segs:[{ar:"غَفَرَ اللَّهُ لَكَ",uz:"Alloh seni kechirsin"},{ar:"يَا صَاحِبِي،",uz:"do‘stim,"},{ar:"غَفَرَ اللَّهُ لَكَ.",uz:"Alloh seni kechirsin."}],full_uz:"Alloh seni kechirsin, do‘stim, Alloh seni kechirsin.",note:"غَفَرَ اللَّهُ لَكَ — o‘tgan zamon shaklida aytilgan duo: Alloh seni kechirsin."},
{num:262,time:"00:20:17,320 --> 00:20:22,320",arabic:"مُنْذُ مَتَى كَانَ رِضَا أَمِيرِ الْمُؤْمِنِينَ مِقْيَاسًا لِلتَّمْيِيزِ بَيْنَ الْحَقِّ وَالْبَاطِلِ؟",segs:[{ar:"مُنْذُ مَتَى",uz:"Qachondan beri"},{ar:"كَانَ رِضَا أَمِيرِ الْمُؤْمِنِينَ مِقْيَاسًا",uz:"mo‘minlar amirining roziligi mezon bo‘lib qoldi"},{ar:"لِلتَّمْيِيزِ",uz:"ajratish uchun"},{ar:"بَيْنَ الْحَقِّ وَالْبَاطِلِ؟",uz:"haq bilan botilni?"}],full_uz:"Qachondan beri mo‘minlar amirining roziligi haq bilan botilni ajratish mezoni bo‘lib qoldi?",note:"مُنْذُ مَتَى — qachondan beri. مِقْيَاسٌ — o‘lchov, mezon."},
{num:263,time:"00:20:22,320 --> 00:20:24,960",arabic:"إِنَّ مِقْيَاسَ تَمْيِيزِ الْحَقِّ وَالْبَاطِلِ هُوَ هُنَا.",segs:[{ar:"إِنَّ مِقْيَاسَ تَمْيِيزِ الْحَقِّ وَالْبَاطِلِ",uz:"Haq bilan botilni ajratish mezoni"},{ar:"هُوَ هُنَا.",uz:"mana shu yerda."}],full_uz:"Haq bilan botilni ajratish mezoni mana shu yerda.",note:"هُنَا — shu yerda; gapiruvchi ko‘rsatayotgan joyni bildiradi."},
{num:264,time:"00:20:24,960 --> 00:20:35,220",arabic:"اسْمَعْنِي يَا بَدْرُ، إِنَّ مِقْيَاسَ التَّمْيِيزِ بَيْنَ الْحَقِّ وَالْبَاطِلِ هُوَ كِتَابُ اللَّهِ وَسُنَّةُ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،",segs:[{ar:"اسْمَعْنِي يَا بَدْرُ،",uz:"Meni eshit, Badr."},{ar:"إِنَّ مِقْيَاسَ التَّمْيِيزِ",uz:"Ajratish mezoni"},{ar:"بَيْنَ الْحَقِّ وَالْبَاطِلِ",uz:"haq bilan botilni"},{ar:"هُوَ كِتَابُ اللَّهِ",uz:"Allohning Kitobidir"},{ar:"وَسُنَّةُ رَسُولِهِ",uz:"va Uning Rasulining sunnatidir"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،",uz:"Alloh u zotga salavot va salom yo‘llasin,"}],full_uz:"Meni eshit, Badr. Haq bilan botilni ajratish mezoni Allohning Kitobi va Uning Rasuli, sollallohu alayhi vasallamning sunnatidir.",note:"التَّمْيِيزُ بَيْنَ ... وَ... — ikki narsa o‘rtasidagi farqni ajratish."},
{num:265,time:"00:20:35,220 --> 00:20:37,640",arabic:"وَلَيْسَ عَقْلَكَ الْمَرِيضَ.",segs:null,full_uz:"Sening kasal aqling emas.",note:"الْمَرِيضُ — kasal; bu yerda aqlga nisbatan ko‘chma ma’noda ishlatilgan."},
{num:266,time:"00:20:37,640 --> 00:20:46,340",arabic:"وَكَيْفَ السَّبِيلُ إِلَى فَهْمِ كِتَابِ اللَّهِ وَسُنَّةِ رَسُولِهِ إِنْ لَمْ نُعْمِلْ فِيهِمَا عُقُولَنَا؟",segs:[{ar:"وَكَيْفَ السَّبِيلُ إِلَى فَهْمِ",uz:"Qanday yo‘l bilan tushunamiz"},{ar:"كِتَابِ اللَّهِ وَسُنَّةِ رَسُولِهِ",uz:"Allohning Kitobi va Rasulining sunnatini"},{ar:"إِنْ لَمْ نُعْمِلْ فِيهِمَا عُقُولَنَا؟",uz:"agar ularni tushunishda aqlimizni ishlatmasak?"}],full_uz:"Agar aqlimizni ishlatmasak, Allohning Kitobi va Rasulining sunnatini qanday tushunamiz?",note:"أَعْمَلَ عَقْلَهُ — aqlini ishga soldi. فِيهِمَا dagi ـهُمَا Kitob va sunnatga ishora qiladi."},
{num:267,time:"00:20:46,340 --> 00:20:49,380",arabic:"إِنَّ الْعَقْلَ يَا صَدِيقِي هُوَ الْجِسْرُ بَيْنَ اللَّفْظِ وَمَعْنَاهُ،",segs:[{ar:"إِنَّ الْعَقْلَ يَا صَدِيقِي",uz:"Aql, do‘stim,"},{ar:"هُوَ الْجِسْرُ",uz:"ko‘prikdir"},{ar:"بَيْنَ اللَّفْظِ وَمَعْنَاهُ،",uz:"so‘z va uning ma’nosi o‘rtasidagi,"}],full_uz:"Do‘stim, aql so‘z va uning ma’nosi o‘rtasidagi ko‘prikdir,",note:"اللَّفْظُ — lafz, aytilgan so‘z; الْمَعْنَى — uning anglatgan ma’nosi."},
{num:268,time:"00:20:49,380 --> 00:20:51,120",arabic:"بَيْنَ الْقَوْلِ وَالْعَمَلِ.",segs:null,full_uz:"so‘z bilan amal o‘rtasidagi.",note:"Oldingi gapdagi الْجِسْرُ — ko‘prik so‘ziga bog‘lanadi."},
{num:269,time:"00:20:51,120 --> 00:20:54,380",arabic:"أَلَيْسَ ذَلِكَ مِنَ الْبَدِيهِيَّاتِ أَيْضًا؟",segs:[{ar:"أَلَيْسَ ذَلِكَ",uz:"Bu ham emasmi"},{ar:"مِنَ الْبَدِيهِيَّاتِ أَيْضًا؟",uz:"o‘z-o‘zidan ravshan narsalardan?"}],full_uz:"Bu ham o‘z-o‘zidan ravshan narsalardan emasmi?",note:"الْبَدِيهِيَّاتُ — alohida isbotsiz ham ravshan bo‘lgan narsalar."},
{num:270,time:"00:20:54,960 --> 00:21:00,460",arabic:"إِنَّ شَيْخِي بِشْرًا وَمَنْ مَعَهُ يَضَعُونَ الْعَقْلَ فِي الْمَكَانِ الَّذِي وَضَعَهُ اللَّهُ لَهُ.",segs:[{ar:"إِنَّ شَيْخِي بِشْرًا",uz:"Ustozim Bishr"},{ar:"وَمَنْ مَعَهُ",uz:"va uning yonidagilar"},{ar:"يَضَعُونَ الْعَقْلَ",uz:"aqlni qo‘yadilar"},{ar:"فِي الْمَكَانِ",uz:"o‘sha o‘ringa"},{ar:"الَّذِي وَضَعَهُ اللَّهُ لَهُ.",uz:"Alloh unga belgilagan."}],full_uz:"Ustozim Bishr va uning yonidagilar aqlni Alloh unga belgilagan o‘ringa qo‘yadilar.",note:"مَنْ مَعَهُ — uning bilan birga bo‘lganlar. مَنْ mazmunan ko‘pchilikni bildirgani uchun يَضَعُونَ ko‘plikda kelgan."},
{num:271,time:"00:21:00,460 --> 00:21:04,579",arabic:"فَلَا تَحْكُمْ لِمُجَرَّدِ سَمَاعِكَ بِأُذُنِكَ يَا صُهَيْبُ.",segs:[{ar:"فَلَا تَحْكُمْ",uz:"Shunday ekan, hukm qilma"},{ar:"لِمُجَرَّدِ سَمَاعِكَ بِأُذُنِكَ",uz:"faqat qulog‘ing bilan eshitganing uchungina"},{ar:"يَا صُهَيْبُ.",uz:"Suhayb."}],full_uz:"Suhayb, faqat qulog‘ing bilan eshitganing uchungina hukm qilma.",note:"لِمُجَرَّدِ — shunchaki ...uchun, faqat ...ning o‘zi sababli. لَا تَحْكُمْ — hukm qilma."},
{num:272,time:"00:21:21,400 --> 00:21:23,279",arabic:"السَّلَامُ عَلَيْكَ يَا أَخَا الْعَرَبِ.",segs:[{ar:"السَّلَامُ عَلَيْكَ",uz:"Sizga salom bo‘lsin"},{ar:"يَا أَخَا الْعَرَبِ.",uz:"ey arab birodar."}],full_uz:"Assalomu alaykum, ey arab birodar.",note:"يَا أَخَا الْعَرَبِ — izofa shaklidagi murojaat; أَخٌ so‘zi bunda أَخَا bo‘lib keladi."},
{num:273,time:"00:21:26,359 --> 00:21:29,839",arabic:"سَمِعْتُكَ قَبْلَ قَلِيلٍ تُحَدِّثُ النَّاسَ فِي الْمَسْجِدِ،",segs:[{ar:"سَمِعْتُكَ قَبْلَ قَلِيلٍ",uz:"Biroz oldin sizni eshitdim"},{ar:"تُحَدِّثُ النَّاسَ",uz:"odamlarga gapirayotganingizni"},{ar:"فِي الْمَسْجِدِ،",uz:"masjidda,"}],full_uz:"Biroz oldin masjidda odamlarga gapirayotganingizni eshitdim.",note:"قَبْلَ قَلِيلٍ — biroz oldin. حَدَّثَ النَّاسَ — odamlarga gapirdi, so‘zlab berdi."},
{num:274,time:"00:21:29,839 --> 00:21:32,319",arabic:"وَقَدْ أَعْجَبَنِي مَا تَقُولُ.",segs:[{ar:"وَقَدْ أَعْجَبَنِي",uz:"Menga yoqdi"},{ar:"مَا تَقُولُ.",uz:"aytayotganlaringiz."}],full_uz:"Aytayotganlaringiz menga yoqdi.",note:"أَعْجَبَنِي — menga yoqdi; yoqqan narsa fe’lning egasi bo‘ladi."},
{num:275,time:"00:21:32,319 --> 00:21:34,559",arabic:"جَزَاكَ اللَّهُ كُلَّ خَيْرٍ.",segs:null,full_uz:"Alloh sizni barcha yaxshiliklar bilan mukofotlasin.",note:"جَزَاكَ اللَّهُ خَيْرًا — minnatdorlik bildirishda ishlatiladigan duo."},
{num:276,time:"00:21:34,559 --> 00:21:38,639",arabic:"أَحْسَبُ إِذَنْ أَنَّكَ فَقِيهٌ أَوْ شَيْخُ حَدِيثٍ.",segs:[{ar:"أَحْسَبُ إِذَنْ",uz:"Unda menimcha"},{ar:"أَنَّكَ فَقِيهٌ",uz:"siz faqihsiz"},{ar:"أَوْ شَيْخُ حَدِيثٍ.",uz:"yoki hadis ustozisiz."}],full_uz:"Unda, menimcha, siz faqih yoki hadis ustozisiz.",note:"أَحْسَبُ — deb o‘ylayman, deb taxmin qilaman. فَقِيهٌ — fiqh olimi."},
{num:277,time:"00:21:38,639 --> 00:21:43,359",arabic:"أَكْرَمَنِيَ اللَّهُ بِالتَّتَلْمُذِ عَلَى يَدِ الْقَاضِي أَبِي يُوسُفَ رَحِمَهُ اللَّهُ،",segs:[{ar:"أَكْرَمَنِيَ اللَّهُ",uz:"Alloh meni sharafladi"},{ar:"بِالتَّتَلْمُذِ",uz:"shogird bo‘lish bilan"},{ar:"عَلَى يَدِ الْقَاضِي أَبِي يُوسُفَ",uz:"qozi Abu Yusufga"},{ar:"رَحِمَهُ اللَّهُ،",uz:"Alloh uni rahmat qilsin,"}],full_uz:"Alloh meni qozi Abu Yusufga shogird bo‘lish bilan sharafladi. Alloh uni rahmat qilsin.",note:"التَّتَلْمُذُ عَلَى يَدِ فُلَانٍ — falon kishining qo‘lida ta’lim olish, unga shogird bo‘lish."},
{num:278,time:"00:21:43,359 --> 00:21:47,359",arabic:"إِمَامِ أَهْلِ الْعِرَاقِ.",segs:null,full_uz:"Iroq ahlining imomiga.",note:"Bu parcha oldingi gapdagi Abu Yusufni tavsiflaydi; shuning uchun إِمَامِ qaratqich holatida."},
{num:279,time:"00:21:47,359 --> 00:21:49,899",arabic:"يَا مَرْحَبًا بِكَ يَا أَخِي.",segs:[{ar:"يَا مَرْحَبًا بِكَ",uz:"Xush kelibsiz"},{ar:"يَا أَخِي.",uz:"birodarim."}],full_uz:"Xush kelibsiz, birodarim.",note:"مَرْحَبًا بِكَ — iliq kutib olish va xushnudlik bildirish iborasi."},
{num:280,time:"00:21:49,899 --> 00:21:51,599",arabic:"أَحْسَبُ أَنَّكَ لَسْتَ مِنْ بَغْدَادَ.",segs:[{ar:"أَحْسَبُ أَنَّكَ",uz:"Menimcha, siz"},{ar:"لَسْتَ مِنْ بَغْدَادَ.",uz:"Bag‘doddan emassiz."}],full_uz:"Menimcha, siz Bag‘doddan emassiz.",note:"لَسْتَ — sen emassan; ayolga لَسْتِ deyiladi."},
{num:281,time:"00:21:51,599 --> 00:21:58,740",arabic:"هُوَ كَمَا تَقُولُ، أَنَا مِنْ مَكَّةَ الْمُكَرَّمَةِ وَأُدْعَى مُحَمَّدَ بْنَ إِدْرِيسَ الشَّافِعِيَّ.",segs:[{ar:"هُوَ كَمَا تَقُولُ،",uz:"Siz aytgandek."},{ar:"أَنَا مِنْ مَكَّةَ الْمُكَرَّمَةِ",uz:"Men Makkai Mukarramadanman"},{ar:"وَأُدْعَى مُحَمَّدَ بْنَ إِدْرِيسَ الشَّافِعِيَّ.",uz:"ismim Muhammad ibn Idris Shofe’iy."}],full_uz:"Siz aytgandek. Men Makkai Mukarramadanman, ismim Muhammad ibn Idris Shofe’iy.",note:"أُدْعَى — meni ...deb atashadi; o‘z ismini aytishda ishlatiladigan majhul nisbatdagi fe’l."},
{num:282,time:"00:21:58,740 --> 00:22:02,259",arabic:"وَأَنَا بِشْرٌ، بِشْرٌ الْمَرِيسِيُّ.",segs:[{ar:"وَأَنَا بِشْرٌ،",uz:"Men esa Bishrman,"},{ar:"بِشْرٌ الْمَرِيسِيُّ.",uz:"Bishr Marisiy."}],full_uz:"Men esa Bishrman, Bishr Marisiy.",note:null},
{num:283,time:"00:22:02,259 --> 00:22:04,639",arabic:"أَهْلًا وَسَهْلًا بِكَ يَا أَخِي.",segs:[{ar:"أَهْلًا وَسَهْلًا بِكَ",uz:"Xush kelibsiz"},{ar:"يَا أَخِي.",uz:"birodarim."}],full_uz:"Xush kelibsiz, birodarim.",note:"أَهْلًا وَسَهْلًا بِكَ — mehmonni iliq kutib olish iborasi."},
{num:284,time:"00:22:04,639 --> 00:22:08,240",arabic:"حَسَنًا، فَلْنَذْهَبْ إِلَى بَيْتِي لِنُكْمِلَ حَدِيثَنَا.",segs:[{ar:"حَسَنًا،",uz:"Yaxshi,"},{ar:"فَلْنَذْهَبْ إِلَى بَيْتِي",uz:"unday bo‘lsa, uyimga boraylik"},{ar:"لِنُكْمِلَ حَدِيثَنَا.",uz:"suhbatimizni davom ettirish uchun."}],full_uz:"Yaxshi, suhbatimizni davom ettirish uchun uyimga boraylik.",note:"فَلْنَذْهَبْ dagi لْ buyruq-istakni, لِنُكْمِلَ dagi لِ esa maqsadni bildiradi."},
{num:285,time:"00:22:08,240 --> 00:22:10,219",arabic:"أَخْشَى أَنَّنِي أُثْقِلُ عَلَيْكَ.",segs:[{ar:"أَخْشَى أَنَّنِي",uz:"Qo‘rqamanki, men"},{ar:"أُثْقِلُ عَلَيْكَ.",uz:"sizga og‘irlik qilaman."}],full_uz:"Sizga og‘irlik qilishdan qo‘rqaman.",note:"أَثْقَلَ عَلَى فُلَانٍ — birovga og‘irlik qilmoq, uni bezovta qilmoq."},
{num:286,time:"00:22:10,219 --> 00:22:12,179",arabic:"تَفَضَّلْ يَا أَخِي، تَفَضَّلْ.",segs:[{ar:"تَفَضَّلْ يَا أَخِي،",uz:"Marhamat, birodarim,"},{ar:"تَفَضَّلْ.",uz:"marhamat."}],full_uz:"Marhamat, birodarim, marhamat.",note:null},
{num:287,time:"00:22:12,719 --> 00:22:19,459",arabic:"لَا أَحَبَّ إِلَى نَفْسِ الشَّافِعِيِّ مِنْ مُجَالَسَةِ الْفُقَهَاءِ وَطُلَّابِ الْعِلْمِ.",segs:[{ar:"لَا أَحَبَّ إِلَى نَفْسِ الشَّافِعِيِّ",uz:"Shofe’iy uchun sevimliroq narsa yo‘q"},{ar:"مِنْ مُجَالَسَةِ الْفُقَهَاءِ",uz:"faqihlar bilan suhbatlashishdan"},{ar:"وَطُلَّابِ الْعِلْمِ.",uz:"va ilm talab qiluvchilar bilan."}],full_uz:"Shofe’iy uchun faqihlar va ilm talab qiluvchilar bilan suhbatlashishdan sevimliroq narsa yo‘q.",note:"مُجَالَسَةٌ — birga o‘tirish, suhbatlashish. Gapiruvchi o‘zini ismi bilan tilga olmoqda."},
{num:288,time:"00:22:19,460 --> 00:22:24,700",arabic:"فَكَيْفَ بِرَجُلٍ هُوَ تِلْمِيذٌ لِأَبِي يُوسُفَ رَحِمَهُ اللَّهُ؟",segs:[{ar:"فَكَيْفَ بِرَجُلٍ",uz:"Unda bir kishi haqida nima deyish mumkin"},{ar:"هُوَ تِلْمِيذٌ لِأَبِي يُوسُفَ",uz:"Abu Yusufning shogirdi bo‘lgan"},{ar:"رَحِمَهُ اللَّهُ؟",uz:"Alloh uni rahmat qilsin?"}],full_uz:"Abu Yusufning shogirdi bilan suhbatlashish esa yanada sevimli bo‘lmaydimi? Alloh uni rahmat qilsin.",note:"فَكَيْفَ بِـ — oldingi fikrni kuchaytirib, unda ...haqida nima deyish mumkin? ma’nosini beradi."},
{num:289,time:"00:22:24,700 --> 00:22:27,940",arabic:"شُكْرًا لَكَ، هَذَا كَرَمٌ مِنْكَ.",segs:[{ar:"شُكْرًا لَكَ،",uz:"Sizga rahmat,"},{ar:"هَذَا كَرَمٌ مِنْكَ.",uz:"bu sizning olijanobligingiz."}],full_uz:"Rahmat, bu sizning olijanobligingiz.",note:null},
{num:290,time:"00:22:33,400 --> 00:22:36,779",arabic:"اعْذُرْنِي عَلَى هَذِهِ الزِّيَارَةِ الْمُفَاجِئَةِ يَا ابْنَ أَبِي دُؤَادٍ.",segs:[{ar:"اعْذُرْنِي",uz:"Meni kechiring"},{ar:"عَلَى هَذِهِ الزِّيَارَةِ الْمُفَاجِئَةِ",uz:"bu kutilmagan tashrif uchun"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ.",uz:"ey Ibn Abu Duod."}],full_uz:"Bu kutilmagan tashrif uchun meni kechiring, Ibn Abu Duod.",note:"اعْذُرْنِي عَلَى... — ...uchun meni kechir. مُفَاجِئَةٌ — kutilmagan, to‘satdan bo‘lgan."},
{num:291,time:"00:22:36,779 --> 00:22:40,559",arabic:"فَصَدِيقِي بَدْرٌ أَصَرَّ عَلَى زِيَارَتِكَ وَالتَّعَرُّفِ عَلَيْكَ.",segs:[{ar:"فَصَدِيقِي بَدْرٌ أَصَرَّ",uz:"Chunki do‘stim Badr qattiq turib oldi"},{ar:"عَلَى زِيَارَتِكَ",uz:"sizni ziyorat qilishga"},{ar:"وَالتَّعَرُّفِ عَلَيْكَ.",uz:"va siz bilan tanishishga."}],full_uz:"Chunki do‘stim Badr sizni ziyorat qilib, siz bilan tanishishga qattiq turib oldi.",note:"أَصَرَّ عَلَى — biror ishda qat’iy turib olmoq. تَعَرَّفَ عَلَى — tanishmoq."},
{num:292,time:"00:22:40,559 --> 00:22:44,340",arabic:"شَرَفٌ كَبِيرٌ لِي أَنْ أَنَالَ كَرَمَ زِيَارَتِكَ يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"شَرَفٌ كَبِيرٌ لِي",uz:"Men uchun katta sharaf"},{ar:"أَنْ أَنَالَ كَرَمَ زِيَارَتِكَ",uz:"tashrifingizga sazovor bo‘lish"},{ar:"يَا أَبَا عَبْدِ اللَّهِ.",uz:"ey Abu Abdulloh."}],full_uz:"Tashrifingizga sazovor bo‘lish men uchun katta sharaf, Abu Abdulloh.",note:"نَالَ — erishmoq, sazovor bo‘lmoq; أَنْ dan keyin أَنَالَ shaklida kelgan."},
{num:293,time:"00:22:44,340 --> 00:22:49,340",arabic:"بَدْرٌ هُوَ مَنْ حَدَّثْتُكَ عَنْهُ سَابِقًا،",segs:[{ar:"بَدْرٌ هُوَ مَنْ",uz:"Badr o‘sha kishiki"},{ar:"حَدَّثْتُكَ عَنْهُ سَابِقًا،",uz:"u haqida sizga ilgari gapirgandim,"}],full_uz:"Badr — sizga ilgari gapirib bergan kishim,",note:"حَدَّثْتُكَ عَنْهُ — sizga u haqida gapirib berdim."},
{num:294,time:"00:22:49,339 --> 00:22:52,539",arabic:"الَّذِي أَشْكَلَ عَلَيْهِ قَوْلُ اللَّهِ سُبْحَانَهُ وَتَعَالَى:",segs:[{ar:"الَّذِي أَشْكَلَ عَلَيْهِ",uz:"unga tushunish qiyin bo‘lgan"},{ar:"قَوْلُ اللَّهِ",uz:"Allohning so‘zi"},{ar:"سُبْحَانَهُ وَتَعَالَى:",uz:"U pok va yuksakdir:"}],full_uz:"Alloh subhanahu va taoloning quyidagi so‘zini tushunishda qiynalgan kishi:",note:"أَشْكَلَ عَلَيْهِ الْأَمْرُ — ish unga tushunarsiz bo‘ldi, uni tushunishda qiynaldi."},
{num:295,time:"00:22:52,539 --> 00:22:56,220",arabic:"وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ، إِلَى رَبِّهَا نَاظِرَةٌ.",segs:[{ar:"وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ،",uz:"U kunda yuzlar porloq bo‘ladi,"},{ar:"إِلَى رَبِّهَا نَاظِرَةٌ.",uz:"Rabbiga boqib turadi."}],full_uz:"U kunda yuzlar porloq bo‘lib, Rabbiga boqib turadi.",note:"نَاضِرَةٌ — porloq, yashnagan; نَاظِرَةٌ — qarayotgan. ض va ظ harflari ma’noni o‘zgartiradi."},
{num:296,time:"00:22:56,220 --> 00:22:57,619",arabic:"حَقًّا؟",segs:null,full_uz:"Rostdanmi?",note:null},
{num:297,time:"00:22:57,619 --> 00:23:01,839",arabic:"لَا بُدَّ إِذَنْ أَنَّ بَدْرًا طَالِبٌ مُهْتَمٌّ بِدَرْسِهِ.",segs:[{ar:"لَا بُدَّ إِذَنْ",uz:"Unda, shubhasiz,"},{ar:"أَنَّ بَدْرًا طَالِبٌ",uz:"Badr bir talabaki"},{ar:"مُهْتَمٌّ بِدَرْسِهِ.",uz:"darsiga qiziqadi."}],full_uz:"Unda Badr, shubhasiz, darsiga qiziqadigan talaba ekan.",note:"مُهْتَمٌّ بِـ — ...ga qiziqadigan, ...ga e’tibor beradigan."},
{num:298,time:"00:23:01,839 --> 00:23:03,079",arabic:"مُهْتَمٌّ، وَلَا شَكَّ.",segs:[{ar:"مُهْتَمٌّ،",uz:"Qiziqadi,"},{ar:"وَلَا شَكَّ.",uz:"bunga shubha yo‘q."}],full_uz:"Qiziqadi, bunga shubha yo‘q.",note:null},
{num:299,time:"00:23:03,079 --> 00:23:05,959",arabic:"وَلَكِنْ فِي ذَلِكَ الْيَوْمِ جَانَبَهُ الصَّوَابُ.",segs:[{ar:"وَلَكِنْ فِي ذَلِكَ الْيَوْمِ",uz:"Ammo o‘sha kuni"},{ar:"جَانَبَهُ الصَّوَابُ.",uz:"u xato qilgan edi."}],full_uz:"Ammo o‘sha kuni u xato qilgan edi.",note:"جَانَبَهُ الصَّوَابُ — so‘zma-so‘z: to‘g‘rilik undan chetda qoldi; xato qildi ma’nosidagi ibora."},
{num:300,time:"00:23:05,959 --> 00:23:08,599",arabic:"مَنْ يَدْرِي يَا مُحَمَّدُ؟",segs:[{ar:"مَنْ يَدْرِي",uz:"Kim biladi"},{ar:"يَا مُحَمَّدُ؟",uz:"Muhammad?"}],full_uz:"Kim biladi, Muhammad?",note:"مَنْ يَدْرِي؟ — kim biladi?; natija hali aniq emasligini bildiradi."},
{num:301,time:"00:23:08,599 --> 00:23:12,899",arabic:"رُبَّمَا نَكْتَشِفُ بَعْدَ فَتْرَةٍ أَنَّ الْحَقَّ مَعَهُ،",segs:[{ar:"رُبَّمَا نَكْتَشِفُ",uz:"Balki bilib qolarmiz"},{ar:"بَعْدَ فَتْرَةٍ",uz:"bir muddatdan keyin"},{ar:"أَنَّ الْحَقَّ مَعَهُ،",uz:"haq uning tomonida ekanini,"}],full_uz:"Balki bir muddatdan keyin uning haq ekanini bilib qolarmiz,",note:"الْحَقُّ مَعَهُ — haq uning tomonida, u haq."},
{num:302,time:"00:23:12,899 --> 00:23:14,619",arabic:"وَنَحْنُ مَنْ جَانَبَنَا الصَّوَابُ.",segs:[{ar:"وَنَحْنُ مَنْ",uz:"biz esa o‘sha kishilarmiz"},{ar:"جَانَبَنَا الصَّوَابُ.",uz:"xato qilgan."}],full_uz:"Xato qilganlar esa biz bo‘lib chiqarmiz.",note:"جَانَبَنَا الصَّوَابُ — biz xato qildik; الصَّوَابُ fe’lning egasi."},
{num:303,time:"00:23:14,619 --> 00:23:21,799",arabic:"لِمَاذَا؟ أَمَا زَالَ لَدَيْكَ شَكٌّ بِمَا قُلْتُ؟",segs:[{ar:"لِمَاذَا؟",uz:"Nega?"},{ar:"أَمَا زَالَ لَدَيْكَ شَكٌّ",uz:"Hali ham sizda shubha bormi"},{ar:"بِمَا قُلْتُ؟",uz:"aytganlarimga?"}],full_uz:"Nega? Aytganlarimga hali ham shubhangiz bormi?",note:"مَا زَالَ — hali ham; boshidagi أَ so‘roqni bildiradi."},
{num:304,time:"00:23:21,799 --> 00:23:26,299",arabic:"لَا، لَا، لَا أَقْصِدُ ذَلِكَ يَا ابْنَ نُوحٍ، لَقَدْ كَانَ كَلَامُكَ مُقْنِعًا.",segs:[{ar:"لَا، لَا،",uz:"Yo‘q, yo‘q,"},{ar:"لَا أَقْصِدُ ذَلِكَ",uz:"buni nazarda tutmayapman"},{ar:"يَا ابْنَ نُوحٍ،",uz:"Ibn Nuh,"},{ar:"لَقَدْ كَانَ كَلَامُكَ مُقْنِعًا.",uz:"gaplaringiz ishontiradigan edi."}],full_uz:"Yo‘q, yo‘q, buni nazarda tutmayapman, Ibn Nuh. Gaplaringiz ishontiradigan edi.",note:"مُقْنِعٌ — ishontiradigan; مُقْتَنِعٌ esa ishongan, qanoat hosil qilgan degani."},
{num:305,time:"00:23:26,299 --> 00:23:32,500",arabic:"أَهْلًا بِأَخِي بَدْرٍ، أَسْعَدَتْنِي زِيَارَتُكَ وَأَرْجُو أَلَّا تَكُونَ الْأَخِيرَةَ.",segs:[{ar:"أَهْلًا بِأَخِي بَدْرٍ،",uz:"Birodarim Badr, xush kelibsiz."},{ar:"أَسْعَدَتْنِي زِيَارَتُكَ",uz:"Tashrifingiz meni xursand qildi"},{ar:"وَأَرْجُو",uz:"va umid qilaman"},{ar:"أَلَّا تَكُونَ الْأَخِيرَةَ.",uz:"bu oxirgisi bo‘lmasligiga."}],full_uz:"Birodarim Badr, xush kelibsiz. Tashrifingiz meni xursand qildi. Bu oxirgi tashrifingiz bo‘lmaydi deb umid qilaman.",note:"أَلَّا — أَنْ va لَا birikmasi. الْأَخِيرَةَ ayol jinsidagi زِيَارَةٌ so‘ziga ishora qiladi."},
{num:306,time:"00:23:32,500 --> 00:23:35,199",arabic:"أَنَا الَّذِي أَرْجُو ذَلِكَ يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"أَنَا الَّذِي أَرْجُو ذَلِكَ",uz:"Buni umid qiladigan o‘zimman"},{ar:"يَا أَبَا عَبْدِ اللَّهِ.",uz:"Abu Abdulloh."}],full_uz:"Buni o‘zim ham umid qilaman, Abu Abdulloh.",note:"أَنَا الَّذِي... — aynan men ...; gap egasiga urg‘u beradi."},
{num:307,time:"00:24:04,619 --> 00:24:06,299",arabic:"هَا هُوَ صَدِيقُكِ مَارًّا.",segs:[{ar:"هَا هُوَ صَدِيقُكِ",uz:"Mana do‘sting"},{ar:"مَارًّا.",uz:"o‘tib ketyapti."}],full_uz:"Mana, do‘sting o‘tib ketyapti.",note:"مَارٌّ — o‘tib ketayotgan; مَرَّ fe’lining ism foil shakli."},
{num:308,time:"00:24:13,619 --> 00:24:22,659",arabic:"حَارِثُ، الْحَقْ بِهَذِهِ الْمَرْأَةِ وَاعْرِفْ كُلَّ شَيْءٍ عَنْهَا، أَحْوَالَهَا وَمَكَانَ إِقَامَتِهَا، وَعُدْ إِلَيَّ عَلَى الْفَوْرِ.",segs:[{ar:"حَارِثُ،",uz:"Horis,"},{ar:"الْحَقْ بِهَذِهِ الْمَرْأَةِ",uz:"bu ayolning ortidan bor"},{ar:"وَاعْرِفْ كُلَّ شَيْءٍ عَنْهَا،",uz:"va u haqidagi hamma narsani bilib ol,"},{ar:"أَحْوَالَهَا",uz:"ahvolini"},{ar:"وَمَكَانَ إِقَامَتِهَا،",uz:"va yashash joyini,"},{ar:"وَعُدْ إِلَيَّ عَلَى الْفَوْرِ.",uz:"so‘ng darhol oldimga qayt."}],full_uz:"Horis, bu ayolning ortidan borib, u haqidagi hamma narsani, ahvoli va yashash joyini bilib ol. So‘ng darhol oldimga qayt.",note:"الْحَقْ بِـ — ortidan yetib bor. عَلَى الْفَوْرِ — darhol, zudlik bilan."},
{num:309,time:"00:24:22,659 --> 00:24:27,079",arabic:"وَكَيْفَ أَتْرُكُكَ وَحْدَكَ يَا مَوْلَايَ؟ أَخَافُ أَنْ يُصِيبَكَ مَكْرُوهٌ، لَا سَمَحَ اللَّهُ.",segs:[{ar:"وَكَيْفَ أَتْرُكُكَ وَحْدَكَ",uz:"Qanday qilib sizni yolg‘iz qoldiraman"},{ar:"يَا مَوْلَايَ؟",uz:"hazratim?"},{ar:"أَخَافُ أَنْ يُصِيبَكَ مَكْرُوهٌ،",uz:"Boshingizga biror ko‘ngilsizlik tushishidan qo‘rqaman,"},{ar:"لَا سَمَحَ اللَّهُ.",uz:"Alloh saqlasin."}],full_uz:"Sizni qanday qilib yolg‘iz qoldiraman, hazratim? Alloh saqlasin, boshingizga biror ko‘ngilsizlik tushishidan qo‘rqaman.",note:"مَكْرُوهٌ — yoqimsiz hodisa, ko‘ngilsizlik. لَا سَمَحَ اللَّهُ — Alloh saqlasin mazmunidagi ibora."},
{num:310,time:"00:24:27,079 --> 00:24:30,019",arabic:"لَا تَخْشَ شَيْئًا يَا حَارِثُ، لَا تَخْشَ عَلَيَّ.",segs:[{ar:"لَا تَخْشَ شَيْئًا",uz:"Hech narsadan qo‘rqma"},{ar:"يَا حَارِثُ،",uz:"Horis,"},{ar:"لَا تَخْشَ عَلَيَّ.",uz:"men uchun xavotir olma."}],full_uz:"Hech narsadan qo‘rqma, Horis. Men uchun xavotir olma.",note:"Taqiq bildiruvchi لَا dan keyin تَخْشَى fe’lining oxirgi ا harfi tushadi: لَا تَخْشَ."},
{num:311,time:"00:24:30,019 --> 00:24:31,859",arabic:"هَيَّا وَنَفِّذْ مَا قُلْتُ لَكَ.",segs:[{ar:"هَيَّا وَنَفِّذْ",uz:"Qani, bajar"},{ar:"مَا قُلْتُ لَكَ.",uz:"senga aytganimni."}],full_uz:"Qani, senga aytganimni bajar.",note:"نَفَّذَ — amalga oshirmoq, bajarmoq; buyrug‘i نَفِّذْ."},
{num:312,time:"00:24:31,859 --> 00:24:32,539",arabic:"أَمْرُكَ.",segs:null,full_uz:"Buyrug‘ingizga binoan.",note:"أَمْرُكَ — buyruqni qabul qilganini bildiruvchi qisqa javob: xo‘p bo‘ladi."},
{num:313,time:"00:24:33,220 --> 00:24:44,200",arabic:"الْعَدَالَةُ الْمُطْلَقَةُ أَمْرٌ مُسْتَحِيلٌ.",segs:[{ar:"الْعَدَالَةُ الْمُطْلَقَةُ",uz:"Mutlaq adolat"},{ar:"أَمْرٌ مُسْتَحِيلٌ.",uz:"imkonsiz ishdir."}],full_uz:"Mutlaq adolat imkonsiz ishdir.",note:"مُطْلَقٌ — mutlaq, cheklanmagan; مُسْتَحِيلٌ — imkonsiz."},
{num:314,time:"00:24:44,200 --> 00:24:51,019",arabic:"أَيَّ ذَنْبٍ تَحْمِلُهُ فِي رَقَبَتِكَ يَا هَارُونُ دُونَ أَنْ تَدْرِي؟",segs:[{ar:"أَيَّ ذَنْبٍ تَحْمِلُهُ",uz:"Qanday gunohni ko‘tarib yuribsan"},{ar:"فِي رَقَبَتِكَ",uz:"bo‘yningda"},{ar:"يَا هَارُونُ",uz:"Horun"},{ar:"دُونَ أَنْ تَدْرِي؟",uz:"o‘zing bilmasdan?"}],full_uz:"Horun, o‘zing bilmasdan bo‘yningda qanday gunohni ko‘tarib yuribsan?",note:"فِي رَقَبَتِكَ — bo‘yningda; javobgarlik va mas’uliyatni ifodalash uchun ham ishlatiladi."},
{num:315,time:"00:24:51,019 --> 00:24:53,019",arabic:"أَيَّ ذَنْبٍ؟",segs:null,full_uz:"Qanday gunohni?",note:"Oldingi gapdagi تَحْمِلُهُ fe’li mazmundan anglashilgani uchun takrorlanmagan."},
{num:316,time:"00:24:53,019 --> 00:24:59,160",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ.",segs:[{ar:"لَا حَوْلَ وَلَا قُوَّةَ",uz:"Hech qanday qudrat va kuch yo‘q"},{ar:"إِلَّا بِاللَّهِ",uz:"faqat Allohning yordami bilandir"},{ar:"الْعَلِيِّ الْعَظِيمِ.",uz:"yuksak va buyuk Zotning."}],full_uz:"Qudrat va kuch faqat yuksak va buyuk Allohning yordami bilandir.",note:"لَا ... إِلَّا — inkor va istisno orqali faqat ...gina ma’nosini beradi."},
{num:317,time:"00:25:07,880 --> 00:25:10,880",arabic:"أَجَلْ، هَذَا هُوَ اسْمُ الرَّجُلِ.",segs:[{ar:"أَجَلْ،",uz:"Ha,"},{ar:"هَذَا هُوَ اسْمُ الرَّجُلِ.",uz:"o‘sha kishining ismi shu."}],full_uz:"Ha, o‘sha kishining ismi shu.",note:null},
{num:318,time:"00:25:10,880 --> 00:25:14,240",arabic:"وَقَدْ قَالَ لِي إِنَّهُ مِنْ تَلَامِيذِ أَبِي يُوسُفَ رَحِمَهُ اللَّهُ.",segs:[{ar:"وَقَدْ قَالَ لِي",uz:"U menga aytdi"},{ar:"إِنَّهُ مِنْ تَلَامِيذِ أَبِي يُوسُفَ",uz:"Abu Yusufning shogirdlaridan ekanini"},{ar:"رَحِمَهُ اللَّهُ.",uz:"Alloh uni rahmat qilsin."}],full_uz:"U menga Abu Yusufning shogirdlaridan ekanini aytdi. Alloh uni rahmat qilsin.",note:null},
{num:319,time:"00:25:14,240 --> 00:25:16,779",arabic:"رَحِمَ اللَّهُ أَبَا يُوسُفَ.",segs:null,full_uz:"Alloh Abu Yusufni rahmat qilsin.",note:"أَبَا — أَبٌ so‘zining tushum shakli; bu gapda rahmat qilinayotgan kishini bildiradi."},
{num:320,time:"00:25:16,779 --> 00:25:19,279",arabic:"أَجَلْ، فَإِنَّ الرَّجُلَ لَمْ يَكْذِبْكَ.",segs:[{ar:"أَجَلْ،",uz:"Ha,"},{ar:"فَإِنَّ الرَّجُلَ لَمْ يَكْذِبْكَ.",uz:"u kishi sizga yolg‘on aytmagan."}],full_uz:"Ha, u kishi sizga yolg‘on aytmagan.",note:"كَذَبَكَ — senga yolg‘on aytdi; كَذَّبَكَ esa seni yolg‘onchiga chiqardi degani."},
{num:321,time:"00:25:19,279 --> 00:25:21,279",arabic:"هُوَ فِعْلًا مِنْ تَلَامِيذِهِ.",segs:null,full_uz:"U haqiqatan uning shogirdlaridan.",note:"فِعْلًا — haqiqatan, rostdan ham."},
{num:322,time:"00:25:21,279 --> 00:25:26,120",arabic:"لَيْتَ الْمَرِيسِيَّ بَقِيَ عَلَى مَا تَعَلَّمَهُ مِنْ شَيْخِهِ.",segs:[{ar:"لَيْتَ الْمَرِيسِيَّ بَقِيَ",uz:"Qaniydi Marisiy qolganida"},{ar:"عَلَى مَا تَعَلَّمَهُ",uz:"o‘rgangan narsasida"},{ar:"مِنْ شَيْخِهِ.",uz:"ustozidan."}],full_uz:"Qaniydi Marisiy ustozidan o‘rgangan yo‘lda qolganida.",note:"بَقِيَ عَلَى — bir holat yoki yo‘lda qolmoq. لَيْتَ amalga oshmagan istakni ham bildiradi."},
{num:323,time:"00:25:26,120 --> 00:25:28,779",arabic:"لِمَاذَا تَقُولُ ذَلِكَ؟",segs:null,full_uz:"Nega bunday deyapsiz?",note:null},
{num:324,time:"00:25:29,160 --> 00:25:33,740",arabic:"لِأَنَّ الْمَرِيسِيَّ هَذَا تَأَثَّرَ بِمُعْتَقَدِ أَهْلِ الِاعْتِزَالِ يَا شَافِعِيُّ.",segs:[{ar:"لِأَنَّ الْمَرِيسِيَّ هَذَا تَأَثَّرَ",uz:"Chunki bu Marisiy ta’sirlangan"},{ar:"بِمُعْتَقَدِ أَهْلِ الِاعْتِزَالِ",uz:"mu’tazila ahlining e’tiqodidan"},{ar:"يَا شَافِعِيُّ.",uz:"Shofe’iy."}],full_uz:"Chunki bu Marisiy mu’tazila ahlining e’tiqodidan ta’sirlangan, Shofe’iy.",note:"تَأَثَّرَ بِـ — ...dan ta’sirlanmoq. مُعْتَقَدٌ — e’tiqod, ishonilgan qarash."},
{num:325,time:"00:25:33,740 --> 00:25:37,240",arabic:"أَتْبَعَهُ الشَّيْطَانُ فَكَانَ مِنَ الْغَاوِينَ.",segs:[{ar:"أَتْبَعَهُ الشَّيْطَانُ",uz:"Shayton uning ortidan yetdi"},{ar:"فَكَانَ مِنَ الْغَاوِينَ.",uz:"natijada u adashganlardan bo‘ldi."}],full_uz:"Shayton uning ortidan yetdi va u adashganlardan bo‘ldi.",note:"الْغَاوِينَ — yo‘ldan ozganlar, adashganlar; birlik shakli غَاوٍ."},
{num:326,time:"00:25:37,240 --> 00:25:40,220",arabic:"فَلَعِبَ بِعَقْلِهِ بَعْضُ شُيُوخِ الْمُعْتَزِلَةِ.",segs:[{ar:"فَلَعِبَ بِعَقْلِهِ",uz:"Uning aqli bilan o‘ynadi"},{ar:"بَعْضُ شُيُوخِ الْمُعْتَزِلَةِ.",uz:"mu’tazilaning ayrim shayxlari."}],full_uz:"Mu’tazilaning ayrim shayxlari uning aqli bilan o‘ynadi.",note:"لَعِبَ بِعَقْلِهِ — uning fikrini chalg‘itdi, ongiga ta’sir qilib boshqardi."},
{num:327,time:"00:25:40,220 --> 00:25:45,400",arabic:"فَجَيَّرَ كُلَّ مَا تَعَلَّمَهُ مِنْ فُقَهَائِنَا لِنُصْرَةِ عَقِيدَتِهِ الْفَاسِدَةِ.",segs:[{ar:"فَجَيَّرَ كُلَّ مَا تَعَلَّمَهُ",uz:"Shu tariqa o‘rgangan barcha narsasini yo‘naltirdi"},{ar:"مِنْ فُقَهَائِنَا",uz:"bizning faqihlarimizdan"},{ar:"لِنُصْرَةِ عَقِيدَتِهِ الْفَاسِدَةِ.",uz:"buzuq aqidasini himoya qilishga."}],full_uz:"Shu tariqa faqihlarimizdan o‘rgangan barcha narsasini buzuq aqidasini himoya qilishga yo‘naltirdi.",note:"جَيَّرَ — bu yerda biror narsani ma’lum maqsadga xizmat qildirmoq. نُصْرَةٌ — qo‘llash, himoya qilish."},
{num:328,time:"00:25:45,400 --> 00:25:49,680",arabic:"وَهُوَ الْيَوْمَ يَدْعُو إِلَى الْقَوْلِ بِخَلْقِ الْقُرْآنِ.",segs:[{ar:"وَهُوَ الْيَوْمَ يَدْعُو",uz:"U bugun da’vat qilmoqda"},{ar:"إِلَى الْقَوْلِ بِخَلْقِ الْقُرْآنِ.",uz:"Qur’on yaratilgan degan qarashga."}],full_uz:"U bugun Qur’on yaratilgan degan qarashga da’vat qilmoqda.",note:"دَعَا إِلَى — ...ga da’vat qilmoq. الْقَوْلُ بِـ — biror qarashni aytish yoki qabul qilish."},
{num:329,time:"00:25:49,680 --> 00:25:53,560",arabic:"أَعُوذُ بِاللَّهِ مِنْ أَنْ نَكُونَ مِمَّنْ آتَاهُ اللَّهُ آيَاتِهِ،",segs:[{ar:"أَعُوذُ بِاللَّهِ",uz:"Allohdan panoh so‘rayman"},{ar:"مِنْ أَنْ نَكُونَ مِمَّنْ",uz:"o‘sha kishilardan bo‘lib qolishimizdan"},{ar:"آتَاهُ اللَّهُ آيَاتِهِ،",uz:"Alloh unga O‘z oyatlarini bergan,"}],full_uz:"Alloh O‘z oyatlarini bergan kishilardan bo‘lib, keyin ulardan yuz o‘girishdan Allohdan panoh so‘rayman,",note:"مِمَّنْ — مِنْ va مَنْ birikmasi: ...kishilardan. Mazmun keyingi parchada davom etadi."},
{num:330,time:"00:25:53,560 --> 00:25:56,680",arabic:"فَانْسَلَخَ مِنْهَا فَأَصْبَحَ مِنَ الْغَاوِينَ.",segs:[{ar:"فَانْسَلَخَ مِنْهَا",uz:"so‘ng u ulardan yuz o‘girdi"},{ar:"فَأَصْبَحَ مِنَ الْغَاوِينَ.",uz:"va adashganlardan bo‘lib qoldi."}],full_uz:"So‘ng u ulardan yuz o‘girib, adashganlardan bo‘lib qoldi.",note:"انْسَلَخَ مِنْ — aslida po‘stidan chiqmoq; bu yerda butunlay yuz o‘girmoq, ajralmoq."},
{num:331,time:"00:25:56,680 --> 00:26:00,160",arabic:"غَرِيبٌ أَمْرُ هَذَا الرَّجُلِ.",segs:[{ar:"غَرِيبٌ",uz:"G‘alati"},{ar:"أَمْرُ هَذَا الرَّجُلِ.",uz:"bu kishining holi."}],full_uz:"Bu kishining holi g‘alati ekan.",note:"غَرِيبٌ kesim bo‘lib, ta’kid uchun gap boshida kelgan."},
{num:332,time:"00:26:00,160 --> 00:26:04,100",arabic:"لَقَدْ بَدَا لِي فِي عَيْنِي فَقِيهًا.",segs:[{ar:"لَقَدْ بَدَا لِي فِي عَيْنِي",uz:"U mening ko‘zimga ko‘ringan edi"},{ar:"فَقِيهًا.",uz:"faqih bo‘lib."}],full_uz:"U mening ko‘zimga faqih bo‘lib ko‘ringan edi.",note:"بَدَا لِي — menga shunday ko‘rindi. بَدَا — ko‘rindi; بَدَأَ — boshladi."},
{num:333,time:"00:26:04,100 --> 00:26:06,759",arabic:"إِنَّهُ كَذَلِكَ لِلْأَسَفِ.",segs:[{ar:"إِنَّهُ كَذَلِكَ",uz:"U shunday"},{ar:"لِلْأَسَفِ.",uz:"afsuski."}],full_uz:"Afsuski, u shunday.",note:"لِلْأَسَفِ — afsuski."},
{num:334,time:"00:26:06,759 --> 00:26:08,200",arabic:"وَلَكِنْ مَا الْفَائِدَةُ؟",segs:null,full_uz:"Lekin nima foyda?",note:null},
{num:335,time:"00:26:08,200 --> 00:26:10,220",arabic:"إِنْ لَمْ يَحْجُزْهُ فِقْهُهُ،",segs:null,full_uz:"Agar uning fiqh ilmi uni to‘smasa,",note:"حَجَزَهُ عَنْ — uni biror narsadan to‘sdi; عَنْ bilan bog‘langan qism keyingi parchada."},
{num:336,time:"00:26:10,220 --> 00:26:12,680",arabic:"عَنِ الْوُقُوعِ فِي حَبَائِلِ الْمُبْتَدِعَةِ،",segs:[{ar:"عَنِ الْوُقُوعِ",uz:"tushib qolishdan"},{ar:"فِي حَبَائِلِ الْمُبْتَدِعَةِ،",uz:"bid’atchilarning tuzoqlariga,"}],full_uz:"bid’atchilarning tuzoqlariga tushib qolishdan,",note:"حَبَائِلُ — tuzoqlar, ov to‘rlari; birlik shakli حِبَالَةٌ."},
{num:337,time:"00:26:12,680 --> 00:26:14,299",arabic:"وَشَرَكِ الضَّالِّينَ.",segs:null,full_uz:"va adashganlarning qopqoniga.",note:"شَرَكٌ — qopqon, tuzoq; شِرْكٌ esa boshqa ma’nodagi so‘z."},
{num:338,time:"00:26:14,299 --> 00:26:17,759",arabic:"لَمْ يُجَاهِرْ بِذَلِكَ.",segs:null,full_uz:"U buni oshkora aytmadi.",note:"جَاهَرَ بِـ — biror narsani oshkora aytmoq yoki qilmoq."},
{num:339,time:"00:26:17,759 --> 00:26:21,960",arabic:"لَقَدْ بَدَا لِي عَلَى غَيْرِ مَا تَقُولُ تَمَامًا.",segs:[{ar:"لَقَدْ بَدَا لِي",uz:"U menga ko‘rindi"},{ar:"عَلَى غَيْرِ مَا تَقُولُ تَمَامًا.",uz:"siz aytayotganingizdan mutlaqo boshqacha."}],full_uz:"U menga siz aytayotganingizdan mutlaqo boshqacha ko‘rindi.",note:"عَلَى غَيْرِ مَا تَقُولُ — siz aytayotgan holatdan boshqacha."},
{num:340,time:"00:26:21,960 --> 00:26:23,560",arabic:"هَذَا الصِّنْفُ مِنَ النَّاسِ،",segs:null,full_uz:"Bu toifadagi odamlar",note:"صِنْفٌ — tur, toifa."},
{num:341,time:"00:26:23,560 --> 00:26:25,960",arabic:"يُخَادِعُونَ اللَّهَ وَالَّذِينَ آمَنُوا،",segs:[{ar:"يُخَادِعُونَ اللَّهَ",uz:"Allohni aldamoqchi bo‘ladilar"},{ar:"وَالَّذِينَ آمَنُوا،",uz:"va iymon keltirganlarni,"}],full_uz:"Allohni va iymon keltirganlarni aldamoqchi bo‘ladilar,",note:"خَادَعَ — aldashga urinmoq, hiyla ishlatmoq."},
{num:342,time:"00:26:26,680 --> 00:26:29,920",arabic:"لَكِنَّهُمْ فِي الْحَقِيقَةِ لَا يَخْدَعُونَ إِلَّا أَنْفُسَهُمْ.",segs:[{ar:"لَكِنَّهُمْ فِي الْحَقِيقَةِ",uz:"Lekin ular aslida"},{ar:"لَا يَخْدَعُونَ إِلَّا أَنْفُسَهُمْ.",uz:"faqat o‘zlarini aldaydilar."}],full_uz:"Lekin ular aslida faqat o‘zlarini aldaydilar.",note:"أَنْفُسَهُمْ — o‘zlarini. لَا ... إِلَّا cheklash ma’nosini beradi."},
{num:343,time:"00:26:29,920 --> 00:26:34,519",arabic:"وَقَدْ أَرَادَ بِذَلِكَ أَنْ يَقَعَ عَلَى حَقِيقَةِ اعْتِقَادِكَ.",segs:[{ar:"وَقَدْ أَرَادَ بِذَلِكَ",uz:"U bu bilan istagan"},{ar:"أَنْ يَقَعَ عَلَى",uz:"bilib olishni"},{ar:"حَقِيقَةِ اعْتِقَادِكَ.",uz:"e’tiqodingizning asl mohiyatini."}],full_uz:"U bu bilan asl e’tiqodingizni bilib olmoqchi bo‘lgan.",note:"وَقَعَ عَلَى — bu yerda topmoq, aniqlamoq, bilib olmoq ma’nosida."},
{num:344,time:"00:26:34,519 --> 00:26:38,880",arabic:"وَظَنِّي أَنَّهُ يَوَدُّ أَنْ تَكُونَ مِنْ جَمَاعَتِهِ.",segs:[{ar:"وَظَنِّي أَنَّهُ يَوَدُّ",uz:"Menimcha, u xohlaydi"},{ar:"أَنْ تَكُونَ مِنْ جَمَاعَتِهِ.",uz:"siz uning guruhidan bo‘lishingizni."}],full_uz:"Menimcha, u sizning o‘z guruhidan bo‘lishingizni xohlaydi.",note:"يَوَدُّ — istaydi, xohlaydi; وَدَّ fe’lining hozirgi-kelasi zamon shakli."},
{num:345,time:"00:26:38,880 --> 00:26:40,840",arabic:"أَعُوذُ بِاللَّهِ.",segs:null,full_uz:"Allohdan panoh so‘rayman.",note:"عَاذَ بِـ — ...dan panoh so‘ramoq, ...ning himoyasiga sig‘inmoq."},
{num:346,time:"00:26:40,840 --> 00:26:44,680",arabic:"أَعُوذُ بِاللَّهِ مِنْ قَوْلِ أَهْلِ الْبَاطِلِ.",segs:[{ar:"أَعُوذُ بِاللَّهِ",uz:"Allohdan panoh so‘rayman"},{ar:"مِنْ قَوْلِ أَهْلِ الْبَاطِلِ.",uz:"botil ahlining so‘zidan."}],full_uz:"Botil ahlining so‘zidan Allohdan panoh so‘rayman.",note:"أَعُوذُ بِاللَّهِ مِنْ... — ...dan Allohning panohiga sig‘inaman."},
{num:347,time:"00:26:45,480 --> 00:26:49,680",arabic:"وَقَانَا اللَّهُ شُرُورَ أَهْلِ الْبِدَعِ وَالْأَهْوَاءِ.",segs:[{ar:"وَقَانَا اللَّهُ",uz:"Alloh bizni asrasin"},{ar:"شُرُورَ أَهْلِ الْبِدَعِ وَالْأَهْوَاءِ.",uz:"bid’at va havoyi nafs ahlining yomonliklaridan."}],full_uz:"Alloh bizni bid’at va havoyi nafs ahlining yomonliklaridan asrasin.",note:"وَقَى — asradi; bu yerda duo ma’nosida. شُرُورٌ — شَرٌّ so‘zining ko‘pligi."},
{num:348,time:"00:26:50,200 --> 00:26:53,460",arabic:"جَنِّبْ أَمْثَالَهُ مَجْلِسَكَ يَا شَافِعِيُّ.",segs:[{ar:"جَنِّبْ أَمْثَالَهُ مَجْلِسَكَ",uz:"Unga o‘xshaganlarni majlisingizdan chetda tuting"},{ar:"يَا شَافِعِيُّ.",uz:"Shofe’iy."}],full_uz:"Shofe’iy, unga o‘xshaganlarni majlisingizdan chetda tuting.",note:"جَنَّبَ — chetlatmoq, uzoq tutmoq. أَمْثَالُهُ — unga o‘xshaganlar."},
{num:349,time:"00:26:53,460 --> 00:26:55,560",arabic:"لَا يَا ابْنَ الْحَسَنِ، لَا.",segs:[{ar:"لَا يَا ابْنَ الْحَسَنِ،",uz:"Yo‘q, Ibn Hasan,"},{ar:"لَا.",uz:"yo‘q."}],full_uz:"Yo‘q, Ibn Hasan, yo‘q.",note:null},
{num:350,time:"00:26:56,680 --> 00:27:01,420",arabic:"لَا، النَّارُ الْمُشْتَعِلَةُ تَحْتَاجُ لِمَنْ يُطْفِئُهَا.",segs:[{ar:"لَا،",uz:"Yo‘q,"},{ar:"النَّارُ الْمُشْتَعِلَةُ",uz:"yonayotgan olov"},{ar:"تَحْتَاجُ لِمَنْ يُطْفِئُهَا.",uz:"uni o‘chiradigan kishiga muhtoj."}],full_uz:"Yo‘q, yonayotgan olov uni o‘chiradigan kishiga muhtoj.",note:"اشْتَعَلَ — yonmoq, alangalanmoq; أَطْفَأَ — o‘chirmoq."},
{num:351,time:"00:27:01,420 --> 00:27:04,460",arabic:"وَالضَّالُّ عَلَيْنَا أَنْ نُرْشِدَهُ.",segs:[{ar:"وَالضَّالُّ",uz:"Adashgan kishini esa"},{ar:"عَلَيْنَا أَنْ نُرْشِدَهُ.",uz:"biz to‘g‘ri yo‘lga boshlashimiz kerak."}],full_uz:"Adashgan kishini esa to‘g‘ri yo‘lga boshlashimiz kerak.",note:"عَلَيْنَا أَنْ... — biz ...qilishimiz kerak. أَرْشَدَ — yo‘l ko‘rsatmoq."},
{num:352,time:"00:27:04,460 --> 00:27:10,519",arabic:"وَمَا اسْتَفْحَلَ أَمْرُ هَؤُلَاءِ إِلَّا لِسُكُوتِنَا عَنْهُمْ وَتَجَنُّبِنَا لَهُمْ.",segs:[{ar:"وَمَا اسْتَفْحَلَ أَمْرُ هَؤُلَاءِ",uz:"Ularning ishi kuchaygani"},{ar:"إِلَّا لِسُكُوتِنَا عَنْهُمْ",uz:"faqat ularga indamaganimiz sababli"},{ar:"وَتَجَنُّبِنَا لَهُمْ.",uz:"va ulardan chetlashganimiz sababli."}],full_uz:"Ularning ishi faqat ularga indamaganimiz va ulardan chetlashganimiz sababli kuchaydi.",note:"اسْتَفْحَلَ الْأَمْرُ — ish kuchaydi, jiddiy tus oldi. تَجَنُّبٌ — chetlashish, o‘zini olib qochish."},
{num:353,time:"00:27:12,500 --> 00:27:18,799",arabic:"الْجَاهِلُ يُعَلَّمُ، وَالْغَافِلُ يُذَكَّرُ.",segs:[{ar:"الْجَاهِلُ يُعَلَّمُ،",uz:"Bilmaganga o‘rgatiladi,"},{ar:"وَالْغَافِلُ يُذَكَّرُ.",uz:"g‘ofilga esa eslatiladi."}],full_uz:"Bilmaganga o‘rgatiladi, g‘ofilga esa eslatiladi.",note:"يُعَلَّمُ va يُذَكَّرُ — majhul nisbat: o‘rgatiladi, eslatiladi."},
{num:354,time:"00:27:18,799 --> 00:27:23,779",arabic:"إِنَّ مَنْ كَانَ عَلَى الْحَقِّ أَيُّهَا الْإِخْوَةُ،",segs:[{ar:"إِنَّ مَنْ كَانَ عَلَى الْحَقِّ",uz:"Haq yo‘lda bo‘lgan kishi"},{ar:"أَيُّهَا الْإِخْوَةُ،",uz:"birodarlar,"}],full_uz:"Birodarlar, haq yo‘lda bo‘lgan kishi",note:"عَلَى الْحَقِّ — haq yo‘lda, haq tomonida. Gap keyingi parchada davom etadi."},
{num:355,time:"00:27:23,779 --> 00:27:28,220",arabic:"لَا يَكْتَرِثُ لِمَنْ يَكِيدُونَ لَهُ حَتَّى لَوْ مَلَؤُوا الْآفَاقَ.",segs:[{ar:"لَا يَكْتَرِثُ",uz:"parvo qilmaydi"},{ar:"لِمَنْ يَكِيدُونَ لَهُ",uz:"unga qarshi hiyla qiladiganlarga"},{ar:"حَتَّى لَوْ مَلَؤُوا الْآفَاقَ.",uz:"hatto ular butun ufqlarni to‘ldirsalar ham."}],full_uz:"O‘ziga qarshi hiyla qiladiganlar butun ufqlarni to‘ldirsalar ham, ularga parvo qilmaydi.",note:"لَا يَكْتَرِثُ — parvo qilmaydi. حَتَّى لَوْ — hatto ...bo‘lsa ham."},
{num:356,time:"00:27:28,220 --> 00:27:31,299",arabic:"فَالْمُؤْمِنُ قَوِيٌّ بِإِيمَانِهِ،",segs:[{ar:"فَالْمُؤْمِنُ قَوِيٌّ",uz:"Chunki mo‘min kuchlidir"},{ar:"بِإِيمَانِهِ،",uz:"iymoni bilan,"}],full_uz:"Chunki mo‘min iymoni bilan kuchlidir,",note:"بِإِيمَانِهِ — iymoni bilan, iymoni sababli."},
{num:357,time:"00:27:31,299 --> 00:27:33,220",arabic:"وَاثِقٌ بِرَبِّهِ،",segs:null,full_uz:"Rabbiga ishongan,",note:"وَاثِقٌ بِـ — ...ga ishongan, ...ga ishonchi komil."},
{num:358,time:"00:27:33,220 --> 00:27:36,639",arabic:"يَعْرِفُ بِأَنَّهُ سَيُمْتَحَنُ وَيُبْتَلَى.",segs:[{ar:"يَعْرِفُ بِأَنَّهُ",uz:"U biladi"},{ar:"سَيُمْتَحَنُ وَيُبْتَلَى.",uz:"imtihon va sinovga duchor bo‘lishini."}],full_uz:"U imtihon va sinovga duchor bo‘lishini biladi.",note:"يُمْتَحَنُ va يُبْتَلَى — majhul nisbatdagi fe’llar: imtihon qilinadi, sinaladi."},
{num:359,time:"00:27:36,639 --> 00:27:42,220",arabic:"أَتَحْسَبُونَ أَنَّنَا أَوَّلُ مَنْ ظُلِمَ مِنْ أَجْلِ مَا يُؤْمِنُ بِهِ؟",segs:[{ar:"أَتَحْسَبُونَ",uz:"O‘ylaysizlarmi"},{ar:"أَنَّنَا أَوَّلُ مَنْ ظُلِمَ",uz:"bizni birinchi zulm ko‘rganlar deb"},{ar:"مِنْ أَجْلِ مَا يُؤْمِنُ بِهِ؟",uz:"o‘z e’tiqodi sababli?"}],full_uz:"Bizni o‘z e’tiqodi sababli zulm ko‘rganlarning birinchisi deb o‘ylaysizlarmi?",note:"ظُلِمَ — unga zulm qilindi. مِنْ أَجْلِ — ...sababli, ...uchun."},
{num:360,time:"00:27:42,220 --> 00:27:43,099",arabic:"لَا يَا إِخْوَتِي.",segs:null,full_uz:"Yo‘q, birodarlarim.",note:"إِخْوَتِي — mening birodarlarim; oxirgi ي egalikni bildiradi."},
{num:361,time:"00:27:43,099 --> 00:27:45,740",arabic:"لَسْنَا أَوَّلَ الْمَظْلُومِينَ،",segs:null,full_uz:"Biz zulm ko‘rganlarning birinchisi emasmiz,",note:"لَسْنَا — biz emasmiz; لَيْسَ fe’lining birinchi shaxs ko‘plik shakli."},
{num:362,time:"00:27:45,740 --> 00:27:48,339",arabic:"وَلَا هَارُونُ أَوَّلُ ظَالِمٍ.",segs:null,full_uz:"Horun ham birinchi zolim emas.",note:"ظَالِمٌ — zulm qiluvchi; مَظْلُومٌ — zulm ko‘rgan kishi."},
{num:363,time:"00:27:48,339 --> 00:27:54,039",arabic:"لَقَدْ سَبَقَنَا إِخْوَةٌ لَنَا ظُلِمُوا مِنْ أَجْلِ مَا يُؤْمِنُونَ بِهِ،",segs:[{ar:"لَقَدْ سَبَقَنَا إِخْوَةٌ لَنَا",uz:"Bizdan oldin ham birodarlarimiz o‘tgan"},{ar:"ظُلِمُوا",uz:"ular zulm ko‘rganlar"},{ar:"مِنْ أَجْلِ مَا يُؤْمِنُونَ بِهِ،",uz:"ishongan narsalari sababli,"}],full_uz:"Bizdan oldin ham o‘z e’tiqodi sababli zulm ko‘rgan birodarlarimiz o‘tgan,",note:"سَبَقَنَا — bizdan oldin bo‘ldi, bizdan ilgari o‘tdi. ظُلِمُوا — ularga zulm qilindi."},
{num:364,time:"00:27:54,039 --> 00:27:56,019",arabic:"وَلَكِنَّهُمْ لَمْ يَهِنُوا.",segs:null,full_uz:"Lekin ular zaiflashmadilar.",note:"وَهَنَ — zaiflashmoq; لَمْ يَهِنُوا — zaiflashmadilar. Jazmda oxirgi ن tushgan."},
{num:365,time:"00:27:56,019 --> 00:27:57,459",arabic:"لِمَاذَا؟",segs:null,full_uz:"Nega?",note:null},
{num:366,time:"00:27:57,459 --> 00:28:02,339",arabic:"لِأَنَّهُمْ أَسْلَمُوا قِيَادَهُمْ لِلَّهِ سُبْحَانَهُ وَتَعَالَى.",segs:[{ar:"لِأَنَّهُمْ أَسْلَمُوا قِيَادَهُمْ",uz:"Chunki ular o‘z ixtiyorlarini topshirdilar"},{ar:"لِلَّهِ",uz:"Allohga"},{ar:"سُبْحَانَهُ وَتَعَالَى.",uz:"U pok va yuksakdir."}],full_uz:"Chunki ular o‘z ixtiyorlarini Alloh subhanahu va taologa topshirdilar.",note:"قِيَادٌ — jilov, boshqaruv; أَسْلَمَ قِيَادَهُ — o‘zini boshqarish ixtiyorini topshirdi."},
{num:367,time:"00:28:02,919 --> 00:28:04,559",arabic:"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ.",segs:[{ar:"السَّلَامُ عَلَيْكُمْ",uz:"Sizlarga tinchlik bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ.",uz:"va Allohning rahmati."}],full_uz:"Assalomu alaykum va rahmatulloh.",note:null},
{num:368,time:"00:28:07,679 --> 00:28:08,339",arabic:"تَفَضَّلُوا.",segs:null,full_uz:"Marhamat qilinglar.",note:"تَفَضَّلُوا — ko‘pchilikka qaratilgan marhamat qilinglar shakli."},
{num:369,time:"00:28:08,980 --> 00:28:13,599",arabic:"تَأَخَّرْتَ عَلَيْنَا أَيُّهَا الْمَرِيسِيُّ.",segs:[{ar:"تَأَخَّرْتَ عَلَيْنَا",uz:"Bizni kuttirib qo‘ydingiz"},{ar:"أَيُّهَا الْمَرِيسِيُّ.",uz:"ey Marisiy."}],full_uz:"Bizni kuttirib qo‘ydingiz, Marisiy.",note:"تَأَخَّرَ عَلَى فُلَانٍ — birovning oldiga kechikib kelmoq, uni kuttirmoq."},
{num:370,time:"00:28:13,599 --> 00:28:18,279",arabic:"صَادَفْتُ الْيَوْمَ رَجُلًا لَمْ تَرَ عَيْنَايَ مِثْلَهُ.",segs:[{ar:"صَادَفْتُ الْيَوْمَ رَجُلًا",uz:"Bugun bir kishini uchratdim"},{ar:"لَمْ تَرَ عَيْنَايَ مِثْلَهُ.",uz:"ko‘zlarim uning o‘xshashini ko‘rmagan."}],full_uz:"Bugun bir kishini uchratdim, ko‘zlarim uning o‘xshashini ko‘rmagan.",note:"عَيْنَايَ — mening ikki ko‘zim. لَمْ تَرَ — ko‘rmadi; jazm sababli fe’lning oxirgi ا harfi tushgan."},
{num:371,time:"00:28:18,279 --> 00:28:21,200",arabic:"إِنَّهُ مِنْ مَكَّةَ الْمُكَرَّمَةِ،",segs:null,full_uz:"U Makkai Mukarramadan,",note:null},
{num:372,time:"00:28:21,200 --> 00:28:24,960",arabic:"وَاسْمُهُ مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ.",segs:[{ar:"وَاسْمُهُ",uz:"ismi esa"},{ar:"مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ.",uz:"Muhammad ibn Idris Shofe’iy."}],full_uz:"Ismi esa Muhammad ibn Idris Shofe’iy.",note:null},
{num:373,time:"00:28:24,960 --> 00:28:27,819",arabic:"قُرَشِيٌّ هَاشِمِيٌّ.",segs:null,full_uz:"Qurayshiy, hoshimiy.",note:"ـِيٌّ nisbat qo‘shimchasi mansublikni bildiradi; bu yerda nasabga nisbat berilgan."},
{num:374,time:"00:28:27,819 --> 00:28:33,460",arabic:"إِذَنْ فَهُوَ ضَالٌّ كَابْنِ عَمِّهِ هَارُونَ.",segs:[{ar:"إِذَنْ فَهُوَ ضَالٌّ",uz:"Unda u ham adashgan"},{ar:"كَابْنِ عَمِّهِ هَارُونَ.",uz:"amakivachchasi Horun kabi."}],full_uz:"Unda u ham amakivachchasi Horun kabi adashgan.",note:"ابْنُ عَمِّهِ — uning amakivachchasi; umumiy ajdoddan kelgan uzoq qarindoshga nisbatan ham ishlatiladi."},
{num:375,time:"00:28:33,460 --> 00:28:34,759",arabic:"لَا يَا ابْنَ الْأَشْرَسِ.",segs:null,full_uz:"Yo‘q, Ibn Ashras.",note:null},
{num:376,time:"00:28:34,759 --> 00:28:40,779",arabic:"إِنَّهُ فَقِيهٌ حَافِظٌ مُحَدِّثٌ مُتَكَلِّمٌ فَصِيحٌ شَاعِرٌ.",segs:[{ar:"إِنَّهُ فَقِيهٌ حَافِظٌ",uz:"U faqih va hofiz"},{ar:"مُحَدِّثٌ مُتَكَلِّمٌ",uz:"muhaddis va so‘zga usta"},{ar:"فَصِيحٌ شَاعِرٌ.",uz:"fasohatli va shoirdir."}],full_uz:"U faqih, hofiz, muhaddis, so‘zga usta, fasohatli va shoirdir.",note:"مُحَدِّثٌ — hadis olimi; فَصِيحٌ — ravon va aniq so‘zlaydigan."},
{num:377,time:"00:28:40,779 --> 00:28:43,399",arabic:"وَمَا الَّذِي جَمَعَكَ بِهِ يَا أَبَا عَبْدِ الرَّحْمَنِ؟",segs:[{ar:"وَمَا الَّذِي جَمَعَكَ بِهِ",uz:"Sizni u bilan nima uchrashtirdi"},{ar:"يَا أَبَا عَبْدِ الرَّحْمَنِ؟",uz:"Abu Abdurahmon?"}],full_uz:"Sizni u bilan nima uchrashtirdi, Abu Abdurahmon?",note:"جَمَعَ فُلَانًا بِفُلَانٍ — bir kishini boshqasi bilan uchrashtirmoq."},
{num:378,time:"00:28:43,399 --> 00:28:45,220",arabic:"قَدَرُ اللَّهِ جَمَعَنَا.",segs:null,full_uz:"Allohning taqdiri bizni uchrashtirdi.",note:"قَدَرُ اللَّهِ — Allohning taqdiri; gapning egasi."},
{num:379,time:"00:28:45,220 --> 00:28:51,640",arabic:"وَإِنِّي لَأَرْجُو مِنَ اللَّهِ أَنْ يَهْدِيَهُ إِلَى حَقِيقَةِ الْإِيمَانِ كَمَا هَدَانَا مِنْ قَبْلُ.",segs:[{ar:"وَإِنِّي لَأَرْجُو مِنَ اللَّهِ",uz:"Men Allohdan umid qilamanki"},{ar:"أَنْ يَهْدِيَهُ",uz:"uni hidoyat qilsin"},{ar:"إِلَى حَقِيقَةِ الْإِيمَانِ",uz:"iymonning asl haqiqatiga"},{ar:"كَمَا هَدَانَا مِنْ قَبْلُ.",uz:"ilgari bizni hidoyat qilganidek."}],full_uz:"Alloh ilgari bizni hidoyat qilganidek, uni ham iymonning asl haqiqatiga hidoyat qilishini umid qilaman.",note:"إِنِّي لَأَرْجُو dagi إِنَّ va لَ ta’kidni kuchaytiradi. هَدَى إِلَى — ...ga yo‘llamoq."},
{num:380,time:"00:28:51,640 --> 00:28:54,339",arabic:"فَهُوَ مَكْسَبٌ لَنَا، وَأَيُّمَا مَكْسَبٍ!",segs:[{ar:"فَهُوَ مَكْسَبٌ لَنَا،",uz:"U biz uchun yutuqdir,"},{ar:"وَأَيُّمَا مَكْسَبٍ!",uz:"yana qanday yutuq!"}],full_uz:"U biz uchun katta yutuq bo‘ladi, yana qanday yutuq!",note:"وَأَيُّمَا مَكْسَبٍ — yutuqning nihoyatda katta ekanini ta’kidlovchi ifoda."},
{num:381,time:"00:28:54,339 --> 00:28:58,059",arabic:"إِذَنْ فَأَنْتَ تُحَدِّثُ نَفْسَكَ بِضَمِّهِ إِلَيْنَا.",segs:[{ar:"إِذَنْ فَأَنْتَ تُحَدِّثُ نَفْسَكَ",uz:"Demak, siz o‘ylab yuribsiz"},{ar:"بِضَمِّهِ إِلَيْنَا.",uz:"uni bizga qo‘shishni."}],full_uz:"Demak, siz uni bizga qo‘shishni o‘ylab yuribsiz.",note:"حَدَّثَ نَفْسَهُ بِـ — biror ishni qilishni ko‘nglidan o‘tkazmoq."},
{num:382,time:"00:28:58,059 --> 00:29:03,220",arabic:"لَوْ كَانَ الْأَمْرُ بِيَدِي لَفَعَلْتُهُ السَّاعَةَ، إِنَّهُ فَوْقَ مَا أَصِفُ.",segs:[{ar:"لَوْ كَانَ الْأَمْرُ بِيَدِي",uz:"Agar ish mening qo‘limda bo‘lganida"},{ar:"لَفَعَلْتُهُ السَّاعَةَ،",uz:"hoziroq qilgan bo‘lardim,"},{ar:"إِنَّهُ فَوْقَ مَا أَصِفُ.",uz:"u men ta’riflaganimdan ham ortiq."}],full_uz:"Agar ish mening qo‘limda bo‘lganida, hoziroq qilgan bo‘lardim. U men ta’riflaganimdan ham ortiq.",note:"السَّاعَةَ — bu yerda hozir, shu zahoti. لَوْ ... لَـ — ...bo‘lganida, ...qilgan bo‘lardim."},
{num:383,time:"00:29:03,880 --> 00:29:08,440",arabic:"أَمْثَالُ هَؤُلَاءِ قَدْ رَانَ عَلَى قُلُوبِهِمْ مَا يَكْسِبُونَ،",segs:[{ar:"أَمْثَالُ هَؤُلَاءِ",uz:"Bunday kishilarning"},{ar:"قَدْ رَانَ عَلَى قُلُوبِهِمْ",uz:"qalblarini qoplab olgan"},{ar:"مَا يَكْسِبُونَ،",uz:"qilayotgan ishlari,"}],full_uz:"Bunday kishilarning qalblarini qilayotgan ishlari qoplab olgan,",note:"رَانَ عَلَى — qoplab olmoq, g‘ubor bosmoq. مَا يَكْسِبُونَ — ularning qilayotgan ishlari."},
{num:384,time:"00:29:08,440 --> 00:29:12,220",arabic:"وَأَتْبَعُوا أَنْفُسَهُمْ هَوَاهَا، فَلَا تَرْجُ مِنْهُمْ شَيْئًا.",segs:[{ar:"وَأَتْبَعُوا أَنْفُسَهُمْ هَوَاهَا،",uz:"ular nafslarini uning havoyi istaklariga ergashtirdilar,"},{ar:"فَلَا تَرْجُ مِنْهُمْ شَيْئًا.",uz:"shuning uchun ulardan hech narsa kutmang."}],full_uz:"Ular nafslarini havoyi istaklariga ergashtirdilar. Shuning uchun ulardan hech narsa kutmang.",note:"لَا تَرْجُ — umid qilma; taqiq sababli تَرْجُو fe’lining oxirgi و harfi tushgan."},
{num:385,time:"00:29:12,220 --> 00:29:16,480",arabic:"لَا بَأْسَ مِنَ الْمُحَاوَلَةِ يَا ابْنَ الْأَشْرَسِ، لَا نَخْسَرُ شَيْئًا.",segs:[{ar:"لَا بَأْسَ مِنَ الْمُحَاوَلَةِ",uz:"Urinib ko‘rishning zarari yo‘q"},{ar:"يَا ابْنَ الْأَشْرَسِ،",uz:"Ibn Ashras,"},{ar:"لَا نَخْسَرُ شَيْئًا.",uz:"hech narsa yo‘qotmaymiz."}],full_uz:"Urinib ko‘rishning zarari yo‘q, Ibn Ashras. Hech narsa yo‘qotmaymiz.",note:"مُحَاوَلَةٌ — urinish; خَسِرَ — yo‘qotmoq, zarar ko‘rmoq."},
{num:386,time:"00:29:16,480 --> 00:29:20,400",arabic:"إِذَنْ نَتْرُكُ الْأَمْرَ لَكَ يَا أَبَا عَبْدِ الرَّحْمَنِ.",segs:[{ar:"إِذَنْ نَتْرُكُ الْأَمْرَ لَكَ",uz:"Unda bu ishni sizga qoldiramiz"},{ar:"يَا أَبَا عَبْدِ الرَّحْمَنِ.",uz:"Abu Abdurahmon."}],full_uz:"Unda bu ishni sizga qoldiramiz, Abu Abdurahmon.",note:null},
{num:387,time:"00:29:20,400 --> 00:29:23,680",arabic:"فَأَنْتَ أَلْسَنُنَا وَأَفْقَهُنَا فِي دِينِ اللَّهِ.",segs:[{ar:"فَأَنْتَ أَلْسَنُنَا",uz:"Chunki siz oramizda eng so‘zga ustasiz"},{ar:"وَأَفْقَهُنَا فِي دِينِ اللَّهِ.",uz:"va Allohning dinini eng chuqur biluvchisiz."}],full_uz:"Chunki siz oramizda eng so‘zga usta va Allohning dinini eng chuqur biluvchisiz.",note:"أَلْسَنُ — so‘zga ustaroq; أَفْقَهُ — chuqurroq tushunadigan. ـنَا bilan: oramizda eng ...bo‘lgan."},
{num:388,time:"00:29:23,680 --> 00:29:26,120",arabic:"بَارَكَ اللَّهُ فِيكَ يَا رَجُلُ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"يَا رَجُلُ.",uz:"birodar."}],full_uz:"Alloh sizga baraka bersin, birodar.",note:"بَارَكَ اللَّهُ فِيكَ — minnatdorlik va yaxshi tilak bildiruvchi duo."},
{num:389,time:"00:29:42,220 --> 00:29:49,880",arabic:"إِنْ أَرَدْتَ شِرَائِي،",segs:null,full_uz:"Agar meni sotib olmoqchi bo‘lsangiz,",note:"شِرَائِي — meni sotib olish; شِرَاءٌ so‘ziga ـِي qo‘shilgan."},
{num:390,time:"00:29:49,880 --> 00:29:51,700",arabic:"فَلِي شَرْطٌ.",segs:null,full_uz:"Mening bir shartim bor.",note:"لِي شَرْطٌ — mening shartim bor; egalik لِ yordamida ifodalangan."},
{num:391,time:"00:29:51,700 --> 00:29:53,539",arabic:"إِنْ قَبِلْتَ بِهِ،",segs:null,full_uz:"Agar uni qabul qilsangiz,",note:"قَبِلَ بِـ — rozi bo‘lmoq, qabul qilmoq."},
{num:392,time:"00:29:53,539 --> 00:29:54,559",arabic:"وَافَقْتُ.",segs:null,full_uz:"Men ham rozi bo‘laman.",note:"Shartning javobidagi o‘tgan zamon shakli bu yerda kelajakdagi natijani bildiradi."},
{num:393,time:"00:29:54,559 --> 00:29:56,059",arabic:"وَإِنْ لَمْ تَقْبَلْ،",segs:null,full_uz:"Agar qabul qilmasangiz esa,",note:null},
{num:394,time:"00:29:56,059 --> 00:29:57,700",arabic:"فَأَنَا لَسْتُ لِلْبَيْعِ.",segs:null,full_uz:"Men sotilmayman.",note:"لِلْبَيْعِ — sotish uchun; لَسْتُ لِلْبَيْعِ — men sotiladigan emasman."},
{num:395,time:"00:29:57,700 --> 00:30:00,100",arabic:"وَمَنْ أَنْتِ حَتَّى تَشْتَرِطِي؟",segs:[{ar:"وَمَنْ أَنْتِ",uz:"Sen kimsanki"},{ar:"حَتَّى تَشْتَرِطِي؟",uz:"shart qo‘yasan?"}],full_uz:"Sen kimsanki, shart qo‘yasan?",note:"اشْتَرَطَ — shart qo‘ymoq. حَتَّى dan keyin تَشْتَرِطِينَ shaklidagi ن tushgan."},
{num:396,time:"00:30:00,100 --> 00:30:00,720",arabic:"ثَكِلَتْكِ!",segs:null,full_uz:"Onang sendan ayrilib qolsin!",note:"ثَكِلَتْكِ — qarg‘ish ifodasi; أُمُّكِ so‘zi aytilmasa ham mazmundan anglashiladi."},
{num:397,time:"00:30:00,720 --> 00:30:01,480",arabic:"قُولِي شَرْطَكِ.",segs:null,full_uz:"Shartingizni ayting.",note:"قُولِي — ayol kishiga qaratilgan ayt buyrug‘i."},
{num:398,time:"00:30:01,480 --> 00:30:03,700",arabic:"إِنِّي أَسْمَعُكِ.",segs:null,full_uz:"Sizni eshityapman.",note:null},
{num:399,time:"00:30:03,700 --> 00:30:06,860",arabic:"لَا أُرِيدُ أَنْ يَسْمَعَ شَرْطِي أَحَدٌ غَيْرُكَ.",segs:[{ar:"لَا أُرِيدُ",uz:"Istamayman"},{ar:"أَنْ يَسْمَعَ شَرْطِي",uz:"shartimni eshitishini"},{ar:"أَحَدٌ غَيْرُكَ.",uz:"sizdan boshqa hech kimning."}],full_uz:"Shartimni sizdan boshqa hech kim eshitishini istamayman.",note:"أَحَدٌ غَيْرُكَ — sizdan boshqa biror kishi."},
{num:400,time:"00:30:06,860 --> 00:30:11,000",arabic:"إِنْ كُنْتِ لَا تُمَانِعِينَ يَا سَيِّدَتِي،",segs:[{ar:"إِنْ كُنْتِ لَا تُمَانِعِينَ",uz:"Agar qarshi bo‘lmasangiz"},{ar:"يَا سَيِّدَتِي،",uz:"xonim,"}],full_uz:"Agar qarshi bo‘lmasangiz, xonim,",note:"لَا تُمَانِعِينَ — qarshi emassiz; ayol kishiga murojaat shakli."},
{num:401,time:"00:30:11,000 --> 00:30:14,099",arabic:"أُرِيدُ أَنْ أَتَحَدَّثَ مَعَهَا وَحْدَنَا.",segs:[{ar:"أُرِيدُ أَنْ أَتَحَدَّثَ مَعَهَا",uz:"U bilan gaplashmoqchiman"},{ar:"وَحْدَنَا.",uz:"ikkimiz yolg‘iz."}],full_uz:"U bilan yolg‘iz gaplashmoqchiman.",note:"وَحْدَنَا — biz yolg‘iz, boshqalarsiz."},
{num:402,time:"00:30:14,099 --> 00:30:18,720",arabic:"تَعَالَ مَعِي يَا حَنْظَلَةُ.",segs:[{ar:"تَعَالَ مَعِي",uz:"Men bilan yur"},{ar:"يَا حَنْظَلَةُ.",uz:"Hanzala."}],full_uz:"Men bilan yur, Hanzala.",note:null},
{num:403,time:"00:30:26,779 --> 00:30:28,660",arabic:"هَا قَدْ أَصْبَحْنَا وَحْدَنَا.",segs:null,full_uz:"Mana, endi yolg‘iz qoldik.",note:"هَا قَدْ... — mana, ...bo‘ldi; yangi yuzaga kelgan holatga e’tibor qaratadi."},
{num:404,time:"00:30:28,660 --> 00:30:30,319",arabic:"تَكَلَّمِي.",segs:null,full_uz:"Gapiring.",note:"تَكَلَّمِي — ayolga qaratilgan buyruq; erkakka تَكَلَّمْ deyiladi."},
{num:405,time:"00:30:30,319 --> 00:30:33,059",arabic:"قَدْ عَلِمْتُ أَنَّ لَدَيْكَ أُخْتًا مَرِيضَةً،",segs:[{ar:"قَدْ عَلِمْتُ",uz:"Bildim"},{ar:"أَنَّ لَدَيْكَ أُخْتًا مَرِيضَةً،",uz:"kasal opa-singlingiz borligini,"}],full_uz:"Kasal opa-singlingiz borligini bildim,",note:"أُخْتٌ — opa yoki singil; arabcha so‘zning o‘zi yosh farqini bildirmaydi."},
{num:406,time:"00:30:33,059 --> 00:30:35,839",arabic:"وَأَنَّكَ تُرِيدُنِي أَنْ أَقُومَ عَلَى خِدْمَتِهَا.",segs:[{ar:"وَأَنَّكَ تُرِيدُنِي",uz:"va siz mendan istayotganingizni"},{ar:"أَنْ أَقُومَ عَلَى خِدْمَتِهَا.",uz:"uning xizmatini qilishimni."}],full_uz:"Va siz uning xizmatini qilishimni istayotganingizni ham bildim.",note:"قَامَ عَلَى خِدْمَةِ فُلَانٍ — birovning xizmatini, parvarishini zimmasiga olmoq."},
{num:407,time:"00:30:35,839 --> 00:30:36,839",arabic:"وَأَنَا مُوَافِقَةٌ.",segs:null,full_uz:"Men roziman.",note:"مُوَافِقَةٌ — rozi bo‘lgan ayol; erkak uchun مُوَافِقٌ."},
{num:408,time:"00:30:36,839 --> 00:30:39,940",arabic:"وَلَكِنِّي سَأَكُونُ فِي بَيْتِكَ خَادِمَةً،",segs:[{ar:"وَلَكِنِّي سَأَكُونُ",uz:"Lekin men bo‘laman"},{ar:"فِي بَيْتِكَ خَادِمَةً،",uz:"uyingizda xizmatkor,"}],full_uz:"Lekin uyingizda xizmatkor bo‘laman,",note:"خَادِمَةً — أَكُونُ fe’lining kesimi bo‘lgani uchun tushum holatida."},
{num:409,time:"00:30:39,940 --> 00:30:41,960",arabic:"خَادِمَةً فَقَطْ.",segs:null,full_uz:"Faqat xizmatkor.",note:"فَقَطْ — faqat, xolos."},
{num:410,time:"00:30:41,960 --> 00:30:46,100",arabic:"أَنَا حُرَّةٌ.",segs:null,full_uz:"Men ozod ayolman.",note:"حُرَّةٌ — ozod ayol; erkak uchun حُرٌّ."},
{num:411,time:"00:30:46,100 --> 00:30:48,340",arabic:"وَلَكِنَّكَ لَنْ تُصَدِّقَنِي.",segs:null,full_uz:"Lekin siz menga ishonmaysiz.",note:"صَدَّقَنِي — menga ishondi, gapimni rost deb bildi."},
{num:412,time:"00:30:48,340 --> 00:30:50,519",arabic:"وَلَا يَعْنِينِي أَنْ تُصَدِّقَنِي.",segs:[{ar:"وَلَا يَعْنِينِي",uz:"Menga muhim emas"},{ar:"أَنْ تُصَدِّقَنِي.",uz:"ishonishingiz."}],full_uz:"Menga ishonishingiz muhim emas.",note:"لَا يَعْنِينِي — meni qiziqtirmaydi, men uchun ahamiyatli emas."},
{num:413,time:"00:30:50,519 --> 00:30:52,740",arabic:"فَكِّرْ فِي شَرْطِي.",segs:null,full_uz:"Shartim haqida o‘ylab ko‘ring.",note:"فَكَّرَ فِي — ...haqida o‘ylamoq."},
{num:414,time:"00:30:52,740 --> 00:30:55,519",arabic:"وَلَا أَطْلُبُ مِنْكَ رَدًّا الْآنَ.",segs:[{ar:"وَلَا أَطْلُبُ مِنْكَ رَدًّا",uz:"Sizdan javob talab qilmayman"},{ar:"الْآنَ.",uz:"hozir."}],full_uz:"Sizdan hozir javob talab qilmayman.",note:"رَدٌّ — javob; bu yerda shartga munosabatini bildirish nazarda tutilgan."},
{num:415,time:"00:30:55,519 --> 00:30:58,660",arabic:"إِنْ قَبِلْتَ فَعُدْ،",segs:[{ar:"إِنْ قَبِلْتَ",uz:"Agar qabul qilsangiz"},{ar:"فَعُدْ،",uz:"qaytib keling,"}],full_uz:"Agar qabul qilsangiz, qaytib keling,",note:"عُدْ — عَادَ يَعُودُ fe’lining buyruq shakli: qayt."},
{num:416,time:"00:30:58,660 --> 00:31:01,660",arabic:"وَإِلَّا فَلَا تَعُدْ أَبَدًا.",segs:[{ar:"وَإِلَّا",uz:"Aks holda"},{ar:"فَلَا تَعُدْ أَبَدًا.",uz:"hech qachon qaytmang."}],full_uz:"Aks holda, hech qachon qaytmang.",note:"لَا تَعُدْ — qaytma; jazmda تَعُودُ fe’lining o‘rtadagi و harfi tushadi."},
{num:417,time:"00:31:09,940 --> 00:31:22,940",arabic:"مَاذَا قَالَتْ لَكَ هَذِهِ الْمَجْنُونَةُ؟",segs:[{ar:"مَاذَا قَالَتْ لَكَ",uz:"Sizga nima dedi"},{ar:"هَذِهِ الْمَجْنُونَةُ؟",uz:"bu telba ayol?"}],full_uz:"Bu telba ayol sizga nima dedi?",note:null},
{num:418,time:"00:31:24,180 --> 00:31:24,840",arabic:"لَا شَيْءَ مُهِمًّا.",segs:null,full_uz:"Hech qanday muhim narsa emas.",note:"لَا شَيْءَ — hech narsa yo‘q."},
{num:419,time:"00:31:24,840 --> 00:31:27,880",arabic:"قَدْ رَاقَتْ لِي وَأَظُنُّنِي سَأَشْتَرِيهَا.",segs:[{ar:"قَدْ رَاقَتْ لِي",uz:"U menga yoqdi"},{ar:"وَأَظُنُّنِي سَأَشْتَرِيهَا.",uz:"va uni sotib olaman deb o‘ylayman."}],full_uz:"U menga yoqdi. Uni sotib olaman deb o‘ylayman.",note:"رَاقَ لِي — menga yoqdi, ma’qul keldi."},
{num:420,time:"00:31:27,880 --> 00:31:29,900",arabic:"قَدْ تَأَخَّرْتُ الْآنَ.",segs:null,full_uz:"Endi kechikib qoldim.",note:null},
{num:421,time:"00:31:29,900 --> 00:31:32,580",arabic:"سَأَعُودُ قَرِيبًا لِنَتَّفِقَ عَلَى كُلِّ شَيْءٍ.",segs:[{ar:"سَأَعُودُ قَرِيبًا",uz:"Yaqinda qaytaman"},{ar:"لِنَتَّفِقَ عَلَى كُلِّ شَيْءٍ.",uz:"hamma narsani kelishib olishimiz uchun."}],full_uz:"Hamma narsani kelishib olishimiz uchun yaqinda qaytaman.",note:"اتَّفَقَ عَلَى — biror narsa yuzasidan kelishmoq. لِنَتَّفِقَ maqsadni bildiradi."},
{num:422,time:"00:31:32,580 --> 00:31:35,180",arabic:"عَلَى الرَّحْبِ وَالسَّعَةِ، فِي أَيِّ وَقْتٍ تَشَاءُ.",segs:[{ar:"عَلَى الرَّحْبِ وَالسَّعَةِ،",uz:"Bajonidil,"},{ar:"فِي أَيِّ وَقْتٍ تَشَاءُ.",uz:"istagan vaqtingizda."}],full_uz:"Bajonidil, istagan vaqtingizda keling.",note:"عَلَى الرَّحْبِ وَالسَّعَةِ — bajonidil, marhamat mazmunidagi ibora."},
{num:423,time:"00:31:39,940 --> 00:31:59,940",arabic:"هَلْ يَسْتَحِقُّ هَارُونُ أَنْ يَجْلِسَ عَلَى كُرْسِيِّ الْخِلَافَةِ؟",segs:[{ar:"هَلْ يَسْتَحِقُّ هَارُونُ",uz:"Horun loyiqmi"},{ar:"أَنْ يَجْلِسَ",uz:"o‘tirishga"},{ar:"عَلَى كُرْسِيِّ الْخِلَافَةِ؟",uz:"xalifalik taxtiga?"}],full_uz:"Horun xalifalik taxtiga o‘tirishga loyiqmi?",note:"اسْتَحَقَّ — loyiq bo‘lmoq, haqli bo‘lmoq."},
{num:424,time:"00:31:59,940 --> 00:32:05,120",arabic:"إِنَّ مِنْ وَرَائِكَ النَّارَ وَمِنْ أَمَامِكَ الْجَنَّةَ،",segs:[{ar:"إِنَّ مِنْ وَرَائِكَ النَّارَ",uz:"Ortingda do‘zax bor"},{ar:"وَمِنْ أَمَامِكَ الْجَنَّةَ،",uz:"oldingda esa jannat,"}],full_uz:"Ortingda do‘zax, oldingda esa jannat bor,",note:"وَرَاءَ — orqada; أَمَامَ — oldinda."},
{num:425,time:"00:32:05,119 --> 00:32:10,439",arabic:"وَوَاللَّهِ إِنِّي لَأَخْشَى أَنْ تَكُونَ الْأُولَى لَا الثَّانِيَةُ.",segs:[{ar:"وَوَاللَّهِ",uz:"Allohga qasamki,"},{ar:"إِنِّي لَأَخْشَى",uz:"men qo‘rqaman"},{ar:"أَنْ تَكُونَ الْأُولَى",uz:"birinchisi bo‘lishidan"},{ar:"لَا الثَّانِيَةُ.",uz:"ikkinchisi emas."}],full_uz:"Allohga qasamki, senga ikkinchisi emas, birinchisi nasib bo‘lishidan qo‘rqaman.",note:"الْأُولَى va الثَّانِيَةُ oldingi gapdagi do‘zax va jannatga tartib bilan ishora qiladi."},
{num:426,time:"00:32:10,439 --> 00:32:16,939",arabic:"فَمَنِ اسْتُرْعِيَ رَعِيَّةً وَلَمْ يُحِطْهُمْ بِنَصِيحَةٍ،",segs:[{ar:"فَمَنِ اسْتُرْعِيَ رَعِيَّةً",uz:"Kimga xalq boshqaruvi topshirilsa"},{ar:"وَلَمْ يُحِطْهُمْ بِنَصِيحَةٍ،",uz:"u esa ularga samimiy g‘amxo‘rlik qilmasa,"}],full_uz:"Kimga xalq boshqaruvi topshirilsa-yu, u ularga samimiy g‘amxo‘rlik qilmasa,",note:"اسْتُرْعِيَ — boshqaruv yoki parvarish unga topshirildi. نَصِيحَةٌ bu yerda samimiy g‘amxo‘rlik ma’nosida."},
{num:427,time:"00:32:16,939 --> 00:32:20,239",arabic:"لَمْ يَجِدْ رِيحَ الْجَنَّةِ.",segs:null,full_uz:"Jannatning hidini ham topmaydi.",note:"Bu gap oldingi مَنْ shartining javobi bo‘lgani uchun لَمْ يَجِدْ kelajakdagi oqibatni ham bildiradi."},
{num:428,time:"00:32:20,239 --> 00:32:24,699",arabic:"وَإِنَّ أَشَدَّ الْغِشِّ غِشُّ الْوَالِي لِرَعِيَّتِهِ.",segs:[{ar:"وَإِنَّ أَشَدَّ الْغِشِّ",uz:"Xiyonatning eng og‘iri"},{ar:"غِشُّ الْوَالِي لِرَعِيَّتِهِ.",uz:"hokimning o‘z xalqiga xiyonatidir."}],full_uz:"Xiyonatning eng og‘iri hokimning o‘z xalqiga xiyonatidir.",note:"غِشٌّ — aldov, xiyonat; رَعِيَّةٌ — hukmdor boshqaruvidagi xalq."},
{num:429,time:"00:32:24,699 --> 00:32:29,779",arabic:"اللَّهُمَّ أَظِلَّنَا بِظِلِّكَ،",segs:[{ar:"اللَّهُمَّ",uz:"Allohim,"},{ar:"أَظِلَّنَا بِظِلِّكَ،",uz:"bizni O‘z soyangga ol,"}],full_uz:"Allohim, bizni O‘z soyangga ol,",note:"أَظَلَّ — soyaga olmoq; buyruq shakli أَظِلَّ, bu yerda duo uchun ishlatilgan."},
{num:430,time:"00:32:29,779 --> 00:32:32,399",arabic:"يَوْمَ لَا ظِلَّ إِلَّا ظِلُّكَ.",segs:[{ar:"يَوْمَ لَا ظِلَّ",uz:"Hech qanday soya bo‘lmaydigan kunda"},{ar:"إِلَّا ظِلُّكَ.",uz:"Sening soyangdan boshqa."}],full_uz:"Sening soyangdan boshqa soya bo‘lmaydigan kunda.",note:"يَوْمَ oldingi duoning vaqtini bildiradi."},
{num:431,time:"00:32:32,400 --> 00:32:37,340",arabic:"عُدْتَ يَا حَارِثُ؟",segs:[{ar:"عُدْتَ",uz:"Qaytdingmi"},{ar:"يَا حَارِثُ؟",uz:"Horis?"}],full_uz:"Qaytdingmi, Horis?",note:"عُدْتَ — qaytding; عَادَ fe’liga تَ qo‘shilganda o‘rtadagi uzun unli tushadi."},
{num:432,time:"00:32:37,340 --> 00:32:41,840",arabic:"السَّلَامُ عَلَيْكَ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"السَّلَامُ عَلَيْكَ",uz:"Sizga salom bo‘lsin"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ.",uz:"ey mo‘minlar amiri."}],full_uz:"Assalomu alaykum, mo‘minlar amiri.",note:null},
{num:433,time:"00:32:44,960 --> 00:32:46,700",arabic:"مَا رَأَيْتَ؟",segs:null,full_uz:"Nimalarni ko‘rding?",note:null},
{num:434,time:"00:32:46,700 --> 00:32:49,680",arabic:"لَقَدْ لَحِقْتُ الْعَجُوزَ إِلَى أَنْ وَصَلَتْ دَارَهَا يَا مَوْلَايَ.",segs:[{ar:"لَقَدْ لَحِقْتُ الْعَجُوزَ",uz:"Kampirning ortidan bordim"},{ar:"إِلَى أَنْ وَصَلَتْ دَارَهَا",uz:"uyiga yetib borgunicha"},{ar:"يَا مَوْلَايَ.",uz:"hazratim."}],full_uz:"Kampirning ortidan uyiga yetib borgunicha bordim, hazratim.",note:"إِلَى أَنْ — ...gunicha; ish-harakatning tugash chegarasini bildiradi."},
{num:435,time:"00:32:49,680 --> 00:32:51,940",arabic:"وَدَارُهَا لَا تَدْخُلُهَا الْجُرَذُ.",segs:[{ar:"وَدَارُهَا",uz:"Uning uyiga esa"},{ar:"لَا تَدْخُلُهَا الْجُرَذُ.",uz:"kalamushlar ham kirmaydi."}],full_uz:"Uning uyiga kalamushlar ham kirmaydi.",note:"الْجُرَذُ — kalamushlar; birlik shakli جُرَذٌ. Bu gap uyda yegulik ham yo‘qligini anglatadi."},
{num:436,time:"00:32:51,940 --> 00:32:53,720",arabic:"إِنَّهَا فَقِيرَةٌ جِدًّا.",segs:null,full_uz:"U juda kambag‘al.",note:null},
{num:437,time:"00:32:53,720 --> 00:32:57,360",arabic:"وَأَخْبَرَنِي جِيرَانُهَا أَنْ لَا مُعِينَ لَهَا إِلَّا اللَّهُ.",segs:[{ar:"وَأَخْبَرَنِي جِيرَانُهَا",uz:"Qo‘shnilari menga aytishdi"},{ar:"أَنْ لَا مُعِينَ لَهَا",uz:"uning yordamchisi yo‘qligini"},{ar:"إِلَّا اللَّهُ.",uz:"Allohdan boshqa."}],full_uz:"Qo‘shnilari uning Allohdan boshqa yordamchisi yo‘qligini aytishdi.",note:"مُعِينٌ — yordam beruvchi; أَعَانَ fe’lidan."},
{num:438,time:"00:32:57,360 --> 00:33:00,720",arabic:"لَا إِلَهَ إِلَّا اللَّهُ.",segs:null,full_uz:"Allohdan boshqa iloh yo‘q.",note:null},
{num:439,time:"00:33:00,720 --> 00:33:06,740",arabic:"مِنْ صَبِيحَةِ الْغَدِ جِدْ لَهَا دَارًا تَلِيقُ بِهَا،",segs:[{ar:"مِنْ صَبِيحَةِ الْغَدِ",uz:"Ertaga tongdanoq"},{ar:"جِدْ لَهَا دَارًا",uz:"unga bir uy top"},{ar:"تَلِيقُ بِهَا،",uz:"unga munosib bo‘lgan,"}],full_uz:"Ertaga tongdanoq unga munosib bir uy top,",note:"جِدْ — وَجَدَ fe’lining buyruq shakli: top. لَاقَ بِـ — ...ga munosib bo‘lmoq."},
{num:440,time:"00:33:06,740 --> 00:33:11,360",arabic:"وَأْمُرْ لَهَا بِنَفَقَةٍ شَهْرِيَّةٍ مِنْ بَيْتِ مَالِ الْمُسْلِمِينَ.",segs:[{ar:"وَأْمُرْ لَهَا بِنَفَقَةٍ شَهْرِيَّةٍ",uz:"Unga oylik nafaqa ajratishni buyur"},{ar:"مِنْ بَيْتِ مَالِ الْمُسْلِمِينَ.",uz:"musulmonlar xazinasidan."}],full_uz:"Unga musulmonlar xazinasidan oylik nafaqa ajratishni buyur.",note:"نَفَقَةٌ — yashash xarajatlari uchun beriladigan mablag‘. بَيْتُ الْمَالِ — xazina."},
{num:441,time:"00:33:11,360 --> 00:33:17,259",arabic:"وَلْتُخْبِرْنَا الْعُيُونُ عَمَّنْ فِي مِثْلِ حَالِهَا لِيَكُونَ لَهُمْ مِثْلُ مَا لَهَا.",segs:[{ar:"وَلْتُخْبِرْنَا الْعُيُونُ",uz:"Xabarchilar bizga xabar bersinlar"},{ar:"عَمَّنْ فِي مِثْلِ حَالِهَا",uz:"unikidek ahvolda bo‘lganlar haqida"},{ar:"لِيَكُونَ لَهُمْ",uz:"ularga ham bo‘lishi uchun"},{ar:"مِثْلُ مَا لَهَا.",uz:"unga berilgandek yordam."}],full_uz:"Xabarchilar unikidek ahvolda bo‘lganlar haqida bizga xabar bersinlar, ularga ham xuddi shunday yordam berilsin.",note:"الْعُيُونُ — aslida ko‘zlar; bu yerda xabar yig‘uvchi kishilar. عَمَّنْ — عَنْ va مَنْ birikmasi."},
{num:442,time:"00:33:17,259 --> 00:33:18,900",arabic:"أَمْرُ مَوْلَايَ.",segs:null,full_uz:"Hazratimning buyrug‘i bosh ustiga.",note:"أَمْرُ مَوْلَايَ — buyruqni qabul qilishni bildiruvchi qisqa javob."},
{num:443,time:"00:33:18,900 --> 00:33:24,120",arabic:"يُنَفَّذُ مَا قُلْتُ مِنْ صَبِيحَةِ الْغَدِ، هَلْ فَهِمْتَ؟",segs:[{ar:"يُنَفَّذُ مَا قُلْتُ",uz:"Aytganlarim bajariladi"},{ar:"مِنْ صَبِيحَةِ الْغَدِ،",uz:"ertaga tongdanoq,"},{ar:"هَلْ فَهِمْتَ؟",uz:"tushundingmi?"}],full_uz:"Aytganlarim ertaga tongdanoq bajarilsin, tushundingmi?",note:"يُنَفَّذُ — majhul nisbat: bajariladi; bu yerda qat’iy buyruq ohangida aytilgan."},
{num:444,time:"00:33:24,120 --> 00:33:25,779",arabic:"سَمْعًا وَطَاعَةً يَا مَوْلَايَ.",segs:[{ar:"سَمْعًا وَطَاعَةً",uz:"Eshitdim va itoat qilaman"},{ar:"يَا مَوْلَايَ.",uz:"hazratim."}],full_uz:"Eshitdim va itoat qilaman, hazratim.",note:"سَمْعًا وَطَاعَةً — buyruqqa to‘liq bo‘ysunishni bildiruvchi turg‘un ibora."},
{num:445,time:"00:33:25,779 --> 00:33:35,180",arabic:"قُلْنَا إِنَّ الْأَصْلَ الْأَوَّلَ فِي مَذْهَبِنَا أَيُّهَا الْقَوْمُ هُوَ التَّوْحِيدُ.",segs:[{ar:"قُلْنَا",uz:"Aytgan edik"},{ar:"إِنَّ الْأَصْلَ الْأَوَّلَ فِي مَذْهَبِنَا",uz:"mazhabimizdagi birinchi asos"},{ar:"أَيُّهَا الْقَوْمُ",uz:"ey jamoat"},{ar:"هُوَ التَّوْحِيدُ.",uz:"tavhid ekanini."}],full_uz:"Ey jamoat, mazhabimizdagi birinchi asos tavhid ekanini aytgan edik.",note:"أَصْلٌ — asos, tamoyil. التَّوْحِيدُ — Allohni yagona deb bilish."},
{num:446,time:"00:33:35,180 --> 00:33:41,319",arabic:"وَنَعْنِي بِهِ إِثْبَاتَ وَحْدَانِيَّةِ اللَّهِ وَنَفْيَ الْمِثْلِ عَنْهُ.",segs:[{ar:"وَنَعْنِي بِهِ",uz:"Bu bilan nazarda tutamiz"},{ar:"إِثْبَاتَ وَحْدَانِيَّةِ اللَّهِ",uz:"Allohning yagonaligini tasdiqlashni"},{ar:"وَنَفْيَ الْمِثْلِ عَنْهُ.",uz:"va Uning o‘xshashi borligini inkor etishni."}],full_uz:"Bu bilan Allohning yagonaligini tasdiqlash va Uning o‘xshashi borligini inkor etishni nazarda tutamiz.",note:"نَعْنِي بِهِ — bu bilan ...ni nazarda tutamiz. إِثْبَاتٌ — tasdiqlash; نَفْيٌ — inkor etish."},
{num:447,time:"00:33:41,319 --> 00:33:43,359",arabic:"وَالْأَصْلُ الثَّانِي هُوَ الْعَدْلُ.",segs:null,full_uz:"Ikkinchi asos esa adolatdir.",note:"الْعَدْلُ — adolat; عَادِلٌ — adolatli."},
{num:448,time:"00:33:43,359 --> 00:33:50,579",arabic:"وَنَعْنِي بِهِ قِيَاسَ أَحْكَامِ اللَّهِ عَلَى مَا يَقْتَضِيهِ الْعَقْلُ وَالْحِكْمَةُ.",segs:[{ar:"وَنَعْنِي بِهِ",uz:"Bu bilan nazarda tutamiz"},{ar:"قِيَاسَ أَحْكَامِ اللَّهِ",uz:"Allohning hukmlarini o‘lchashni"},{ar:"عَلَى مَا يَقْتَضِيهِ",uz:"taqozo qiladigan narsaga ko‘ra"},{ar:"الْعَقْلُ وَالْحِكْمَةُ.",uz:"aql va hikmat."}],full_uz:"Bu bilan Allohning hukmlarini aql va hikmat taqozo qiladigan narsaga ko‘ra o‘lchashni nazarda tutamiz.",note:"اقْتَضَى — talab qilmoq, taqozo etmoq; يَقْتَضِيهِ — uni taqozo qiladi."},
{num:449,time:"00:33:50,579 --> 00:33:55,099",arabic:"فَالْعَقْلُ مُسْتَقِلٌّ بِالتَّحْسِينِ وَالتَّقْبِيحِ.",segs:[{ar:"فَالْعَقْلُ مُسْتَقِلٌّ",uz:"Aql mustaqildir"},{ar:"بِالتَّحْسِينِ وَالتَّقْبِيحِ.",uz:"yaxshi va yomon deb baholashda."}],full_uz:"Aql yaxshi va yomon deb baholashda mustaqildir.",note:"التَّحْسِينُ — yaxshi deb baholash; التَّقْبِيحُ — yomon deb baholash."},
{num:450,time:"00:33:55,099 --> 00:33:58,959",arabic:"فَمَا حَسَّنَهُ الْعَقْلُ كَانَ حَسَنًا،",segs:[{ar:"فَمَا حَسَّنَهُ الْعَقْلُ",uz:"Aql nimani yaxshi deb bilsa"},{ar:"كَانَ حَسَنًا،",uz:"o‘sha yaxshi bo‘ladi,"}],full_uz:"Aql nimani yaxshi deb bilsa, o‘sha yaxshi bo‘ladi,",note:"حَسَّنَهُ — bu yerda uni yaxshi deb baholadi."},
{num:451,time:"00:33:58,959 --> 00:34:02,099",arabic:"وَمَا قَبَّحَهُ كَانَ قَبِيحًا.",segs:[{ar:"وَمَا قَبَّحَهُ",uz:"nimani yomon deb bilsa"},{ar:"كَانَ قَبِيحًا.",uz:"o‘sha yomon bo‘ladi."}],full_uz:"Nimani yomon deb bilsa, o‘sha yomon bo‘ladi.",note:"قَبَّحَهُ fe’lining yashirin egasi oldingi gapdagi الْعَقْلُ — aql."},
{num:452,time:"00:34:02,759 --> 00:34:06,379",arabic:"مَاذَا حَدَثَ مَعَ زَمِيلِكَ فِي حَلْقَةِ الدَّرْسِ؟",segs:[{ar:"مَاذَا حَدَثَ مَعَ زَمِيلِكَ",uz:"Sheriging bilan nima bo‘ldi"},{ar:"فِي حَلْقَةِ الدَّرْسِ؟",uz:"dars davrasidagi?"}],full_uz:"Dars davrasidagi sheriging bilan nima bo‘ldi?",note:"حَلْقَةُ الدَّرْسِ — ustoz atrofida yig‘ilib dars tinglanadigan davra."},
{num:453,time:"00:34:09,319 --> 00:34:11,099",arabic:"إِنَّهُ أَحْمَقُ لَيْسَ إِلَّا.",segs:[{ar:"إِنَّهُ أَحْمَقُ",uz:"U ahmoq"},{ar:"لَيْسَ إِلَّا.",uz:"xolos."}],full_uz:"U ahmoq, xolos.",note:"لَيْسَ إِلَّا — boshqa narsa emas, xolos."},
{num:454,time:"00:34:11,099 --> 00:34:11,759",arabic:"إِذَنْ فَشِلْتَ مَعَهُ.",segs:null,full_uz:"Demak, u bilan muvaffaqiyatga erisha olmading.",note:"فَشِلَ — muvaffaqiyatsizlikka uchramoq."},
{num:455,time:"00:34:11,759 --> 00:34:14,339",arabic:"فَقَدْ ذَهَبَ كَلَامِي مَعَهُ سُدًى.",segs:[{ar:"فَقَدْ ذَهَبَ كَلَامِي مَعَهُ",uz:"Unga aytgan gaplarim ketdi"},{ar:"سُدًى.",uz:"bekorga."}],full_uz:"Unga aytgan gaplarim bekor ketdi.",note:"ذَهَبَ سُدًى — behuda ketmoq, natijasiz qolmoq."},
{num:456,time:"00:34:14,339 --> 00:34:16,519",arabic:"إِنَّهُ لَا يَسْتَحِقُّ الْعَنَاءَ.",segs:null,full_uz:"U ovora bo‘lishga arzimaydi.",note:"الْعَنَاءُ — mashaqqat, ovora bo‘lish."},
{num:457,time:"00:34:16,519 --> 00:34:18,039",arabic:"لَا طَائِلَ مِنْ وَرَائِهِ.",segs:null,full_uz:"Undan hech qanday naf yo‘q.",note:"لَا طَائِلَ مِنْ وَرَائِهِ — undan foyda yoki natija chiqmaydi."},
{num:458,time:"00:34:18,639 --> 00:34:20,460",arabic:"لَا يَا بَدْرُ.",segs:null,full_uz:"Yo‘q, Badr.",note:null},
{num:459,time:"00:34:20,460 --> 00:34:23,079",arabic:"لَا أُحِبُّ أَنْ أَسْمَعَ مِثْلَ هَذَا الْكَلَامِ مِنْكَ.",segs:[{ar:"لَا أُحِبُّ أَنْ أَسْمَعَ",uz:"Eshitishni istamayman"},{ar:"مِثْلَ هَذَا الْكَلَامِ مِنْكَ.",uz:"sendan bunday gaplarni."}],full_uz:"Sendan bunday gaplarni eshitishni istamayman.",note:null},
{num:460,time:"00:34:23,079 --> 00:34:25,059",arabic:"عَلَيْكَ أَلَّا تَسْتَهِينَ بِشَخْصٍ مَهْمَا كَانَ.",segs:[{ar:"عَلَيْكَ أَلَّا تَسْتَهِينَ بِشَخْصٍ",uz:"Biror kishini mensimasliging kerak emas"},{ar:"مَهْمَا كَانَ.",uz:"u kim bo‘lishidan qat’i nazar."}],full_uz:"Kim bo‘lishidan qat’i nazar, hech kimni mensimay qo‘ymasliging kerak.",note:"اسْتَهَانَ بِـ — mensimaslik, past nazar bilan qarash. مَهْمَا كَانَ — kim yoki qanday bo‘lishidan qat’i nazar."},
{num:461,time:"00:34:25,059 --> 00:34:29,340",arabic:"إِنْ بَقِينَا نَتَرَفَّعُ عَنِ النَّاسِ لَبَقِيَ أَكْثَرُهُمْ فِي الضَّلَالَةِ.",segs:[{ar:"إِنْ بَقِينَا نَتَرَفَّعُ عَنِ النَّاسِ",uz:"Agar odamlardan o‘zimizni ustun tutaversak"},{ar:"لَبَقِيَ أَكْثَرُهُمْ",uz:"ularning ko‘pchiligi qolib ketadi"},{ar:"فِي الضَّلَالَةِ.",uz:"adashishda."}],full_uz:"Agar odamlardan o‘zimizni ustun tutaversak, ularning ko‘pchiligi adashishda qolib ketadi.",note:"تَرَفَّعَ عَنْ — o‘zini yuqori tutib chetlashmoq; bu yerda odamlarga kibr bilan munosabat qilish."},
{num:462,time:"00:34:29,340 --> 00:34:32,460",arabic:"إِنَّ الْأَمِيرَ عَبْدَ اللَّهِ الْمَأْمُونَ يَا مَوْلَايَ،",segs:[{ar:"إِنَّ الْأَمِيرَ عَبْدَ اللَّهِ الْمَأْمُونَ",uz:"Amir Abdulloh Ma’mun"},{ar:"يَا مَوْلَايَ،",uz:"hazratim,"}],full_uz:"Hazratim, amir Abdulloh Ma’mun",note:"إِنَّ ning xabari keyingi parchada keladi."},
{num:463,time:"00:34:32,460 --> 00:34:35,719",arabic:"يَتَفَصَّدُ ذَكَاءً وَنَجَابَةً.",segs:[{ar:"يَتَفَصَّدُ",uz:"to‘lib-toshib turibdi"},{ar:"ذَكَاءً وَنَجَابَةً.",uz:"zakovat va iste’dodga."}],full_uz:"Zakovat va iste’dodga to‘lib-toshib turibdi.",note:"يَتَفَصَّدُ — aslida oqib chiqmoq; bu yerda bir sifatning juda kuchli namoyon bo‘lishini bildiradi."},
{num:464,time:"00:34:35,719 --> 00:34:39,380",arabic:"وَلَا أَكُونُ مُبَالِغًا إِنْ قُلْتُ،",segs:[{ar:"وَلَا أَكُونُ مُبَالِغًا",uz:"Mubolag‘a qilgan bo‘lmayman"},{ar:"إِنْ قُلْتُ،",uz:"agar aytsam,"}],full_uz:"Shunday desam, mubolag‘a qilgan bo‘lmayman:",note:"مُبَالِغٌ — bo‘rttirib gapiruvchi; بَالَغَ fe’lidan."},
{num:465,time:"00:34:39,380 --> 00:34:42,900",arabic:"إِنَّنِي لَمْ أَرَ شَابًّا فِي عُمْرِهِ،",segs:[{ar:"إِنَّنِي لَمْ أَرَ شَابًّا",uz:"Men biror yigitni ko‘rmaganman"},{ar:"فِي عُمْرِهِ،",uz:"uning yoshida,"}],full_uz:"Men uning yoshidagi biror yigitni ko‘rmaganman,",note:"لَمْ أَرَ — ko‘rmadim; أَرَى fe’lining oxirgi ا harfi jazmda tushgan."},
{num:466,time:"00:34:42,900 --> 00:34:45,519",arabic:"يُفَكِّرُ كَمَا يُفَكِّرُ الْمُكْتَهِلُونَ.",segs:[{ar:"يُفَكِّرُ",uz:"fikrlaydigan"},{ar:"كَمَا يُفَكِّرُ الْمُكْتَهِلُونَ.",uz:"yetuk yoshdagi kishilar fikrlaganidek."}],full_uz:"Yetuk yoshdagi kishilardek fikrlaydigan.",note:"الْمُكْتَهِلُونَ — yetuk yoshga kirgan kishilar; yoshlikdan o‘tgan, tajribali odamlar."},
{num:467,time:"00:34:45,519 --> 00:34:49,259",arabic:"إِنَّهُ نَادِرَةٌ مِنْ نَوَادِرِ هَذَا الزَّمَانِ،",segs:[{ar:"إِنَّهُ نَادِرَةٌ",uz:"U noyob bir inson"},{ar:"مِنْ نَوَادِرِ هَذَا الزَّمَانِ،",uz:"bu zamonning noyob insonlaridan,"}],full_uz:"U bu zamonning noyob insonlaridan,",note:"نَادِرَةٌ — noyob narsa yoki inson; ko‘pligi نَوَادِرُ."},
{num:468,time:"00:34:49,259 --> 00:34:51,619",arabic:"وَكُلِّ زَمَانٍ يَا مَوْلَايَ.",segs:[{ar:"وَكُلِّ زَمَانٍ",uz:"va barcha zamonlarning"},{ar:"يَا مَوْلَايَ.",uz:"hazratim."}],full_uz:"Barcha zamonlarning ham, hazratim.",note:"Bu parcha oldingi gapdagi هَذَا الزَّمَانِ birikmasiga bog‘langan."},
{num:469,time:"00:34:51,619 --> 00:34:52,900",arabic:"صَدَقْتَ.",segs:null,full_uz:"To‘g‘ri aytding.",note:"صَدَقْتَ — rost aytding; fikrga qo‘shilishni ham bildiradi."},
{num:470,time:"00:34:52,900 --> 00:34:55,360",arabic:"صَدَقْتَ يَا ابْنَ سَهْلٍ.",segs:[{ar:"صَدَقْتَ",uz:"To‘g‘ri aytding"},{ar:"يَا ابْنَ سَهْلٍ.",uz:"Ibn Sahl."}],full_uz:"To‘g‘ri aytding, Ibn Sahl.",note:null},
{num:471,time:"00:34:55,360 --> 00:34:59,820",arabic:"فَإِنَّ فِي هَذَا الْفَتَى حَزْمَ جَدِّي الْمَنْصُورِ.",segs:[{ar:"فَإِنَّ فِي هَذَا الْفَتَى",uz:"Chunki bu yigitda bor"},{ar:"حَزْمَ جَدِّي الْمَنْصُورِ.",uz:"bobom Mansurning qat’iyati."}],full_uz:"Chunki bu yigitda bobom Mansurning qat’iyati bor.",note:"حَزْمٌ — qat’iyat, ishni puxta o‘ylab qat’iy qaror qilish."},
{num:472,time:"00:34:59,820 --> 00:35:02,639",arabic:"وَتُقَى أَبِي الْمَهْدِيِّ،",segs:null,full_uz:"Otam Mahdiyning taqvosi ham,",note:"تُقًى — taqvo, Allohdan qo‘rqib yomonlikdan saqlanish. Oldingi gapdagi sifatlar sanog‘i davom etmoqda."},
{num:473,time:"00:35:02,639 --> 00:35:05,500",arabic:"وَعِزَّةَ نَفْسِ أَخِي الْهَادِي.",segs:[{ar:"وَعِزَّةَ نَفْسِ",uz:"va or-nomusi"},{ar:"أَخِي الْهَادِي.",uz:"akam Hodiyning."}],full_uz:"Akam Hodiyning or-nomusi ham bor.",note:"عِزَّةُ النَّفْسِ — o‘z qadrini bilish, or-nomusini saqlash."},
{num:474,time:"00:35:05,500 --> 00:35:10,400",arabic:"وَوَاللَّهِ لَوْ شِئْتُ أَنْ أَقُولَ الرَّابِعَةَ مِنِّي لَقُلْتُ.",segs:[{ar:"وَوَاللَّهِ",uz:"Allohga qasamki,"},{ar:"لَوْ شِئْتُ أَنْ أَقُولَ",uz:"agar aytishni istasam"},{ar:"الرَّابِعَةَ مِنِّي",uz:"to‘rtinchi sifat mendan ekanini"},{ar:"لَقُلْتُ.",uz:"aytgan bo‘lardim."}],full_uz:"Allohga qasamki, to‘rtinchi sifat mendan ekanini aytishni istasam, aytgan bo‘lardim.",note:"لَوْ شِئْتُ ... لَقُلْتُ — istaganimda ...degan bo‘lardim. مِنِّي — mendan."},
{num:475,time:"00:35:10,400 --> 00:35:16,380",arabic:"فَكَيْفَ بِأَبِي مُوسَى الْأَمِينِ وَلِيِّ عَهْدِكُمْ يَا أَمِيرَ الْمُؤْمِنِينَ؟",segs:[{ar:"فَكَيْفَ بِأَبِي مُوسَى الْأَمِينِ",uz:"Abu Muso Amin haqida-chi"},{ar:"وَلِيِّ عَهْدِكُمْ",uz:"valiahdingiz"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ؟",uz:"ey mo‘minlar amiri?"}],full_uz:"Valiahdingiz Abu Muso Amin haqida nima deysiz, mo‘minlar amiri?",note:"وَلِيُّ الْعَهْدِ — valiahd, hukmdorlikka voris etib belgilangan kishi."},
{num:476,time:"00:35:16,380 --> 00:35:19,240",arabic:"إِنَّ الْأَمِينَ لَا يَقِلُّ شَأْنًا عَنْ أَخِيهِ.",segs:[{ar:"إِنَّ الْأَمِينَ لَا يَقِلُّ شَأْنًا",uz:"Aminning darajasi kam emas"},{ar:"عَنْ أَخِيهِ.",uz:"birodaridan."}],full_uz:"Aminning darajasi birodarinikidan kam emas.",note:"لَا يَقِلُّ شَأْنًا عَنْ — daraja yoki qadr jihatidan ...dan kam emas."},
{num:477,time:"00:35:19,239 --> 00:35:23,099",arabic:"وَمَنْ مِثْلُ أَبِي مُوسَى الْأَمِينِ فِي بَذْلِهِ وَجُودِهِ؟",segs:[{ar:"وَمَنْ مِثْلُ أَبِي مُوسَى الْأَمِينِ",uz:"Kim Abu Muso Aminga teng"},{ar:"فِي بَذْلِهِ وَجُودِهِ؟",uz:"ehson va saxovatda?"}],full_uz:"Ehson va saxovatda kim Abu Muso Aminga teng?",note:"بَذْلٌ — molini yoki imkoniyatini boshqalarga sarflash; جُودٌ — saxovat."},
{num:478,time:"00:35:23,099 --> 00:35:26,439",arabic:"إِنَّهُ يَقْتَفِي خُطَى أَجْدَادِهِ الْهَاشِمِيِّينَ.",segs:[{ar:"إِنَّهُ يَقْتَفِي خُطَى",uz:"U izidan bormoqda"},{ar:"أَجْدَادِهِ الْهَاشِمِيِّينَ.",uz:"hoshimiy ajdodlarining."}],full_uz:"U hoshimiy ajdodlarining izidan bormoqda.",note:"اقْتَفَى خُطَى فُلَانٍ — birovning izidan bormoq, undan o‘rnak olmoq."},
{num:479,time:"00:35:26,439 --> 00:35:27,279",arabic:"أَحْسَنْتَ.",segs:null,full_uz:"Barakalla.",note:"أَحْسَنْتَ — yaxshi qilding; maqtash va ma’qullash uchun ishlatiladi."},
{num:480,time:"00:35:27,279 --> 00:35:30,379",arabic:"أَحْسَنْتَ الْقَوْلَ يَا ابْنَ الرَّبِيعِ.",segs:[{ar:"أَحْسَنْتَ الْقَوْلَ",uz:"Yaxshi gap aytding"},{ar:"يَا ابْنَ الرَّبِيعِ.",uz:"Ibn Rabi’."}],full_uz:"Yaxshi gap aytding, Ibn Rabi’.",note:null},
{num:481,time:"00:35:30,379 --> 00:35:33,699",arabic:"قُلْ لِي يَا ابْنَ سَهْلٍ،",segs:[{ar:"قُلْ لِي",uz:"Menga ayt"},{ar:"يَا ابْنَ سَهْلٍ،",uz:"Ibn Sahl,"}],full_uz:"Menga ayt, Ibn Sahl,",note:null},
{num:482,time:"00:35:33,699 --> 00:35:37,519",arabic:"أَيْنَ جَعْفَرٌ؟ لَمْ أَرَهُ فِي مَجْلِسِي مُنْذُ يَوْمَيْنِ.",segs:[{ar:"أَيْنَ جَعْفَرٌ؟",uz:"Ja’far qayerda?"},{ar:"لَمْ أَرَهُ فِي مَجْلِسِي",uz:"Uni majlisimda ko‘rmadim"},{ar:"مُنْذُ يَوْمَيْنِ.",uz:"ikki kundan beri."}],full_uz:"Ja’far qayerda? Ikki kundan beri uni majlisimda ko‘rmadim.",note:"مُنْذُ يَوْمَيْنِ — ikki kundan beri. لَمْ أَرَهُ — uni ko‘rmadim."},
{num:483,time:"00:35:37,519 --> 00:35:42,799",arabic:"إِنَّ أَبَا الْفَضْلِ لَا يَشْغَلُهُ عَنْ أَمِيرِ الْمُؤْمِنِينَ شَاغِلٌ يَا مَوْلَايَ.",segs:[{ar:"إِنَّ أَبَا الْفَضْلِ",uz:"Abu Fazlni"},{ar:"لَا يَشْغَلُهُ عَنْ أَمِيرِ الْمُؤْمِنِينَ شَاغِلٌ",uz:"hech bir ish mo‘minlar amiridan chalg‘ita olmaydi"},{ar:"يَا مَوْلَايَ.",uz:"hazratim."}],full_uz:"Abu Fazlni hech bir ish mo‘minlar amiridan chalg‘ita olmaydi, hazratim.",note:"شَغَلَهُ عَنْ — uni ...dan chalg‘itdi. شَاغِلٌ — mashg‘ul qiluvchi ish."},
{num:484,time:"00:35:42,799 --> 00:35:46,959",arabic:"وَلَكِنْ أَحْسَبُ أَنَّ السَّهَرَ عَلَى شُؤُونِ دَوْلَةِ أَمِيرِ الْمُؤْمِنِينَ،",segs:[{ar:"وَلَكِنْ أَحْسَبُ أَنَّ",uz:"Lekin o‘ylaymanki,"},{ar:"السَّهَرَ عَلَى شُؤُونِ",uz:"ishlari bilan tunlari bedor bo‘lish"},{ar:"دَوْلَةِ أَمِيرِ الْمُؤْمِنِينَ،",uz:"mo‘minlar amirining davlati,"}],full_uz:"Lekin, o‘ylaymanki, mo‘minlar amirining davlat ishlari bilan tunlari bedor bo‘lishi",note:"السَّهَرُ عَلَى شُؤُونِ... — ...ishlariga g‘amxo‘rlik qilib, ular bilan bedor bo‘lish."},
{num:485,time:"00:35:46,960 --> 00:35:50,740",arabic:"عَاقَهُ عَنْ حُضُورِ مَجْلِسِكَ الْيَوْمَ يَا مَوْلَايَ الرَّشِيدُ.",segs:[{ar:"عَاقَهُ عَنْ حُضُورِ مَجْلِسِكَ",uz:"uni majlisingizda qatnashishdan to‘sdi"},{ar:"الْيَوْمَ",uz:"bugun"},{ar:"يَا مَوْلَايَ الرَّشِيدُ.",uz:"hazratim Rashid."}],full_uz:"Uni bugun majlisingizda qatnashishdan to‘sdi, hazratim Rashid.",note:"عَاقَهُ عَنْ — unga biror ishni qilishga to‘sqinlik qildi."},
{num:486,time:"00:35:50,740 --> 00:35:55,500",arabic:"أَوْ أَنَّهُ مَشْغُولٌ عَنْكَ يَا مَوْلَايَ بِقَصْرِهِ الْجَدِيدِ،",segs:[{ar:"أَوْ أَنَّهُ مَشْغُولٌ عَنْكَ",uz:"Yoki u sizdan chalg‘ib, banddir"},{ar:"يَا مَوْلَايَ",uz:"hazratim"},{ar:"بِقَصْرِهِ الْجَدِيدِ،",uz:"yangi saroyi bilan,"}],full_uz:"Yoki u yangi saroyi bilan band bo‘lib, sizdan chalg‘igandir, hazratim,",note:"مَشْغُولٌ بِـ — ...bilan band; مَشْغُولٌ عَنْ — ...ga vaqt ajrata olmaydigan."},
{num:487,time:"00:35:55,500 --> 00:36:00,519",arabic:"الَّذِي أَنْفَقَ عَلَيْهِ عِشْرِينَ أَلْفَ أَلْفِ دِرْهَمٍ كَمَا يُقَالُ.",segs:[{ar:"الَّذِي أَنْفَقَ عَلَيْهِ",uz:"unga sarflagan"},{ar:"عِشْرِينَ أَلْفَ أَلْفِ دِرْهَمٍ",uz:"yigirma million dirham"},{ar:"كَمَا يُقَالُ.",uz:"aytilishicha."}],full_uz:"Aytilishicha, u bu saroyga yigirma million dirham sarflagan.",note:"أَلْفُ أَلْفٍ — ming marta ming, ya’ni million. يُقَالُ — aytiladi."},
{num:488,time:"00:36:00,519 --> 00:36:05,300",arabic:"أَرَى أَنَّ هَذَا الرَّقْمَ مُبَالَغٌ فِيهِ يَا أَبَا الْعَبَّاسِ.",segs:[{ar:"أَرَى أَنَّ هَذَا الرَّقْمَ",uz:"Menimcha, bu raqam"},{ar:"مُبَالَغٌ فِيهِ",uz:"bo‘rttirilgan"},{ar:"يَا أَبَا الْعَبَّاسِ.",uz:"Abu Abbos."}],full_uz:"Menimcha, bu raqam bo‘rttirilgan, Abu Abbos.",note:"مُبَالَغٌ فِيهِ — bo‘rttirilgan, haddan ortiq oshirib aytilgan."},
{num:489,time:"00:36:05,300 --> 00:36:08,300",arabic:"بَلْ إِنَّهُ أَكْثَرُ مِمَّا تَحْسَبُ يَا ابْنَ سَهْلٍ.",segs:[{ar:"بَلْ إِنَّهُ أَكْثَرُ",uz:"Aksincha, u ko‘proq"},{ar:"مِمَّا تَحْسَبُ",uz:"siz o‘ylaganingizdan"},{ar:"يَا ابْنَ سَهْلٍ.",uz:"Ibn Sahl."}],full_uz:"Aksincha, u siz o‘ylaganingizdan ko‘proq, Ibn Sahl.",note:"مِمَّا — مِنْ va مَا birikmasi; bu yerda ...ganingizdan ma’nosini beradi."},
{num:490,time:"00:36:08,300 --> 00:36:12,480",arabic:"إِنَّ جَعْفَرًا لَدَيْهِ مِنَ الدُّورِ وَالْقُصُورِ الْكَثِيرُ،",segs:[{ar:"إِنَّ جَعْفَرًا لَدَيْهِ",uz:"Ja’farning bor"},{ar:"مِنَ الدُّورِ وَالْقُصُورِ الْكَثِيرُ،",uz:"ko‘plab uy va saroylari,"}],full_uz:"Ja’farning ko‘plab uy va saroylari bor,",note:"دُورٌ — دَارٌ so‘zining ko‘pligi; قُصُورٌ — قَصْرٌ so‘zining ko‘pligi."},
{num:491,time:"00:36:12,480 --> 00:36:15,300",arabic:"فَمَا حَاجَتُهُ لِبِنَاءِ قَصْرٍ جَدِيدٍ؟",segs:[{ar:"فَمَا حَاجَتُهُ",uz:"Unda unga nima zarurat bor"},{ar:"لِبِنَاءِ قَصْرٍ جَدِيدٍ؟",uz:"yangi saroy qurishga?"}],full_uz:"Unda unga yangi saroy qurishning nima zarurati bor?",note:"مَا حَاجَتُهُ لِـ؟ — unga ...ning nima keragi bor?"},
{num:492,time:"00:36:15,300 --> 00:36:18,060",arabic:"دَعْكَ مِنْ هَذَا الْحَدِيثِ يَا عِيسَى.",segs:[{ar:"دَعْكَ مِنْ هَذَا الْحَدِيثِ",uz:"Bu gapni qo‘y"},{ar:"يَا عِيسَى.",uz:"Iso."}],full_uz:"Bu gapni qo‘y, Iso.",note:"دَعْكَ مِنْ... — ...ni qo‘y, ...bilan shug‘ullanma mazmunidagi ibora."},
{num:493,time:"00:36:18,060 --> 00:36:20,560",arabic:"قُلْ لِي يَا ابْنَ الرَّبِيعِ،",segs:[{ar:"قُلْ لِي",uz:"Menga ayt"},{ar:"يَا ابْنَ الرَّبِيعِ،",uz:"Ibn Rabi’,"}],full_uz:"Menga ayt, Ibn Rabi’,",note:null},
{num:494,time:"00:36:20,560 --> 00:36:22,880",arabic:"مَا أَخْبَارُ ضَيْفِكَ؟",segs:null,full_uz:"Mehmoningdan qanday yangiliklar bor?",note:"مَا أَخْبَارُ...؟ — ...ning ahvoli qanday, undan qanday yangiliklar bor?"},
{num:495,time:"00:36:22,880 --> 00:36:25,780",arabic:"مَوْلَايَ الرَّشِيدُ يَقْصِدُ الشَّافِعِيَّ؟",segs:[{ar:"مَوْلَايَ الرَّشِيدُ",uz:"Hazratim Rashid"},{ar:"يَقْصِدُ الشَّافِعِيَّ؟",uz:"Shofe’iyni nazarda tutyaptilarmi?"}],full_uz:"Hazratim Rashid Shofe’iyni nazarda tutyaptilarmi?",note:"قَصَدَ — bu yerda nazarda tutmoq."},
{num:496,time:"00:36:25,780 --> 00:36:29,539",arabic:"لَقَدِ اسْتَأْثَرَ بِهِ قَاضِي قُضَاتِكَ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"لَقَدِ اسْتَأْثَرَ بِهِ قَاضِي قُضَاتِكَ",uz:"Qozikaloningiz uni butunlay o‘ziga band qilib oldi"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ.",uz:"ey mo‘minlar amiri."}],full_uz:"Qozikaloningiz uni butunlay o‘ziga band qilib oldi, mo‘minlar amiri.",note:"اسْتَأْثَرَ بِـ — biror narsani boshqalardan o‘ziga ajratib olmoq. قَاضِي الْقُضَاةِ — qozikalon."},
{num:497,time:"00:36:29,539 --> 00:36:33,560",arabic:"إِذَنْ فَقَدْ أَسْدَيْنَا مَعْرُوفًا لِابْنِ الْحَسَنِ،",segs:[{ar:"إِذَنْ فَقَدْ أَسْدَيْنَا مَعْرُوفًا",uz:"Demak, biz yaxshilik qilibmiz"},{ar:"لِابْنِ الْحَسَنِ،",uz:"Ibn Hasanga,"}],full_uz:"Demak, biz Ibn Hasanga yaxshilik qilibmiz,",note:"أَسْدَى مَعْرُوفًا — yaxshilik qilmoq."},
{num:498,time:"00:36:33,560 --> 00:36:36,900",arabic:"إِذْ أَبْقَيْنَا عَلَى مُحَمَّدِ بْنِ إِدْرِيسَ الشَّافِعِيِّ فِي بَغْدَادَ،",segs:[{ar:"إِذْ أَبْقَيْنَا عَلَى مُحَمَّدِ بْنِ إِدْرِيسَ الشَّافِعِيِّ",uz:"Muhammad ibn Idris Shofe’iyni qoldirganimiz bilan"},{ar:"فِي بَغْدَادَ،",uz:"Bag‘dodda,"}],full_uz:"Muhammad ibn Idris Shofe’iyni Bag‘dodda qoldirganimiz bilan,",note:"إِذْ — bu yerda oldingi fikrning sababini izohlaydi."},
{num:499,time:"00:36:36,900 --> 00:36:37,840",arabic:"أَلَيْسَ كَذَلِكَ؟",segs:null,full_uz:"Shunday emasmi?",note:null},
{num:500,time:"00:37:15,300 --> 00:37:18,300",arabic:"تَتَكَلَّمِينَ عَنِ الدَّمَامَةِ، أَيَّتُهَا الْعَجُوزُ الشَّمْطَاءُ!",segs:[{ar:"تَتَكَلَّمِينَ عَنِ الدَّمَامَةِ،",uz:"Xunuklik haqida gapiryapsan"},{ar:"أَيَّتُهَا الْعَجُوزُ الشَّمْطَاءُ!",uz:"ey sochi oqargan kampir!"}],full_uz:"Xunuklik haqida gapiryapsanmi, ey sochi oqargan kampir!",note:"دَمَامَةٌ — xunuklik. شَمْطَاءُ — sochiga oq oralagan ayol."},
{num:501,time:"00:37:18,300 --> 00:37:20,300",arabic:"اغْرُبِي عَنْ وَجْهِي وَإِلَّا ضَرَبْتُكِ!",segs:[{ar:"اغْرُبِي عَنْ وَجْهِي",uz:"Ko‘zimdan yo‘qol"},{ar:"وَإِلَّا ضَرَبْتُكِ!",uz:"aks holda seni uraman!"}],full_uz:"Ko‘zimdan yo‘qol, aks holda seni uraman!",note:"اغْرُبِي — ayolga qaratilgan buyruq. وَإِلَّا — aks holda."},
{num:502,time:"00:37:20,300 --> 00:37:22,300",arabic:"لَنْ أَغْرُبَ! لَنْ أَغْرُبَ!",segs:null,full_uz:"Ketmayman! Ketmayman!",note:"لَنْ أَغْرُبَ — ketmayman; لَنْ kelajakdagi ishni qat’iy inkor qiladi."},
{num:503,time:"00:37:22,300 --> 00:37:23,300",arabic:"حَسَنًا، سَأَضْرِبُكِ!",segs:[{ar:"حَسَنًا،",uz:"Yaxshi,"},{ar:"سَأَضْرِبُكِ!",uz:"seni uraman!"}],full_uz:"Yaxshi, seni uraman!",note:null},
{num:504,time:"00:37:23,300 --> 00:37:24,300",arabic:"هَيَّا، هَيَّا!",segs:null,full_uz:"Qani, qani!",note:"هَيَّا — harakatga undash yoki shoshiltirish uchun ishlatiladi."},
{num:505,time:"00:37:38,300 --> 00:37:39,300",arabic:"أُمِّي، حَسَنًا!",segs:[{ar:"أُمِّي،",uz:"Onajon,"},{ar:"حَسَنًا!",uz:"bo‘ldi!"}],full_uz:"Onajon, bo‘ldi!",note:null},
{num:506,time:"00:37:39,300 --> 00:37:40,300",arabic:"تَعَالَيْ.",segs:null,full_uz:"Keling.",note:"تَعَالَيْ — ayol kishiga qaratilgan kel buyrug‘i; erkakka تَعَالَ deyiladi."},
{num:507,time:"00:37:47,300 --> 00:37:51,300",arabic:"خُذِي طَعَامَكِ، أُرِيدُكِ أَنْ تَأْكُلِيهِ كُلَّهُ.",segs:[{ar:"خُذِي طَعَامَكِ،",uz:"Ovqatingni ol,"},{ar:"أُرِيدُكِ أَنْ تَأْكُلِيهِ",uz:"uni yeyishingni istayman"},{ar:"كُلَّهُ.",uz:"hammasini."}],full_uz:"Ovqatingni ol, hammasini yeyishingni istayman.",note:"تَأْكُلِيهِ — sen uni yeyishing; أَنْ dan keyin تَأْكُلِينَ shaklidagi ن tushgan."},
{num:508,time:"00:37:52,300 --> 00:37:55,300",arabic:"أُرِيدُكِ أَنْ تَسْتَعِيدِي رَوْنَقَكِ وَعَافِيَتَكِ.",segs:[{ar:"أُرِيدُكِ أَنْ تَسْتَعِيدِي",uz:"Qayta tiklashingni istayman"},{ar:"رَوْنَقَكِ وَعَافِيَتَكِ.",uz:"tarovating va sog‘lig‘ingni."}],full_uz:"Tarovating va sog‘lig‘ingni qayta tiklashingni istayman.",note:"اسْتَعَادَ — qayta tiklamoq, qaytarib olmoq. رَوْنَقٌ — tarovat, ko‘rk."},
{num:509,time:"00:37:58,300 --> 00:38:02,300",arabic:"لَا أُرِيدُ لِلرَّجُلِ أَنْ يَأْتِيَ وَيَرَاكِ وَأَنْتِ بِهَذَا الشُّحُوبِ.",segs:[{ar:"لَا أُرِيدُ لِلرَّجُلِ أَنْ يَأْتِيَ",uz:"U kishining kelishini istamayman"},{ar:"وَيَرَاكِ",uz:"va seni ko‘rishini"},{ar:"وَأَنْتِ بِهَذَا الشُّحُوبِ.",uz:"shunday rangpar holingda."}],full_uz:"U kishi kelib, seni shunday rangpar holda ko‘rishini istamayman.",note:"شُحُوبٌ — rangparlik. وَأَنْتِ... hol jumlasini boshlaydi."},
{num:510,time:"00:38:03,300 --> 00:38:04,300",arabic:"كُلِي، كُلِي.",segs:null,full_uz:"Ye, ye.",note:"كُلِي — ayolga qaratilgan ye buyrug‘i; erkakka كُلْ deyiladi."},
{num:511,time:"00:38:08,300 --> 00:38:14,140",arabic:"مَا بِكِ؟ لِمَ لَا تَرُدِّينَ؟ مُنْذُ غَادَرَنَا الرَّجُلُ وَأَنْتِ عَلَى صَمْتِكِ هَذَا.",segs:[{ar:"مَا بِكِ؟",uz:"Senga nima bo‘ldi?"},{ar:"لِمَ لَا تَرُدِّينَ؟",uz:"Nega javob bermayapsan?"},{ar:"مُنْذُ غَادَرَنَا الرَّجُلُ",uz:"U kishi ketganidan beri"},{ar:"وَأَنْتِ عَلَى صَمْتِكِ هَذَا.",uz:"shunday jim o‘tiribsan."}],full_uz:"Senga nima bo‘ldi? Nega javob bermayapsan? U kishi ketganidan beri shunday jim o‘tiribsan.",note:"لِمَ — لِمَاذَا ning qisqa shakli. عَلَى صَمْتِكِ — sukut saqlagan holingda."},
{num:512,time:"00:38:14,140 --> 00:38:19,519",arabic:"أَلَنْ تُخْبِرِينِي بِمَا دَارَ بَيْنَكُمَا مِنْ حَدِيثٍ؟",segs:[{ar:"أَلَنْ تُخْبِرِينِي",uz:"Menga aytmaysanmi"},{ar:"بِمَا دَارَ بَيْنَكُمَا",uz:"ikkovingiz o‘rtasida bo‘lib o‘tgan"},{ar:"مِنْ حَدِيثٍ؟",uz:"suhbat haqida?"}],full_uz:"Ikkovingiz nima haqda gaplashganingizni menga aytmaysanmi?",note:"دَارَ بَيْنَهُمَا حَدِيثٌ — ular o‘rtasida suhbat bo‘ldi. بَيْنَكُمَا — ikkovingiz o‘rtangizda."},
{num:513,time:"00:38:19,519 --> 00:38:26,200",arabic:"يَبْدُو أَنَّكِ قَدْ خَرِسْتِ وَلَا فَائِدَةَ مِنَ الْحَدِيثِ مَعَكِ.",segs:[{ar:"يَبْدُو أَنَّكِ قَدْ خَرِسْتِ",uz:"Aftidan, tiling yo‘qolib qolganga o‘xshaydi"},{ar:"وَلَا فَائِدَةَ",uz:"va foyda yo‘q"},{ar:"مِنَ الْحَدِيثِ مَعَكِ.",uz:"sen bilan gaplashishdan."}],full_uz:"Aftidan, tiling yo‘qolib qolgan. Sen bilan gaplashishdan foyda yo‘q.",note:"خَرِسَ — soqov bo‘lib qolmoq; bu yerda gapirmay qo‘ygan kishiga nisbatan aytilgan."},
{num:514,time:"00:38:26,200 --> 00:38:30,300",arabic:"مَتَى سَيَأْتِي الْيَوْمُ الَّذِي أَرْتَاحُ فِيهِ مِنْكِ؟",segs:[{ar:"مَتَى سَيَأْتِي الْيَوْمُ",uz:"Qachon keladi o‘sha kun"},{ar:"الَّذِي أَرْتَاحُ فِيهِ مِنْكِ؟",uz:"sendan qutulib tinchiydigan?"}],full_uz:"Sendan qutulib tinchiydigan kunim qachon keladi?",note:"ارْتَاحَ مِنْ — ...dan qutulib tinchimoq. ارْتَاحَ إِلَى esa ko‘ngli tortmoq degani."},
{num:515,time:"00:38:38,300 --> 00:38:49,080",arabic:"هَلْ سَيَعُودُ؟",segs:null,full_uz:"U qaytarmikan?",note:null},
{num:516,time:"00:38:49,080 --> 00:38:50,120",arabic:"لَا أَظُنُّ.",segs:null,full_uz:"Bunday deb o‘ylamayman.",note:null},
{num:517,time:"00:38:50,120 --> 00:38:56,620",arabic:"لِمَاذَا سَيَعُودُ؟",segs:null,full_uz:"Nega qaytsin?",note:"Savol bu yerda qaytish uchun sabab yo‘qligini ifodalaydi."},
{num:518,time:"00:38:56,620 --> 00:38:58,620",arabic:"لَا عَاقِلَ يَقْبَلُ مَا اشْتَرَطْتُ عَلَيْهِ.",segs:[{ar:"لَا عَاقِلَ يَقْبَلُ",uz:"Hech bir aqli raso kishi qabul qilmaydi"},{ar:"مَا اشْتَرَطْتُ عَلَيْهِ.",uz:"unga qo‘ygan shartimni."}],full_uz:"Hech bir aqli raso kishi unga qo‘ygan shartimni qabul qilmaydi.",note:"عَاقِلٌ — aqli raso kishi. اشْتَرَطَ عَلَيْهِ — unga shart qo‘ydi."},
{num:519,time:"00:38:58,620 --> 00:39:01,720",arabic:"وَلَكِنْ مَعَ ذَلِكَ لَنْ أَفْقِدَ الْأَمَلَ.",segs:[{ar:"وَلَكِنْ مَعَ ذَلِكَ",uz:"Lekin shunga qaramay"},{ar:"لَنْ أَفْقِدَ الْأَمَلَ.",uz:"umidimni yo‘qotmayman."}],full_uz:"Lekin shunga qaramay, umidimni yo‘qotmayman.",note:"مَعَ ذَلِكَ — shunga qaramay; فَقَدَ الْأَمَلَ — umidini yo‘qotmoq."},
{num:520,time:"00:39:01,720 --> 00:39:04,420",arabic:"رُبَّمَا يَعُودُ.",segs:null,full_uz:"Balki qaytar.",note:null},
{num:521,time:"00:39:06,300 --> 00:39:09,260",arabic:"فَرِّجْ عَنِّي مَا أَنَا فِيهِ.",segs:[{ar:"فَرِّجْ عَنِّي",uz:"Meni xalos qil"},{ar:"مَا أَنَا فِيهِ.",uz:"ichida qolgan bu holatimdan."}],full_uz:"Meni tushib qolgan bu kulfatimdan xalos qil.",note:"فَرَّجَ عَنْهُ — uning g‘amini aritdi, qiyinchiligini yengillashtirdi."},
{num:522,time:"00:39:10,820 --> 00:39:14,360",arabic:"سَأَفْتَحُ بَيْتًا جَدِيدًا.",segs:null,full_uz:"Yangi ro‘zg‘or ochaman.",note:"فَتَحَ بَيْتًا — ko‘chma ma’noda ro‘zg‘or qurmoq, alohida uy tutmoq."},
{num:523,time:"00:39:14,360 --> 00:39:15,660",arabic:"هَذِهِ الْأَغْرَاضُ تَلْزَمُنِي.",segs:null,full_uz:"Bu buyumlar menga kerak.",note:"تَلْزَمُنِي — menga kerak bo‘ladi. أَغْرَاضٌ — buyumlar, narsalar."},
{num:524,time:"00:39:15,660 --> 00:39:17,340",arabic:"السَّلَامُ عَلَيْكُمْ.",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:525,time:"00:39:17,340 --> 00:39:28,820",arabic:"أَخَفْتَنِي يَا رَجُلُ!",segs:[{ar:"أَخَفْتَنِي",uz:"Meni qo‘rqitib yubording"},{ar:"يَا رَجُلُ!",uz:"ey birodar!"}],full_uz:"Meni qo‘rqitib yubording-ku, birodar!",note:"أَخَافَ — qo‘rqitmoq; خَافَ — qo‘rqmoq."},
{num:526,time:"00:39:28,820 --> 00:39:30,740",arabic:"مَا لَكَ مُسْتَعْجِلًا هَكَذَا؟",segs:[{ar:"مَا لَكَ مُسْتَعْجِلًا",uz:"Nega shoshilyapsan"},{ar:"هَكَذَا؟",uz:"bunchalik?"}],full_uz:"Nega bunchalik shoshilyapsan?",note:"مُسْتَعْجِلًا — shoshilgan holda; hol vazifasida tushum kelishigida."},
{num:527,time:"00:39:30,740 --> 00:39:31,720",arabic:"لَدَيَّ عَمَلٌ.",segs:null,full_uz:"Ishim bor.",note:"لَدَيَّ — menda bor; egalik yoki mavjudlikni bildiradi."},
{num:528,time:"00:39:31,720 --> 00:39:33,240",arabic:"عَمَلٌ؟",segs:null,full_uz:"Ish?",note:null},
{num:529,time:"00:39:33,239 --> 00:39:40,779",arabic:"وَقُلِ اعْمَلُوا فَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ،",segs:[{ar:"وَقُلِ اعْمَلُوا",uz:"Ayting: amal qilinglar"},{ar:"فَسَيَرَى اللَّهُ عَمَلَكُمْ",uz:"Alloh amalingizni ko‘radi"},{ar:"وَرَسُولُهُ وَالْمُؤْمِنُونَ،",uz:"Uning Rasuli va mo‘minlar ham,"}],full_uz:"Ayting: amal qilinglar, Alloh, Uning Rasuli va mo‘minlar amalingizni ko‘radilar,",note:"اعْمَلُوا — ko‘pchilikka qaratilgan amal qilinglar buyrug‘i. سَيَرَى — ko‘radi."},
{num:530,time:"00:39:40,779 --> 00:39:43,579",arabic:"وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ،",segs:[{ar:"وَسَتُرَدُّونَ",uz:"Va qaytarilursizlar"},{ar:"إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ،",uz:"g‘ayb va oshkorani Biluvchiga,"}],full_uz:"G‘ayb va oshkorani Biluvchiga qaytarilursizlar,",note:"تُرَدُّونَ — majhul nisbat: qaytarilasizlar. الْغَيْبُ — yashirin; الشَّهَادَةُ — oshkor, ko‘rinadigan olam."},
{num:531,time:"00:39:43,579 --> 00:39:46,839",arabic:"فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ.",segs:[{ar:"فَيُنَبِّئُكُمْ",uz:"So‘ng U sizlarga xabar beradi"},{ar:"بِمَا كُنْتُمْ تَعْمَلُونَ.",uz:"qilib yurgan ishlaringiz haqida."}],full_uz:"So‘ng U sizlarga qilib yurgan ishlaringiz haqida xabar beradi.",note:"نَبَّأَ — xabar bermoq. كُنْتُمْ تَعْمَلُونَ — qilib yurgan edingiz."},
{num:532,time:"00:39:46,839 --> 00:39:48,239",arabic:"مَاذَا بَعْدُ؟",segs:null,full_uz:"Yana nima?",note:"مَاذَا بَعْدُ؟ — keyin-chi, yana nima?"},
{num:533,time:"00:39:50,019 --> 00:39:53,739",arabic:"يَعْلَمُ خَائِنَةَ الْأَعْيُنِ وَمَا تُخْفِي الصُّدُورُ.",segs:[{ar:"يَعْلَمُ خَائِنَةَ الْأَعْيُنِ",uz:"U ko‘zlarning xiyonatkor qarashlarini biladi"},{ar:"وَمَا تُخْفِي الصُّدُورُ.",uz:"va ko‘ksilar yashirgan narsalarni."}],full_uz:"U ko‘zlarning xiyonatkor qarashlarini va ko‘ksilar yashirgan narsalarni biladi.",note:"تُخْفِي — yashiradi; أَخْفَى fe’lidan. الصُّدُورُ — ko‘ksilar, bu yerda insonning ichki o‘ylarini anglatadi."},
{num:534,time:"00:39:53,739 --> 00:39:55,239",arabic:"مَاذَا تَقْصِدُ؟",segs:null,full_uz:"Nimani nazarda tutyapsan?",note:null},
{num:535,time:"00:39:55,959 --> 00:39:59,639",arabic:"لَا تَنْقُصُكَ الْفِطْنَةُ يَا ابْنَ أُمِّ فَرَجٍ.",segs:[{ar:"لَا تَنْقُصُكَ الْفِطْنَةُ",uz:"Senga farosat yetishmayotgani yo‘q"},{ar:"يَا ابْنَ أُمِّ فَرَجٍ.",uz:"ey Umm Farajning o‘g‘li."}],full_uz:"Senga farosat yetishmayotgani yo‘q, ey Umm Farajning o‘g‘li.",note:"فِطْنَةٌ — fahm-farosat, tez anglash qobiliyati. لَا تَنْقُصُكَ — senda kam emas."},
{num:536,time:"00:40:03,239 --> 00:40:12,359",arabic:"بَلْ يَنْقُصُنِي الْكَثِيرُ.",segs:null,full_uz:"Aksincha, menga ko‘p narsa yetishmaydi.",note:"بَلْ oldingi fikrni rad etib, uning o‘rniga boshqa fikrni keltiradi."},
{num:537,time:"00:40:12,359 --> 00:40:21,859",arabic:"أَرْسَلْتَ فِي طَلَبِي؟",segs:null,full_uz:"Meni chaqirtirdingizmi?",note:"أَرْسَلَ فِي طَلَبِ فُلَانٍ — birovni chaqirtirmoq, uning ortidan odam yubormoq."},
{num:538,time:"00:40:21,859 --> 00:40:26,619",arabic:"مَا زِلْتُ أَنْتَظِرُ مِنْكَ أَخْبَارًا.",segs:[{ar:"مَا زِلْتُ أَنْتَظِرُ",uz:"Hali ham kutyapman"},{ar:"مِنْكَ أَخْبَارًا.",uz:"sendan xabarlar."}],full_uz:"Hali ham sendan xabar kutyapman.",note:"مَا زِلْتُ — men hali ham; ish-harakatning davom etayotganini bildiradi."},
{num:539,time:"00:40:26,619 --> 00:40:28,099",arabic:"لَقَدْ نَقَلْتُ إِلَيْكَ كُلَّ مَا سَمِعْتُ.",segs:[{ar:"لَقَدْ نَقَلْتُ إِلَيْكَ",uz:"Sizga yetkazdim"},{ar:"كُلَّ مَا سَمِعْتُ.",uz:"eshitganlarimning hammasini."}],full_uz:"Eshitganlarimning hammasini sizga yetkazdim.",note:"نَقَلَ إِلَيْهِ خَبَرًا — unga xabar yetkazdi."},
{num:540,time:"00:40:28,099 --> 00:40:29,000",arabic:"ادْخُلْ.",segs:null,full_uz:"Kir.",note:null},
{num:541,time:"00:40:29,000 --> 00:40:39,179",arabic:"اسْمَعْ، كُلُّ مَا نَقَلْتَهُ لِي لَا أَهَمِّيَّةَ لَهُ.",segs:[{ar:"اسْمَعْ،",uz:"Eshit,"},{ar:"كُلُّ مَا نَقَلْتَهُ لِي",uz:"menga yetkazgan barcha narsang"},{ar:"لَا أَهَمِّيَّةَ لَهُ.",uz:"hech qanday ahamiyatga ega emas."}],full_uz:"Eshit, menga yetkazgan narsalaringning hech qanday ahamiyati yo‘q.",note:"لَا أَهَمِّيَّةَ لَهُ — uning ahamiyati yo‘q."},
{num:542,time:"00:40:39,179 --> 00:40:42,139",arabic:"مَا كَلَّفْتُكَ بِهِ لَيْسَ بِالْأَمْرِ السَّهْلِ.",segs:[{ar:"مَا كَلَّفْتُكَ بِهِ",uz:"Senga topshirgan vazifam"},{ar:"لَيْسَ بِالْأَمْرِ السَّهْلِ.",uz:"oson ish emas."}],full_uz:"Senga topshirgan vazifam oson ish emas.",note:"كَلَّفَهُ بِـ — unga vazifa yuklamoq. لَيْسَ بِـ tarkibidagi بِ inkorni kuchaytiradi."},
{num:543,time:"00:40:42,139 --> 00:40:46,599",arabic:"إِنْ كُنْتَ لَا تَسْتَطِيعُ تَصَيُّدَ الْأَخْبَارِ الْمُهِمَّةِ،",segs:[{ar:"إِنْ كُنْتَ لَا تَسْتَطِيعُ",uz:"Agar uddalay olmasang"},{ar:"تَصَيُّدَ الْأَخْبَارِ الْمُهِمَّةِ،",uz:"muhim xabarlarni izlab topishni,"}],full_uz:"Agar muhim xabarlarni izlab topishni uddalay olmasang,",note:"تَصَيُّدٌ — ovlash; xabarga nisbatan uni astoydil izlab topish ma’nosida."},
{num:544,time:"00:40:46,599 --> 00:40:49,000",arabic:"فَدَعْنِي أَبْحَثْ عَنْ بَدِيلٍ لَكَ.",segs:[{ar:"فَدَعْنِي أَبْحَثْ",uz:"unda menga izlashga qo‘y"},{ar:"عَنْ بَدِيلٍ لَكَ.",uz:"sening o‘rningga boshqasini."}],full_uz:"Unda sening o‘rningga boshqasini izlashimga qo‘y.",note:"بَدِيلٌ — o‘rnini bosuvchi. أَبْحَثْ buyruqning natijasi bo‘lgani uchun jazmda kelgan."},
{num:545,time:"00:40:49,000 --> 00:40:54,320",arabic:"فَهُنَاكَ الْكَثِيرُ يَنْتَظِرُ أَنْ يَخْدُمَ أَمْنَ هَذِهِ الْبِلَادِ.",segs:[{ar:"فَهُنَاكَ الْكَثِيرُ يَنْتَظِرُ",uz:"Chunki kutayotganlar ko‘p"},{ar:"أَنْ يَخْدُمَ أَمْنَ هَذِهِ الْبِلَادِ.",uz:"bu yurt xavfsizligiga xizmat qilishni."}],full_uz:"Chunki bu yurt xavfsizligiga xizmat qilishni kutayotganlar ko‘p.",note:"أَمْنٌ — xavfsizlik, osoyishtalik."},
{num:546,time:"00:40:54,320 --> 00:40:57,599",arabic:"وَمِنْ أَيْنَ آتِيكَ بِالْأَخْبَارِ الْمُهِمَّةِ؟",segs:[{ar:"وَمِنْ أَيْنَ آتِيكَ",uz:"Sizga qayerdan olib kelay"},{ar:"بِالْأَخْبَارِ الْمُهِمَّةِ؟",uz:"muhim xabarlarni?"}],full_uz:"Sizga muhim xabarlarni qayerdan olib kelay?",note:"أَتَاهُ بِشَيْءٍ — unga biror narsani olib keldi."},
{num:547,time:"00:40:57,599 --> 00:41:01,599",arabic:"أَتُرِيدُنِي أَنْ أَخْتَلِقَهَا وَأَظْلِمَ النَّاسَ؟",segs:[{ar:"أَتُرِيدُنِي أَنْ أَخْتَلِقَهَا",uz:"Ularni to‘qib chiqarishimni istaysizmi"},{ar:"وَأَظْلِمَ النَّاسَ؟",uz:"va odamlarga zulm qilishimni?"}],full_uz:"Xabarlarni to‘qib chiqarib, odamlarga zulm qilishimni istaysizmi?",note:"اخْتَلَقَ — yolg‘on narsani to‘qib chiqarmoq."},
{num:548,time:"00:41:01,599 --> 00:41:04,599",arabic:"الْأَخْبَارُ لَا تَسْعَى، بَلْ يُسْعَى إِلَيْهَا.",segs:[{ar:"الْأَخْبَارُ لَا تَسْعَى،",uz:"Xabarlar o‘zi kelmaydi,"},{ar:"بَلْ يُسْعَى إِلَيْهَا.",uz:"balki ular izlab boriladi."}],full_uz:"Xabarlar o‘zi kelmaydi, ularni izlab borish kerak.",note:"تَسْعَى — harakat qiladi, intiladi; يُسْعَى — majhul nisbat. So‘z o‘yini orqali izlanish zarurati aytilgan."},
{num:549,time:"00:41:04,599 --> 00:41:10,599",arabic:"فَتِّشْ عَنْهَا، وَمَنْ لَا يُرِيدُ الْحَدِيثَ اسْتَدْرِجْهُ لِيَبُوحَ بِمَا يُخْفِي.",segs:[{ar:"فَتِّشْ عَنْهَا،",uz:"Ularni izla,"},{ar:"وَمَنْ لَا يُرِيدُ الْحَدِيثَ",uz:"gapirishni istamagan kishini esa"},{ar:"اسْتَدْرِجْهُ",uz:"asta-sekin gapga sol"},{ar:"لِيَبُوحَ",uz:"ochiq aytishi uchun"},{ar:"بِمَا يُخْفِي.",uz:"yashirayotgan narsasini."}],full_uz:"Xabarlarni izla. Gapirishni istamagan kishini yashirayotgan narsasini aytishga asta-sekin unda.",note:"اسْتَدْرَجَهُ — uni asta-sekin maqsadiga tomon og‘dirdi. بَاحَ بِـ — sirini ochiq aytdi."},
{num:550,time:"00:41:11,599 --> 00:41:15,599",arabic:"أَنْتَ شَابٌّ ذَكِيٌّ وَلَا تَنْقُصُكَ الْفِطْنَةُ.",segs:[{ar:"أَنْتَ شَابٌّ ذَكِيٌّ",uz:"Sen aqlli yigitsan"},{ar:"وَلَا تَنْقُصُكَ الْفِطْنَةُ.",uz:"farosating ham kam emas."}],full_uz:"Sen aqlli yigitsan, farosating ham kam emas.",note:"ذَكِيٌّ — aqlli, ziyrak; الْفِطْنَةُ — fahm-farosat."},
{num:551,time:"00:41:16,599 --> 00:41:18,599",arabic:"سَأُحَاوِلُ.",segs:null,full_uz:"Harakat qilaman.",note:null},
{num:552,time:"00:41:19,599 --> 00:41:23,599",arabic:"عَمَّا قَرِيبٍ سَتَسْمَعُ مِنِّي مَا يَسُرُّكَ.",segs:[{ar:"عَمَّا قَرِيبٍ",uz:"Yaqin orada"},{ar:"سَتَسْمَعُ مِنِّي",uz:"mendan eshitasiz"},{ar:"مَا يَسُرُّكَ.",uz:"sizni xursand qiladigan narsani."}],full_uz:"Yaqin orada mendan sizni xursand qiladigan xabar eshitasiz.",note:"عَمَّا قَرِيبٍ — yaqin orada. سَرَّهُ — uni xursand qildi."},
{num:553,time:"00:41:23,599 --> 00:41:25,519",arabic:"هَيَّا عُدْ لِعَمَلِكَ.",segs:null,full_uz:"Qani, ishingga qayt.",note:"عُدْ — qayt; عَادَ يَعُودُ fe’lidan."},
{num:554,time:"00:41:25,519 --> 00:41:28,360",arabic:"وَأَنَا أَنْتَظِرُ مِنْكَ أَخْبَارًا.",segs:[{ar:"وَأَنَا أَنْتَظِرُ",uz:"Men esa kutaman"},{ar:"مِنْكَ أَخْبَارًا.",uz:"sendan xabarlar."}],full_uz:"Men esa sendan xabar kutaman.",note:null}
];

if (typeof module !== "undefined" && module.exports) {
    module.exports = lessons;
}
